[32783] = { ["id"] = 32783, ["name"] = "Ga'nar's Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "My brother's head is as thick as his axe and he is as stubborn as a gronn. When Ga'nar left he took with him some of the finest warriors in the clan and headed north to the Daggermaw Ravine. If they are still out there, you must find them. Ga'nar will not listen to me. Help him see his vengeance through if you must but please bring him back to us.", ["objectivesText"] = "Find Ga'nar near Daggermaw Ravine.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70909, ["x"] = 0.308, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[32791] = { ["id"] = 32791, ["name"] = "Let the Hunt Begin!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "I have no time for my brother's whimpering. We hunt for vengeance or death. The Thunderlord chieftain slew my father and left me for dead, so I shall take his three sons, the first of which is this runt in my hand. This filth has revealed the number and positions of the Thunderlords in the ravine beyond. Join us, if you dare, and you will witness how real warriors of the Frostwolf clan fight. Get in my way, and I will end you.", ["objectivesText"] = "Confront Grotan the Herald.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70909, ["x"] = 0.308, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74000, ["x"] = 0.36, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[32792] = { ["id"] = 32792, ["name"] = "Leave Nothing Behind!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32791, 32794, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "The Thunderlord clan has become a thorn in my side I will no longer tolerate. Go east and leave none alive! Burn their supplies! Leave them nothing to cling to. Converge on the Savage Crag to the east when it is done.", ["objectivesText"] = "Kill Kur'ak the Binder , burn the Thunderlord Supplies , and destroy the Thunderlord Ballistae.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 111917, 111918, 117505, 117506, 117507, 117508 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74000, ["x"] = 0.36, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70910, ["x"] = 0.464, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[32794] = { ["id"] = 32794, ["name"] = "Wrath of Gronn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32791, 32792, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "The Thunderlord are capturing gronn for the Iron Horde. Show these fools why gronn are NOT pets. Follow us into Grulloc's Grotto and sunder the chains of the captive gronn . Let the beasts seek to gain their own vengeance against the Thunderlord. Meet us at Grulloc's Lair beneath the grotto when you are done.", ["objectivesText"] = "Release 3 Captive Gronn .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70910, ["x"] = 0.464, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[32795] = { ["id"] = 32795, ["name"] = "The Eldest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 532, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32791, 32792, 32794, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "There is Hatock, last and eldest son of the Iron Wolf. One of the greatest hunters the Thunderlord have ever fielded. He was there when his father murdered my father and left me for dead. When I am done with him he will regret not finishing the job.", ["objectivesText"] = "Help Ga'nar win his vengeance.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 117501, 117502, 117503, 117504, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 532, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 4, ["flags"] = 0 } } },
[32796] = { ["id"] = 32796, ["name"] = "To the Garrison", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "My father is avenged. The sons of the Iron Wolf are all slain. Go to the garrison your people are constructing in the south. There, herald my return to my laggard brother. The time has come for the \"chieftain\" to be reminded of what it means to be a Frostwolf.", ["objectivesText"] = "Meet with Durotan in front of your garrison in Frostfire Ridge .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 5, ["flags"] = 0 } } },
