[33359] = { ["id"] = 33359, ["name"] = "Meet Us at Starfall Outpost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 33062, 33066, 33112, 33114, 33115, 33116, 33168, 33359 }, ["series"] = { 33062, 33066, 33112, 33115 }, ["description"] = "The archmage has uncovered a potential Shadow Council presence in the valley. He asked me to let you know. As soon as you can, join us at Starfall Outpost. We're going to need your muscle to root them out, commander.", ["objectivesText"] = "Speak with Archmage Khadgar at Starfall Outpost.", ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77184, ["x"] = 0.292, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 59, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 0, ["flags"] = 0 } } },
