[33444] = { ["id"] = 33444, ["name"] = "Eatercology", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32979, 32980, 32983, 32984, 32985, 33427, 33444 }, ["series"] = { 32979, 32980, 32983, 32984, 32985, 33427 }, ["description"] = "Drek'Thar thinks the portions of Exurotus consumed by the goren might be worthless. I am not about to step before the fury without at least trying to recover as many of these \"motes\" as possible. Slay any goren you find at Magnarok and see if you can extract the motes of Frostfire from them.", ["objectivesText"] = "Collect 10 Motes of Frostfire . Progress: Have you had any luck recovering those motes?", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 102091, 119145 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72230, ["x"] = 0.6465, ["y"] = 0.3765 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72230, ["x"] = 0.6465, ["y"] = 0.3765 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.6465, ["y"] = 0.3765 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 117, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[33454] = { ["id"] = 33454, ["name"] = "The Cure", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33454 }, ["series"] = { 33412, 33450 }, ["description"] = "Cowards! A curse on these wretched meatbags! The Bladespire have always taunted the orc clans by taking our wounded as slaves to fight like dogs in their pits. In retaliation for our assault they have poisoned their orc prisoners, leaving them to suffer and die an excruciating death. Only their geomancers carry the antidote, traveler. Use it to cure the Frostwolf prisoners.", ["objectivesText"] = "Cure 5 Frostwolf Gladiators .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 52583, 52619, 52631, 106958, 118931, 158258, 158259, 158260, 158261, 160097, 160098, 160099, 160100, 182487, 182496, 182505, 182514, 183744, 184843, 237812 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74635, ["x"] = 0.244, ["y"] = 0.287 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74635, ["x"] = 0.244, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33461] = { ["id"] = 33461, ["name"] = "Gloomshade Game Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33263, 33271, 33331, 33461, 34806, 34820 }, ["description"] = "<You find a list on a piece of parchment. Arsenio needs some ingredients for a new recipe he's preparing at your garrison.>", ["objectivesText"] = "Collect ingredients in Gloomshade Grove. Progress: Did you find all the ingredients I need?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 111884, 111885, 111888 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79966, ["x"] = 0.3955, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.3955, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 45, ["name"] = "Ending the Gloom", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33467] = { ["id"] = 33467, ["name"] = "The Fall of the Warlord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33467 }, ["description"] = "You've managed to survive this long, stranger. All that remains to be done here is to fell the Warlord of the arena. This will be your first true test here. Bult would provide a challenge to even a battle-hardened Frostwolf. Place the heads you've collected on spikes in the Frostfire Arena. They are sure to enrage the warlord and lure him into battle. Come out of the arena victorious and it will show that Durotan's trust in you was not misplaced.", ["objectivesText"] = "Kill Warlord Bult . Progress: Yes, traveler?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 108735, 117982, 117983, 117984 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74635, ["x"] = 0.244, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33468] = { ["id"] = 33468, ["name"] = "Save Wolf Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33469, 33470, 33473, 33807 }, ["description"] = "Cowardly Thunderlords... During the battle for the citadel, runners informed me that the Iron Wolf is striking at our home. He'll find no easy footing there, Draka will make them pay tenfold for any of ours that they slay, but we must return quickly and chase the mongrels off. You and your forces have proven valuable allies of the Frostwolves. We'd welcome your aid in securing our Wor'gol. I'll see you on the battlefield if you choose to come.", ["objectivesText"] = "Save Wor'gol from the Thunderlord clan. Progress: There are more Thunderlord to be killed.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74651, ["x"] = 0.208, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33469] = { ["id"] = 33469, ["name"] = "The Farseer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33470, 33473, 33807 }, ["description"] = "The Thunderlord warleader... <name>, you have to stop him. He went to attack Drek'Thar at the Pool of Visions to the northwest!", ["objectivesText"] = "Get to the Pool of Visions and kill Warleader Gargrak . Progress: Wolf Home will not be safe until this coward is dead!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74651, ["x"] = 0.208, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.208, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33470] = { ["id"] = 33470, ["name"] = "Pool of Visions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33473, 33807 }, ["description"] = "A terrible storm gathers on the horizon, <class>. I have prepared a ritual. You must consult the pool to see what destiny holds for us all.", ["objectivesText"] = "Speak with Farseer Drek'Thar at the Pool of Visions to begin the ritual of vision.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 106141, 106152, 106162, 106173, 244320 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33473] = { ["id"] = 33473, ["name"] = "Back to Bladespire Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33473 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33807 }, ["description"] = "Durotan must be told of your vision. Pul Windcarver will offer you a flight back. The fate of the Frostwolf... of Draenor, depends upon you, <name>.", ["objectivesText"] = "Return to Durotan at Bladespire Citadel.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33483] = { ["id"] = 33483, ["name"] = "Mulverick's Plight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33483 }, ["series"] = { 33119, 33484 }, ["description"] = "You were sent here to free me? It seems that makes us allies. Slavemaster Turgall within the Soostained Mines will certainly have the key to this cage. While you're in there, do you think you could see which of those spineless taskmasters took my axes?", ["objectivesText"] = "Get the key from Slavemaster Turgall and find Mulverick's Axes . Progress: These ogres will be seeing the other side of my axes soon.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 107066, 107075, 108953, 108954, 108955 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72890, ["x"] = 0.308, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 79047, ["x"] = 0.306, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33484] = { ["id"] = 33484, ["name"] = "The Slavemaster's Demise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33484 }, ["series"] = { 33119, 33483 }, ["description"] = "Share word with the others of the Frostwolves you saved this day. They will be glad to know that some made it out of the mines alive.", ["objectivesText"] = "Speak to Guse at Bladespire Citadel.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 79047, ["x"] = 0.306, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33485] = { ["id"] = 33485, ["name"] = "Multiplayer Race", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 33485 }, ["description"] = "Run through the arch... Get to the blue marker... Get to the green marker... Get to the red marker Get to the purple marker Return here... Then do it all again. That's right - 2 laps! Good luck!", ["objectivesText"] = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp.", ["rewardGold"] = 234000, ["rewardXP"] = 300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33492] = { ["id"] = 33492, ["name"] = "Northshire Sprint Practice", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 33492 }, ["description"] = "Welcome to the Irongnome games! For this challenge: run through the arch... Get to the blue marker... Get to the green marker... then return here. You have all the time you need for this.", ["objectivesText"] = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.", ["rewardGold"] = 309800, ["rewardXP"] = 300, ["rewardItems"] = { 106952 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33493] = { ["id"] = 33493, ["name"] = "Return to the Pack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 33828, 37291 }, ["description"] = "Part of me agrees with Karg - we COULD challenge the Iron Wolf right now. My fists clench at the mention of his name. My muscles scream for vengeance. But then, in my heart, I feel Asha. Calming me. Guiding me. I do not deserve her wisdom, but it is a gift I will not waste. <Lokra squints at the sky.> Durotan and the others will be gathering at your garrison about now. We should meet them.", ["objectivesText"] = "Speak with Durotan at your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 110560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 9, ["flags"] = 0 } } },
