[33928] = { ["id"] = 33928, ["name"] = "A Wrong of Earth and Fire", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 33928 }, ["description"] = "The molten core appears to be the mutated remains of an elemental that consisted of both earth and fire. Slag elementals should not exist upon the plateau where the elements live in purity. You decide that the core should be taken to Incineratus at the Throne of Elements for examination. Perhaps the great fury of fire will know what to make of this core and your battle with Magmire.", ["objectivesText"] = "Deliver the Molten Core to Incineratus .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113080 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80593, ["x"] = 0.714, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["startItems"] = { 113080 } },
[33929] = { ["id"] = 33929, ["name"] = "Shivertail's Den", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33929 }, ["series"] = { 33955 }, ["description"] = "The Frostwolf pup looks at you with his big eyes. He howls and stares into the cave. It's unusual for a wolf this young to be wandering around by itself. Shivertail 's parents must be nearby.", ["objectivesText"] = "Search for Shivertail 's parents in Frostfire Ridge . Progress: Shivertail smells your boots.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76889, ["x"] = 0.195, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76889, ["x"] = 0.195, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.195, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
