[34012] = { ["id"] = 34012, ["name"] = "Need More Teeth", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "< Prowler Sasha silently holds out his hand to reveal a necklace crafted of stained leather and putrid brown ogre teeth. All have a matching tone of rot to them.> <It has several knots that appear to be missing additional teeth.>", ["objectivesText"] = "Collect 30 Putrid Brown Ogre Teeth. Progress: < Prowler Sasha stares at you with cold, merciless eyes.>", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 108898 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75008, ["x"] = 0.414, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75008, ["x"] = 0.414, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34013] = { ["id"] = 34013, ["name"] = "Never Forget", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "We had to escape Telmor with what few we could save. Someone disabled Leafshadow 's cloaking field; I know not who, but I suspect it had to have been one of our own. We will retrieve our livelihoods in time, but we cannot risk losing our sacred artifacts. If you are able, bring Leafshadow , our town registry, and our prayerbook to safety.", ["objectivesText"] = "Recover the Telmor Registry , the Auchenai Prayerbook , and Leafshadow in Telmor. Progress: Some things are worth fighting for, <race>. These are such things.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78083, ["x"] = 0.504667, ["y"] = 0.874667 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78083, ["x"] = 0.504667, ["y"] = 0.874667 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.504667, ["y"] = 0.874667 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 13, ["flags"] = 0 } }, ["startItems"] = { 108951 } },
[34019] = { ["id"] = 34019, ["name"] = "Shadows Awaken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33080, 33081, 33765, 33814, 33905, 36592 }, ["description"] = "We've managed to pin Ner'zhul inside the Observatory, but he's taken many down with him. He has taken Yrel's sister, Samaara. I am needed to hold the line here. Please, do whatever you can to save her, hero.", ["objectivesText"] = "Confront Ner'zhul. Progress: The Shadowmoon clan's aggression began when the Iron Horde arrived on Draenor.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 106167, 107308, 107313, 107318, 113103, 114877, 114972, 114984, 115278, 115281, 115343, 115507 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.490667, ["y"] = 0.381333 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34026] = { ["id"] = 34026, ["name"] = "Garrison Campaign: Seismic Matters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["description"] = "One of our junior surveyors has been harassing me about unusual seismic activity. I find it hard to believe that we accidentally built on some kind of fault line - we triple checked! Can you have a word with him?", ["objectivesText"] = "Speak with Jr. Surveyor Dorn at your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34027] = { ["id"] = 34027, ["name"] = "Groundbreaking Data", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["description"] = "Aye, we triple-checked the site before we set up here. Nary a peep from the ol' earthly deep. But there's been rumblin's today, and they're gettin' closer! I tell ya somethin' ain't right! Ye don't have to take my word for it - the Tremor-Tracker is just about finished collecting data. Check it out an' see fer yerself!", ["objectivesText"] = "Use the Tremor-Tracker in your garrison. Progress: Go on, check out the Tremor-Tracker ! It ain't gonna bite ye.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34028] = { ["id"] = 34028, ["name"] = "These Look Familiar...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34029, 34030, 34031, 34032, 34033, 34048 }, ["description"] = "So what is the Iron Horde doing with Dark Iron technology? I know who ta ask! Thaelin Darkanvil is a genius engineer from the Dark Iron clan who's been helping us here on Draenor. You may have already met him in yer travels, eh? Word is he set up a bunker somewhere in Gorgrond, a secret workshop so-to-speak. If ye can find him, he may know somethin' about this. Er, and be cautious, eh? The Dark Iron may be our allies now, but I trust 'em about as far as I can throw 'em.", ["objectivesText"] = "Find Thaelin's Workshop in Gorgrond.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77160, ["x"] = 0.864, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34029] = { ["id"] = 34029, ["name"] = "The Prototype", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34028, 34030, 34031, 34032, 34033, 34048 }, ["description"] = "A few days ago a bunch of Iron Horde orcs showed up and kidnapped Thaelin. They've been keeping me alive as collateral to make sure he cooperates. I don't know where they took him, but I know how to get us there. Thaelin keeps a tracking device on him at all times - don't ask where he hides it. Anything he makes that can move has a \"Come to Papa\" button that sends it straight to him. In retrospect, not a great feature for the walking bombs... but perfect for the mole machine! Jump in and let's go!", ["objectivesText"] = "Use the Prototype Mole Machine to look for Thaelin Darkanvil.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 166846, 169610, 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467, 237812 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77160, ["x"] = 0.864, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77160, ["x"] = 0.864, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34030] = { ["id"] = 34030, ["name"] = "The Captive Engineer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34028, 34029, 34031, 34032, 34033, 34048 }, ["description"] = "Argh... I'm sorry, $p, but I'm too weak to fight. They kept me alive, but just barely. I'll keep an eye on the mole machine while you look for Thaelin. He should be somewhere close!", ["objectivesText"] = "Find Thaelin Darkanvil in the Iron Siegeworks.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77160, ["x"] = 0.864, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77161, ["x"] = 0.877333, ["y"] = 0.492667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34031] = { ["id"] = 34031, ["name"] = "Something to Remember Me By", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34028, 34029, 34030, 34032, 34033, 34048 }, ["description"] = "The Iron Horde want my inventions so bad? Then we'll leave some behind. These little beauties will blow the treads clear off a tank AND melt her chassis into the dirt. Let's see them try and drive their shoddy cannons out of this place!", ["objectivesText"] = "Place 4 Dark Iron Mines in the Iron Siegeworks. Progress: Don't be shy with those mines, I got plenty.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34032] = { ["id"] = 34032, ["name"] = "Privileged Information", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34033, 34048 }, ["description"] = "I'm not the only prize the Iron Horde brought back after raiding my workshop. Overlord Blackhammer, the maniac in charge of this operation, took my notebook as his own personal treasure. Manufacturing techniques; schematics for new inventions; embarrassing doodles. It's got all my secrets! Can I count on you to help me get it back?", ["objectivesText"] = "Loot Thaelin's Notebook from Overlord Blackhammer in the Iron Siegeworks. Progress: That book has my working notes from the last five years. It's too dangerous to leave behind!", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110453, 119359 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34033] = { ["id"] = 34033, ["name"] = "And The Mole You Rode In On", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34048 }, ["description"] = "I think we've kept Hansel waiting long enough. Can you take me to him? Then we can all hitch a ride out of here on the mole machine.", ["objectivesText"] = "Bring Thaelin Darkanvil to Hansel Heavyhands in the Iron Siegeworks.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77161, ["x"] = 0.877333, ["y"] = 0.492667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.877333, ["y"] = 0.492667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34034] = { ["id"] = 34034, ["name"] = "Garrison Campaign: Grinding Gears", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["series"] = { 34035, 34039, 34040, 34042, 34078 }, ["description"] = "Commanda! Da Frostwolf orcs at Thunder Pass have reported a horrible grinding noise boomin' tru da canyon. We suspect it's some kind of Iron Horde war machine. Gazlowe has agreed ta investigate, but he be wantin' a cash bonus. Goblins! Meet wit him at Thunder Pass and deliver dis payment.", ["objectivesText"] = "Deliver Gazlowe's Payment to Gazlowe near Thunder Pass. Progress: Yo! You got the dough?", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 109747 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77928, ["x"] = 0.813333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.813333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34035] = { ["id"] = 34035, ["name"] = "I Know The Drill!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["series"] = { 34034, 34039, 34040, 34042, 34078 }, ["description"] = "It's a machine alright. A drill - a BIG one! Fortunately, we don't have to take apart the whole thing. They're relying on forced induction, using twin superchargers to pipe extra boost into the engine. Without that boost, the drill is useless. Get in there and open the clutch on the back of the drill. That'll draw some attention away from the turbines. I'll take care of the turbines - you just worry about the hordes of bloodthirsty orcs.", ["objectivesText"] = "Help Gazlowe sabotage the Iron Stonegrinder. Progress: You ready to roll?", ["rewardGold"] = 58650, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77928, ["x"] = 0.813333, ["y"] = 0.523333 }, { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77928, ["x"] = 0.813333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.813333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34039] = { ["id"] = 34039, ["name"] = "WANTED: Overlord Blackhammer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["series"] = { 34034, 34035, 34040, 34042, 34078 }, ["description"] = "So, we COULD just leave now. We got what we came for, and I even did a little charity work to help Thaelin escape. But there's also this. <Gazlowe holds up a scrap of paper showing a hand-drawn depiction of an especially mean looking orc.> It's an SI:7 bounty for one Overlord Blackhammer , who just happens to operate out of this very facility. You help me take him out, I pay you. Then I take his head to the Alliance and collect on the bounty. Everyone wins! Well, everyone except for Blackhammer.", ["objectivesText"] = "Slay Overlord Blackhammer in the Iron Siegeworks. Progress: You aren't getting cold feet on me now, are ya?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34040] = { ["id"] = 34040, ["name"] = "Maker's Mark", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["series"] = { 34034, 34035, 34039, 34042, 34078 }, ["description"] = "I don't get it - most of the Iron Horde junk is about as advanced as strapping cannons to a gronn. Even the drill itself is nothing special. But that induction system was a work of art... This don't add up at all! Despite my better judgment, I gotta find out who made this. I wanna look at more of what they got in the Iron Siegeworks, see if anything's been signed. < Gazlowe pats the sack of coins on his belt.> Whaddaya say? Wanna be my bodyguard?", ["objectivesText"] = "Inspect 5 Siege Parts in the Iron Siegeworks. Progress: You get paid when we get out of this place alive.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77928, ["x"] = 0.813333, ["y"] = 0.523333 }, { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.813333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34041] = { ["id"] = 34041, ["name"] = "Four Finger Discount", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["description"] = "I gotta admit, establishing a supply chain to a primal world on the wrong side of time is tough, even for me. Gotta make due with, uh... \"locally sourced\" goods. Say what you want about the Iron Horde, but when it comes to raw materials, they got connections! Keep an eye out for some of the more valuable goods in the Iron Siegeworks. I packed a few rocket chickens we can use to send the good stuff back to your garrison.", ["objectivesText"] = "Steal a Blackrock Cog , Condensed Geyser Gas , and a Carbonfrost Flamecore from the Iron Siegeworks.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77928, ["x"] = 0.813333, ["y"] = 0.523333 }, { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.813333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34042] = { ["id"] = 34042, ["name"] = "A Fellow Gearhead", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["series"] = { 34034, 34035, 34039, 34040, 34078 }, ["description"] = "There's no way Thaelin sold out. NO way! They gotta be holdin' him here somewhere. Come on, $p. I know he's with the Alliance, and I know they aren't your favorite people, but we do NOT want the Iron Horde having access to his work - trust me!", ["objectivesText"] = "Find Thaelin Darkanvil in the Iron Siegeworks. Progress: You gotta respect your fellow gearheads! Plus, I made a TON of money copying those walking bombs he designed. Er... you didn't hear that last part.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34043] = { ["id"] = 34043, ["name"] = "Darkest Night", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 33082, 33586 }, ["description"] = "This keystone will grant its bearer entry into Anguish Fortress. Take it and meet Prophet Velen outside the Shadowmoon fortress. He intends to face Ner'zhul head-on.", ["objectivesText"] = "Speak to Prophet Velen at Anguish Fortress. Provided item:", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 112372 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 75884, ["x"] = 0.457, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34048] = { ["id"] = 34048, ["name"] = "\"Mole Machine, Go Home\"", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033, 34048 }, ["series"] = { 34026, 34027, 34028, 34029, 34030, 34031, 34032, 34033 }, ["description"] = "My patented \"Come to Papa\" voice command was only the first step. I also programmed all of my mole machines with a \"Go Home\" command that'll send 'em auto-diggin' to a pre-determined location - my workshop in Gorgrond! Let's send the mole machines home before the orcs stink 'em all up with their stupid breath and their sweaty... leather... thongs. <You hear Thaelin gagging a little from inside The Suit.> Blech!", ["objectivesText"] = "Send 5 Mole Machines home from the Iron Siegeworks. Progress: If the voice command fails, you can always try the manual override. Ye simply hold down the control pedal, shift into reverse, and pull the escape lever at the same time.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 70, ["name"] = "Garrison Campaign", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34054] = { ["id"] = 34054, ["name"] = "The Dark Side of the Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 35032 }, ["description"] = "< Prophet Velen 's voice continues.> Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress. Meet us there. We must stop him.", ["objectivesText"] = "Find Ner'zhul. Progress: Ner'zhul will pay for what he has done.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 106175, 107307, 107312, 107317, 110560, 237812 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.377 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34063] = { ["id"] = 34063, ["name"] = "Enemies Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34063 }, ["series"] = { 34066 }, ["description"] = "We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf <name>, but we can not rest yet. The Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us. I sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. Lok'tar <name>!", ["objectivesText"] = "Speak with Scout Ruk'gan near the Bones of Agurak.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34066] = { ["id"] = 34066, ["name"] = "Savage Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34066 }, ["series"] = { 34063 }, ["description"] = "The Thunderlord are a blight <name>. <Ruk'gan spits in disgust.> My daughter, Grishna, was killed by those monsters. Only their blood will bring me peace now. If you would help me then I need you to cause a distraction so I can sneak to a position closer to their camp. Killing a few of their so called \" Iron Thunderguard \" would be perfect.", ["objectivesText"] = "Kill 10 Iron Thunderguards within the Bones of Agurak in Frostfire Ridge .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 117509, 117510, 117511, 117512 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34067] = { ["id"] = 34067, ["name"] = "A Collection of Coils", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34067 }, ["description"] = "This coil of rope has been woven thick, the better for the Thunderlord Wranglers to handle the dangerous beasts they tame. Scout Ruk'gan might have a use for this and a few more like it.", ["objectivesText"] = "Gather 5 Coils of Sturdy Rope from Thunderlord Wranglers in the Bones of Agurak. Progress: I'm growing tired of waiting, do you have anything to help our assault or not?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109055 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["startItems"] = { 109121 } },
[34069] = { ["id"] = 34069, ["name"] = "Getting the Points", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34069 }, ["description"] = "The Thunderlord Spear is extremely light and strong. Scout Ruk'gan might be able to use this and a few more like it.", ["objectivesText"] = "Gather 5 Thunderlord Spears within the Bones of Agurak. Progress: What is it <class>? Have you got something for me?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109056 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["startItems"] = { 109095 } },
[34070] = { ["id"] = 34070, ["name"] = "At the End of Your Rope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34070 }, ["series"] = { 34072, 34073, 34075, 34102, 34264 }, ["description"] = "With the spears and rope you gathered the Thunderlord Sky Riders will no longer be out of our reach. Even they will feel our wrath! I've tied the rope to the spears you brought me to fashion a harpoon. Hunt the Sky Riders that are flying all over the valley. Take the Harpoon and throw it at them as they circle by. If your aim is true the barbs should allow the spear a firm hold allowing you to yank the rider right towards you! If your aim is bad... well... try not to miss.", ["objectivesText"] = "Use the Barbed Harpoon to unseat and kill 5 Thunderlord Sky Riders .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109082 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34072] = { ["id"] = 34072, ["name"] = "Tar Get of Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34072 }, ["series"] = { 34070, 34073, 34075, 34102, 34264 }, ["description"] = "General Vul'gath leads this band of Thunderlord. He is a coward and hides in his hut, yelling orders at his warriors through the walls. We will need to show him that his flimsy defenses can not stand against the Frostwolves! I'll need some tar to carry this out. There are a couple of tar pits to the south, go gather a few globs from the oozes that reside there and bring them to me.", ["objectivesText"] = "Gather 5 Globs of Sticky Tar from the Black Tar's in the Bones of Agurak. Progress: We need that tar soon <name>! Get to it!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109080 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34073] = { ["id"] = 34073, ["name"] = "Burn Them Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34073 }, ["series"] = { 34070, 34072, 34075, 34102, 34264 }, ["description"] = "Now, we begin our assault, <name>! Get down to Agurak's Fall and use these tarbombs to destroy their rylak egg incubators. While you are busy I will sneak down into their camp and prepare for the next phase of our attack. Meet me there once you have burned everything.", ["objectivesText"] = "Burn down the Thunderlord Rylak Incubators within Agurak's Fall.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109164 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34075] = { ["id"] = 34075, ["name"] = "Vul'gath's End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34075 }, ["series"] = { 34070, 34072, 34073, 34102, 34264 }, ["description"] = "Vul'gath's time has come to an end, <name>. My daughter's blood is upon his hands, now his blood will be on ours! Show no mercy and strike him down!", ["objectivesText"] = "Kill General Vul'gath within Agurak's Fall.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 117513, 117514, 117515, 117516 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34076] = { ["id"] = 34076, ["name"] = "The Burial Fields", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34076 }, ["objectivesText"] = "Orc spirits slain", ["rewardGold"] = 849000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Orc spirits slain", ["amount"] = 6, ["type"] = 0, ["objectID"] = 82220, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[34077] = { ["id"] = 34077, ["name"] = "Trouble to the South", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34077 }, ["series"] = { 33786, 33787, 33788, 33808 }, ["description"] = "A group of Alliance soldiers headed south from here not long ago. They said they were searching for some sort of special flower. To be frank, I'm concerned for their safety. This area is still crawling with Iron Horde. They could surely use your help if you're able. Follow the road south and you should find their position.", ["objectivesText"] = "Find Captain Renault south of Pilgrim's Sojourn in Shadowmoon Valley .", ["rewardGold"] = 11800, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34078] = { ["id"] = 34078, ["name"] = "Payment Due for Services Rendered", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34034, 34035, 34039, 34040, 34041, 34042, 34078 }, ["series"] = { 34034, 34035, 34039, 34040, 34042 }, ["description"] = "I'm ready to get outta here, and I ain't hoofin' it back through all those orcs. Fortunately, I kept a few extra rocket chickens to get us back to your garrison in style! Let's get up to the roof and find a decent place to take off.", ["objectivesText"] = "Bring Gazlowe to the roof of Overlord Blackhammer's fortress in the Iron Siegeworks.", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 113, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34079] = { ["id"] = 34079, ["name"] = "Mission Successful", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34079 }, ["description"] = "The Thunderlords are finished <name> and our job is complete. I'll stay here and watch over the area. You should head back to Sergeant Gil'nath. I'm certain he will have another task for you.", ["objectivesText"] = "Speak to Sergeant Gil'nath in Frostfire Ridge .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34087] = { ["id"] = 34087, ["name"] = "Through the Looking Glass", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34088, 34959, 36801 }, ["description"] = "An ally of yours, Thaelin, is helping us counter the Iron Horde. He claims this device can be used to spy on the enemy, even so far as hearing what they are saying at great distance. I do not trust such devices. Use it and let me know what you see.", ["objectivesText"] = "Look through Thaelin's Observicopter. Progress: Take a look through Thaelin's Observicopter. I don't trust that machine.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34088] = { ["id"] = 34088, ["name"] = "Too Many Irons in the Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34087, 34959, 36801 }, ["description"] = "We must slay the Iron Horde troops who infest our lands. Find those who would sully our great forest and show them the hand of justice.", ["objectivesText"] = "Kill 15 Iron Horde at Mor'gran Logworks.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34089] = { ["id"] = 34089, ["name"] = "In Short Supply", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34095 }, ["description"] = "The Iron Horde has explosive devices stored throughout the heart of their logging camp. We must recover them so they are not used against us. I will keep an eye on Maraad... I worry for him in his anger.", ["objectivesText"] = "Collect 6 Iron Horde Explosives . Progress: Have you found the Iron Horde Explosives yet?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 69903, 90818, 103533, 107843, 107855, 108825, 109161, 110560, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34090] = { ["id"] = 34090, ["name"] = "Thaelin's Quick Fix", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34091, 34094, 34096, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "Those orcs sure like to pile things up in one place. That gave me an idea... I've built this ingenious device for ya! When you get near a target, it'll let you know, and you can deploy it for a big, satisfying, kerBOOM!", ["objectivesText"] = "Destroy the Thunderlord Cache, Blackrock Forge, and Log Storage. Progress: BOOM! Ahahahahaaa!", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560, 113023, 113024, 113025 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34091] = { ["id"] = 34091, ["name"] = "Decommissioned Mission", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34094, 34096, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "Ketya Shrediron, Your new Iron Shredders are a menace to our own soldiers. Decommission the prototype and store it out of the way until you've worked out the kinks. I will send Engineer Trak to work on it in the meantime. - Orgrim Doomhammer", ["objectivesText"] = "Kill Engineer Trak and recover the Decommissioned Iron Shredder .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34092] = { ["id"] = 34092, ["name"] = "Desperate Measures", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 33976, 34240, 34242, 34326, 34508 }, ["description"] = "We've identified the location of Teron'gor's compound, but his forces are already far stronger than anything we've ever faced. We need to gain an edge, and quickly. The cursed spirits of the Ango'rosh ogres, our ancient enemies, linger in nearby ruins. Go there and gather the Ango'rosh Spellbook and the Grimoire of Binding . Perform the ritual described within at their altar to lift their curse and seek their aid. It's a long shot, but we don't have any other options.", ["objectivesText"] = "Gather the Ango'rosh Spellbook and the Grimoire of Binding , then perform the ritual at the Altar of Ango'rosh in the Ango'rosh Ruins. Progress: Were you able to acquire the aid of the Ango'rosh?", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77799, ["x"] = 0.434, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77799, ["x"] = 0.434, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 17, ["flags"] = 0 } } },
[34093] = { ["id"] = 34093, ["name"] = "Getting the Points", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34093 }, ["description"] = "Those Thunderlords circling above us are a problem <name>. They fly their pathetic Rylaks leisurely across the valley, thinking they are safe to rain spears down on our heads. We need to show them they are not safe from Frostwolf Vengeance! I have a plan but we will need to gather some material. Go hunt across the valley for any of their spears that survived intact. I think five should be enough.", ["objectivesText"] = "Gather 5 Barbed Thunderlord Spears within the Bones of Agurak. Progress: What is it <name>? Have you got something for me?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109056 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34094] = { ["id"] = 34094, ["name"] = "Vol. X Pages ?", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34096, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "That shredder had a manual jammed in the cockpit, but it's missing a lot o' pages. If we can find those manual pages, I'd bet my third toe I can get the prototype shredder working again. I coulda swore I saw a few of those pages floatin' about in Archenon Siegeyard. Maybe the orcs there carry them.", ["objectivesText"] = "Find 20 Manual Pages on orcs at Archenon Siegeyard. Progress: Have you found those pages? These manuals are ridiculous.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 107843 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34095] = { ["id"] = 34095, ["name"] = "Iron Them Out", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34089 }, ["description"] = "The orcs themselves are not the only threat. They still have siege weapons of significant power. They've already been used against Tuurem, and we must not allow for their continued operation. Sabotage siege weapons using the explosives you collected from the logging camp.", ["objectivesText"] = "Destroy 6 Iron Horde Siege Engines.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34096] = { ["id"] = 34096, ["name"] = "An Eye for a Spy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "I'll get the prototype shredder working right now! Take a look through my Observicopter. You'll see what you're about to head into...", ["objectivesText"] = "Look through Thaelin's Observicopter. Progress: Take a look!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 63793, 63794, 63796, 63797, 246427 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34097] = { ["id"] = 34097, ["name"] = "Born to Shred", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34098, 34099, 34947, 34963 }, ["description"] = "I've got this prototype shredder operating on most cylinders. Boy, will they be surprised when you stomp them with their own machine! Can't wait to watch you from the safety of the Observicopter.", ["objectivesText"] = "Kill 100 Iron Horde in Tuurem using the Iron Shredder.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 }, { ["mapID"] = 535, ["npcID"] = 75968, ["x"] = 0.606, ["y"] = 0.387368 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34098] = { ["id"] = 34098, ["name"] = "Engineering Her Demise", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34097, 34099, 34947, 34963 }, ["description"] = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", ["objectivesText"] = "Defeat Ketya Shrediron .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 113050, 113051, 113052, 113053, 113054, 113055, 113056, 113057 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 }, { ["mapID"] = 535, ["npcID"] = 75968, ["x"] = 0.606, ["y"] = 0.387368 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34099] = { ["id"] = 34099, ["name"] = "The Battle for Shattrath", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34097, 34098, 34947, 34963 }, ["description"] = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose. Horde, Alliance, past, present... all meaningless in the face of this enemy. We will retake Shattrath together... or die trying.", ["objectivesText"] = "Repel the Iron Horde from Shattrath.", ["rewardGold"] = 1239200, ["rewardXP"] = 5530, ["rewardItems"] = { 112516, 112517, 112518, 112519, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75805, ["x"] = 0.542, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79608, ["x"] = 0.696, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34102] = { ["id"] = 34102, ["name"] = "The Mark of Defiance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34102 }, ["series"] = { 34070, 34072, 34073, 34075, 34264 }, ["description"] = "As you look upon the Frostwolf banner you remember struggles that have led you and the Frostwolves to this point. Ruk'gan has suffered in his battles with the Thunderlord and would appreciate an extra show of defiance. As the banner rustles in the wind you're inspired to mark the foes of the Frostwolf with its standard.", ["objectivesText"] = "Use the Battle-Worn Frostwolf Banner on the corpses of 6 Thunderlord Orcs in Agurak's Fall. Progress: Anything to report, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 109196 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34103] = { ["id"] = 34103, ["name"] = "WANTED: Kil'uun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34103 }, ["description"] = "I have a bounty set on a bird, commander. Yes, a bird. The issue is this thing is massive, and it was last sighted a stone's throw away from the Horde base to the south in the forest. The locals call it Kil'uun. If you'd like to track the creature down and bring back its beak I wager it would fetch a sack or two of gold for your coffers!", ["objectivesText"] = "Hunt Kil'uun and bring its beak to Patrick Messer . Progress: Any luck tracking down that bird, commander?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 112380, 112534, 112577, 112578, 112582, 112584, 112624 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80854, ["x"] = 0.695, ["y"] = 0.211 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80854, ["x"] = 0.695, ["y"] = 0.211 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.211 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "group" },
[34104] = { ["id"] = 34104, ["name"] = "WANTED: Hilaani", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34104 }, ["description"] = "O'riley wants to thank our peasants for their hard work with a riverbeast dinner. $I don't want to waste your time asking you to slaughter the things all day, commander. We've gotten reports of a huge riverbeast called Hilaani that would feed the whole fort twice over living in the lake to the south. If you have a chance to bring cuts of her meat back, the men would be grateful.", ["objectivesText"] = "Kill Hilaani and bring the Pile of Riverbeast Meat to Patrick Messer . Progress: Have you had time to kill Hilaani?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 112381, 112533, 112576, 112579, 112583, 112586, 112587 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80854, ["x"] = 0.695, ["y"] = 0.211 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80854, ["x"] = 0.695, ["y"] = 0.211 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.211 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "group" },
[34105] = { ["id"] = 34105, ["name"] = "WANTED: Ra'tok the Hammer", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34105 }, ["description"] = "I've got an issue that could use your assistance, commander. A few of our men spotted an Iron Horde lieutenant wandering in the cliffs near here. We suspect she's directing their forces to strategic ground as they land on the Orunai Coast. I would feel much better about the safety of this fort if you could take her out.", ["objectivesText"] = "Dispatch Ra'tok the Hammer in the Orunai Coast.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 112535, 112536, 112580, 112581, 112585 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80854, ["x"] = 0.695, ["y"] = 0.211 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80854, ["x"] = 0.695, ["y"] = 0.211 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.211 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "group" },
[34106] = { ["id"] = 34106, ["name"] = "WANTED: Ra'tok the Hammer", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34106 }, ["description"] = "The Iron Horde have no honor. They disgust me. We spotted one of their lieutenants wandering the cliffs not far from our base. I believe that she is tracking our movements to prepare for some sort of assault from the Orunai Coast. I understand you have much to do, commander. If you have the time, I believe it would be beneficial to our position's integrity.", ["objectivesText"] = "Kill Ra'tok the Hammer in the Orunai Coast.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 112535, 112536, 112580, 112581, 112585 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80833, ["x"] = 0.708, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80833, ["x"] = 0.708, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "group" },
[34107] = { ["id"] = 34107, ["name"] = "WANTED: Hilaani", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34107 }, ["description"] = "We need more meat, commander. I know what you're thinking. What about all of that meat right behind me? That's the problem. It'll be gone in a day if we're lucky. There's a riverbeast that lives in the lake to the south. Locals call her Hilaani. Massive, lots of meat. If you would take down the beast and bring me her meat, your wolves will be better off for it.", ["objectivesText"] = "Slay Hilaani and bring a Pile of Riverbeast Meat to Beastmaster Tagh . Progress: Good to see you, commander.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 112381, 112533, 112576, 112578, 112579, 112583, 112586, 112587 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80833, ["x"] = 0.708, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80833, ["x"] = 0.708, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "group" },
[34108] = { ["id"] = 34108, ["name"] = "WANTED: Kil'uun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34108 }, ["description"] = "It's that damned bird! Every few hours, this blasted thing flies right past here, and none of these idiots will stop it. \"It's got the crazy in its eyes,\" they tell me. Pah! Commander, this bird will be the end of me. If you see it, could you cut off its stupid head and give it to me? It'd make me feel better.", ["objectivesText"] = "Bring Kil'uun's Beak to Beastmaster Tagh . Progress: If you decide to kill that creature, I will name my first-born in your honor.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 112380, 112534, 112577, 112578, 112582, 112584, 112624 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80833, ["x"] = 0.708, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80833, ["x"] = 0.708, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "group" },
[34122] = { ["id"] = 34122, ["name"] = "Ogre Diplomacy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34122 }, ["description"] = "They may be spirits, but the Ango'rosh are still ogres. Even with their books in hand, they won't respect you until you prove yourself, and there's only one way to earn that. By killing them. You should take out as many of the Ango'rosh spirits and their pets as you can while in the ruins.", ["objectivesText"] = "Kill 10 Ango'rosh in the Ango'rosh Ruins. Progress: How goes your diplomatic mission?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34123] = { ["id"] = 34123, ["name"] = "To Thunder Pass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33010, 34123, 34124, 37291 }, ["series"] = { 33010, 33543, 33544, 34124, 34867, 35557, 49546 }, ["description"] = "There is no time to mourn our fallen or lick our wounds. Your scouts have already reported sighting a massive Iron Horde army making its way through Thunder Pass. I advise you let your garrison forces secure this area while you and I make for the pass east of here with the rest of the Frostwolves. It is time to show this Iron Horde what a united Frostwolf clan can do.", ["objectivesText"] = "Speak with Lokra at Wolf's Stand.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 106137, 106146, 106169, 107397 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76487, ["x"] = 0.749, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 22, ["name"] = "The Battle of Thunder Pass", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34124] = { ["id"] = 34124, ["name"] = "The Battle of Thunder Pass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33010, 34123, 34124, 37291 }, ["series"] = { 33010, 33543, 33544, 34123, 34867, 35557, 49546 }, ["description"] = "The Iron Horde has an army tenfold our number marching down the Thunder Pass as we speak. Durotan is amassing our forces at the mouth of the pass. He is doing what he can to mount a defense but war on this scale is not what we Frostwolves are masters of. He will need your expertise. Please, go to him.", ["objectivesText"] = "Defend Frostfire Ridge from the Iron Horde.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 106137, 106146, 106169, 107397, 118474 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76487, ["x"] = 0.749, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76484, ["x"] = 0.756, ["y"] = 0.554 }, { ["mapID"] = 525, ["npcID"] = 77485, ["x"] = 0.75, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 22, ["name"] = "The Battle of Thunder Pass", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34144] = { ["id"] = 34144, ["name"] = "Retribution for the Light", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale. You have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", ["objectivesText"] = "Kill 15 demons in Gul'rok.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 }, { ["mapID"] = 535, ["npcID"] = 77580, ["x"] = 0.456, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 19, ["flags"] = 0 } } },
