[34211] = { ["id"] = 34211, ["name"] = "Treasure: Gorgrond Treasure 20", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34211 }, ["rewardGold"] = 171000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34213] = { ["id"] = 34213, ["name"] = "They Have My Son", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34213 }, ["description"] = "Please, $p! Can you help me. I received a ransom note from a very corrupt and uncouth orc within the ranks of the Iron Horde. He has my son! He made sure to include a number of graphic words to describe what would happen if the ransom is not paid. Clearly he thinks my people conjure gold from the nether. And if I try to rescue him myself, both of us will be killed in the process. Can you go to Gron'mar for me and rescue my son? His name is Corki .", ["objectivesText"] = "Find the Key to Corki's Cage and set him free.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 109592 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
