[34242] = { ["id"] = 34242, ["name"] = "Scheduled Pickup", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["series"] = { 33958, 33976, 34092, 34240, 34326, 34508 }, ["description"] = "You've proven yourself more than capable in battle, <name>. There may be Shadow Council forces all around Auchindoun, including near Telmor. I want you to join Soulbinder Tuulani at Telmor to make sure the crystal makes it safely to Auchindoun. I know I can trust you to get it done.", ["objectivesText"] = "Speak to Soulbinder Tuulani outside Telmor.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75246, ["x"] = 0.61, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77869, ["x"] = 0.504, ["y"] = 0.875 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34244] = { ["id"] = 34244, ["name"] = "They Took My Father", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34244 }, ["description"] = "$p! I have a lead on what happened to my father. There have been reports that he was seen in the presence of Shadow Council orcs in ____. My father was a powerful Anchorite with a vast amount of ancient knowledge. I dread to think what those within the Shadow Council would do to him to get that knowledge. Can you go to ___? Hunt down their officers and see what they know?", ["objectivesText"] = "Collect Anchorite Dolruu's three notes.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109749, 109750, 109751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34264] = { ["id"] = 34264, ["name"] = "A Collection of Coils", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34264 }, ["series"] = { 34070, 34072, 34073, 34075, 34102 }, ["description"] = "None of the Thunderlord can escape my wrath! We need something to pull them out of the skies so that they can greet our blades. Their wranglers should carry rope with them for handling their beasts. Slay them, if they have any coils in good condition bring them to me.", ["objectivesText"] = "Gather 5 Coils of Sturdy Rope from Thunderlord Wranglers in the Bones of Agurak. Progress: I'm growing tired of waiting, do you have anything to help our assault or not?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109055 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77210, ["x"] = 0.8275, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.8275, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34271] = { ["id"] = 34271, ["name"] = "The Fate of Gordawg", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements. Gordawg stands before us enthralled; a slave to the pale and their mysterious master. My heart is heavy with grief to see such a great creature mindless and enslaved by evil. There is no going back, in order to push forward you must go through Gordawg. It pains me, but Gordawg must be slain. When the deed is done, we will return the fury's heart to the Throne of Elements.", ["objectivesText"] = "Retrieve the Heart of the Fury . Progress: What of Gordawg? Has the great fury been brought to rest?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 113077 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80595, ["x"] = 0.726, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34277] = { ["id"] = 34277, ["name"] = "Stop the Flow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34277 }, ["description"] = "The Shadow Council down in the boneyard are going to have magic circles. It's not enough to simply kill them; we also have to eliminate their infernal devices. If you destroy the circles, you'll stop the flow of demons they're summoning to inhabit the bones of the dead.", ["objectivesText"] = "Destroy 7 Summoning Circles . Progress: Were you able to destroy the Shadow Council's summoning circles ?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72836, ["x"] = 0.318, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72836, ["x"] = 0.318, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34278] = { ["id"] = 34278, ["name"] = "Desecration of the Dead", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34278 }, ["description"] = "These filthy warlocks are desecrating the dead in the boneyard! <The farseer trembles as he fails to keep his composure.> I WANT THEM DEAD! Destroy the necrophytes . Destroy their demonic abominations.", ["objectivesText"] = "Kill 15 Necrophytes and Fel Wolves .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 108972, 108975, 108976 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72837, ["x"] = 0.318, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72837, ["x"] = 0.318, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34279] = { ["id"] = 34279, ["name"] = "I Am Blook", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34279 }, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 78030, ["x"] = 0.412, ["y"] = 0.914 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 78030, ["x"] = 0.412, ["y"] = 0.914 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.914 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[34280] = { ["id"] = 34280, ["name"] = "All is Revealed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34209, 34216, 34227, 34230, 34280, 34291, 34294, 34295 }, ["series"] = { 34230, 34291, 34294, 34295 }, ["description"] = "Tell me when you're ready. We'll invoke the power of the ring to summon one of their 'eyes.' Through it, we'll discover where the Shadow Council is located and what they're really up to.", ["objectivesText"] = "Spy on the Shadow Council.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 44017, 44033, 44034, 44035, 62860, 62861, 62862, 131665 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72874, ["x"] = 0.316, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72874, ["x"] = 0.316, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 58, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34281] = { ["id"] = 34281, ["name"] = "Out of the Chains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["description"] = "They roughed me up real good an' I have a splitting headache but I'll survive. I need to get out of this bit o' chain here though. Could ye get the key to it for me? A big ogre called Nub has it, he's over on the far side of the terrace.", ["objectivesText"] = "Obtain the Bloodmaul Shackle Key and free Owynn Graddock . Progress: Dun ye worry about me. I'll sit here an' nurse me wounds.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 37959, 38001, 38044, 38105, 110116, 112588, 112589, 112590, 112607, 237812 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78056, ["x"] = 0.488, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78056, ["x"] = 0.488, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34284] = { ["id"] = 34284, ["name"] = "Garrison Campaign: The Search for Owynn Graddock", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34285, 34286, 34287, 34288, 34289, 34362 }, ["description"] = "Commander, I have bad news to report. Agent Graddock was out on assignment to keep an eye on the Bloodmaul and he missed his deadline to check back in. Something's not right, <name>. If Owynn was captured they may have locked him away with their slaves. Head over to Stonefury Cliffs and see if you can locate him.", ["objectivesText"] = "Travel to the Stonefury Cliffs in Frostfire Ridge and search for Owynn Graddock .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110116, 110149, 110229, 110232, 110378, 110394 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78056, ["x"] = 0.488, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34285] = { ["id"] = 34285, ["name"] = "Gearing Up", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34284, 34286, 34287, 34288, 34289, 34362 }, ["description"] = "When I was captured they took my gear and left me in rags. My mace is being used to crack stones and they're even using me best dagger as a dinner fork! I'd hate to know what happened to me armor but I hope its still usable. I'll need a wee bit to recover from me wounds and without my stuff I'm no help in a fight. Could ye go find my gear for me? Last I saw my armors in a chest next to that big tower south of here, my dagger was to the south west, and my mace over near that lava field to the west.", ["objectivesText"] = "Obtain Owynn's Dagger , Mace, and Gear. Progress: Just need a bit of a refresher, being beat up by ogres makes ye a little sore. Who knew?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 6735, 110149, 110229, 110232, 226273, 239121, 250765 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78056, ["x"] = 0.488, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78056, ["x"] = 0.488, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34286] = { ["id"] = 34286, ["name"] = "Seeking the Truth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34284, 34285, 34287, 34288, 34289, 34362 }, ["description"] = "Okay, now down to business. The Bloodmaul have unearthed some monstrous artifact I've heard them call the Soulgrinder. It's a nasty bit o' sorcery that their chief uses to give himself incredible magical power, but it comes at the cost of needing to feed upon souls to maintain it. Every day, more and more corpses pile up from the slaves killed to maintain it. We need to go find Borgal and get rid of this Soulgrinder!", ["objectivesText"] = "Locate Borgal Doomfist.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 248038, 248039, 248040, 248041 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78185, ["x"] = 0.486, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78239, ["x"] = 0.402, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34287] = { ["id"] = 34287, ["name"] = "Cleansing the Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34284, 34285, 34286, 34288, 34289, 34362 }, ["description"] = "Not all spirits are destroyed by the Soulgrinder. Some souls manage to survive more or less intact like myself. Others have become twisted and maddened. End their misery, take my soul shard and use it to purify them. Their rage will blind them to the effects of its energy so you must defeat them before you use it.", ["objectivesText"] = "Cleanse 10 Crazed Souls.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110394 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34288] = { ["id"] = 34288, ["name"] = "The Totems That Bind", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34284, 34285, 34286, 34287, 34289, 34362 }, ["description"] = "Before Borgal began to use the Soulgrinder, he used totems to bind spirits to his service. If we can get a few of those totems I may be able to use the spiritual connection he's forged with them to force a link. He'll be compelled to appear before us! Go find me a few of those totems and I might be able to pull this off, I think five should do it.", ["objectivesText"] = "Collect 5 of Borgal's Totems . Progress: Do you have those totems I asked for? He left them around the buildings nearby.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110378 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34289] = { ["id"] = 34289, ["name"] = "Soulgrinder Survivor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34362 }, ["description"] = "It is time for Borgal to die. We must travel to a location of power where I have room for the ritual. There is a ruined tower to the northwest that will be perfect for this. Meet us there and place the totems in the areas of power you will find there. Once they are placed I will do the ritual that will summon Borgal to us. Your job will be the difficult one, kill him!", ["objectivesText"] = "Place Borgal's totems so that Orlana can begin the ritual, then kill Borgal.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 119151 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78810, ["x"] = 0.38, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34291] = { ["id"] = 34291, ["name"] = "Have a Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34209, 34216, 34227, 34230, 34280, 34291, 34294, 34295 }, ["series"] = { 34230, 34280, 34294, 34295 }, ["description"] = "Did you notice the magical barrier protecting the cave's entrance? It's being powered by demon crystals. The Burning Legion has a habit of making demon parts serve as the keys to such devices. Travel west to the Ruins of Ata'gar. Look for a powerful demon therein and bring me its heart. I'll project an image of myself into the ruins. You won't have to come back here until we're done.", ["objectivesText"] = "Collect the Heart of Fernus from Fernus. Progress: Do you have the demon key?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 110150 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72874, ["x"] = 0.316, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 73480, ["x"] = 0.212667, ["y"] = 0.145333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 58, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34292] = { ["id"] = 34292, ["name"] = "Eliminate the Shadow Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34292 }, ["description"] = "Those ruins are going to be full of Shadow Council flunkies. We can't afford to let them scatter all over Draenor once you've dealt with Gul'dan. No, we need to eliminate every one of them down to the last orc.", ["objectivesText"] = "Kill 12 Shadow Council members at the Ruins of Ata'gar.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72836, ["x"] = 0.318, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72836, ["x"] = 0.318, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34293] = { ["id"] = 34293, ["name"] = "Eliminate the Shadow Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34293 }, ["description"] = "These ruins are full of Shadow Council adherents. We can't afford to let them scatter all over Draenor once Gul'dan has been dealt with. No, we need to eliminate every one of them down to the last orc.", ["objectivesText"] = "Kill 12 Shadow Council members at the Ruins of Ata'gar.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 73480, ["x"] = 0.212667, ["y"] = 0.145333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72836, ["x"] = 0.318, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.212667, ["y"] = 0.145333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34294] = { ["id"] = 34294, ["name"] = "The Fel Crystals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34209, 34216, 34227, 34230, 34280, 34291, 34294, 34295 }, ["series"] = { 34230, 34280, 34291, 34295 }, ["description"] = "You have the key. Now use it to destroy the fel crystals . Once they are eliminated, the magical barrier blocking the entrance to the Gloomspire will come down. And once the barrier is down, you'll go inside to confront Gul'dan.", ["objectivesText"] = "Destroy the Fel Crystals . Progress: Is there a problem?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110545 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 73480, ["x"] = 0.212667, ["y"] = 0.145333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 73480, ["x"] = 0.212667, ["y"] = 0.145333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.212667, ["y"] = 0.145333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 58, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34295] = { ["id"] = 34295, ["name"] = "To Capture Gul'dan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34209, 34216, 34227, 34230, 34280, 34291, 34294, 34295 }, ["series"] = { 34230, 34280, 34291, 34294 }, ["description"] = "Gul'dan is in the cave further into the Gloomspire. We know that he's about to leave for Talador and Shadowmoon Valley. You must capture him by any means necessary, <name>. I'll see you back at Throm'var. Good luck.", ["objectivesText"] = "Confront Gul'dan .", ["rewardGold"] = 509400, ["rewardXP"] = 2125, ["rewardItems"] = { 113148, 113149, 113150 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 73480, ["x"] = 0.212667, ["y"] = 0.145333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72874, ["x"] = 0.316, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.212667, ["y"] = 0.145333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 58, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34309] = { ["id"] = 34309, ["name"] = "Garrison Campaign: The Search for Shadow Hunter Bwu'ja", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["description"] = "It be a long time since we hear from Shadow Hunter Bwu'ja , commander. Last we know she be on assignment keeping an eye on dem Bloodmaul ogres up in Frostfire. Dem ogres just be a bunch a slavers so something really big must be happening ta keep her from reporting in. Go over ta de Stonefury Cliffs an' find her.", ["objectivesText"] = "Travel to the Stonefury Cliffs and search for Shadow Hunter Bwu'ja .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110378, 110394, 110606, 110607, 110608, 110664 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78659, ["x"] = 0.518, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34314] = { ["id"] = 34314, ["name"] = "Out of the Chains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34315, 34316, 34318, 34319, 34381, 34469 }, ["description"] = "Lissen mon, dem ogres, got da jump on me wid an artifact wid powerful mojo. Next t'ing I know I wake here wid broken bones an' dis chain on me leg. I called to da spirits ta break it, but da spirits here no answer. Gotta go wid da old methods ta get out. Dere be a big ogre in da cave here called Rugrum who has da key to me shackle. Could ye go put a blade in his belly and get me dat key?", ["objectivesText"] = "Obtain the Bloodmaul Slave Key and free Shadow Hunter Bwu'ja . Progress: You no worry about me, mon. I be going nowhere.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 37959, 38001, 38044, 38105, 110378, 110394, 110606, 110607, 110608, 110664, 112588, 112589, 112590, 112607, 237812 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78659, ["x"] = 0.518, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78659, ["x"] = 0.518, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34315] = { ["id"] = 34315, ["name"] = "Gearing Up", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34316, 34318, 34319, 34381, 34469 }, ["description"] = "Dem ogres whipped me real good. My arm be broke, a few ribs snapped, t'ink even me spleen be hurtin' from dat beatin'. Nothin' a troll can't handle though but I be needin' a moment ta recover. What I really be needin' is me gear dem ogres took from me. Dey got me garb in a chest near a hut to da south, me glave in a chest next to da tower wid da Bonecrushers, dey even got me mask, it over near da lava! Could ye go find dem while I take a breather?", ["objectivesText"] = "Obtain Bwu'ja's garb, glave, and mask. Progress: Ah, hear dat? T'ink anudda rib just popped back inta place.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 6735, 110378, 110394, 110606, 110607, 110608, 110664, 226273, 239121, 250765 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78659, ["x"] = 0.518, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78659, ["x"] = 0.518, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34316] = { ["id"] = 34316, ["name"] = "Seeking the Truth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34315, 34318, 34319, 34381, 34469 }, ["description"] = "Lissen mon, a few nights ago dem ogres found a bit o' old and powerful mojo. I was snooping around da cave across de lava flows when dere was a huge scream from da spirit world. I went in and saw Borgal, de ogre chief, he be draining da spirits from de slaves wid some big stone wheel dat I heard dem call de Soulgrinder. I tried ta take 'em out but a single shot from dat thing took all de strength from me. Dat mojo too much of a threat in de hands of dem ogres.", ["objectivesText"] = "Locate Borgal Doomfist.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110378, 110394, 110606, 110607, 110608, 110664, 248038, 248039, 248040, 248041 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78746, ["x"] = 0.518, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78785, ["x"] = 0.405, ["y"] = 0.218 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34318] = { ["id"] = 34318, ["name"] = "The Totems That Bind", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34315, 34316, 34319, 34381, 34469 }, ["description"] = "Before Borgal began to use the Soulgrinder, he used totems to bind spirits to his service. If we can get a few of those totems I may be able to use the spiritual connection he's forged with them to force a link. He'll be compelled to appear before us! Go find me a few of those totems and I might be able to pull this off, I think five should do it.", ["objectivesText"] = "Collect 5 of Borgal's Totems . Progress: Do you have those totems I asked for? He left them around the buildings nearby.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110378, 110394, 110606, 110607, 110608, 110664 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34319] = { ["id"] = 34319, ["name"] = "Soulgrinder Survivor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34315, 34316, 34318, 34381, 34469 }, ["description"] = "It is time for Borgal to die. We must travel to a location of power where I have room for the ritual. There is a ruined tower to the northwest that will be perfect for this. Meet us there and place the totems in the areas of power you will find there. Once they are placed I will do the ritual that will summon Borgal to us. Your job will be the difficult one, kill him!", ["objectivesText"] = "Place Borgal's totems so that Orlana can begin the ritual, then kill Borgal.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 109624, 110378, 110394, 110606, 110607, 110608, 110664, 119151 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78821, ["x"] = 0.375, ["y"] = 0.14 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34321] = { ["id"] = 34321, ["name"] = "Ashes Of The Past", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34321 }, ["description"] = "The ogres are a plague upon my kind. They summon my kin and force them into servitude, working them without rest till their heat fades away and they crumble into dust. Their ashes must return to the lava flows so that they can be reborn! The Ogres keep the dust in pouches on their person thinking it would enhance their strength. Go slay them and recover the ashes of my people!", ["objectivesText"] = "Molthron within the Bloodmaul Territory wants you to bring him 6 Piles of Elemental Ash . Progress: Do you bring me the remains of our fallen?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110438 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77998, ["x"] = 0.435, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77998, ["x"] = 0.435, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34325] = { ["id"] = 34325, ["name"] = "Flames Of The Earth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34325 }, ["description"] = "I've searched the depths of the earth and found the means to break the spells that hold my people captive, but it only functions to free one who is completely bound. I would be unable to prevent myself from becoming bound by the same magic. You, flesh creature, are not of the flames below so their binding spells should not affect you. Please take my jewel, use its power to free my people!", ["objectivesText"] = "Molthron within the Bloodmaul Territory wants you to use the Flamewrought Jewel to free 6 Magma Elementals. Progress: Do my people have their freedom?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110492 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 77998, ["x"] = 0.435, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 77998, ["x"] = 0.435, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34326] = { ["id"] = 34326, ["name"] = "Changing the Tide", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 33976, 34092, 34240, 34242, 34508 }, ["description"] = "It is time to retaliate against this foe. Meet me at Retribution Point and we will take this fight to the Shadow Council. Teron'gor shall not feast on another soul so long as we stand in his way! His reign of terror ends today.", ["objectivesText"] = "Speak to Restalaan at Retribution Point.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77082, ["x"] = 0.448, ["y"] = 0.905 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77799, ["x"] = 0.434, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.905 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 16, ["flags"] = 0 } } },
[34335] = { ["id"] = 34335, ["name"] = "Garrison Campaign: Crows In The Field", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 535, ["storyline"] = { 34335, 34336, 34337, 34338, 34339, 34340, 34341, 34347 }, ["series"] = { 34336, 34337, 34338, 34339, 34340, 34341, 34347, 34409, 34410 }, ["description"] = "Our druids set up a wide network of scouts to follow up on your intel from Nagrand. We've identified a suspicious Iron Horde excavation near some salt pools on the western coast of Gorgrond. We have reason to believe that these orcs are pursuing a valuable artifact deep in the desert. I'm putting together a small mission for a focused, surgical strike, and we could use a capable <class> like yourself. I'd like you to be part of that team.", ["objectivesText"] = "Speak to Thisalee Crow at Skysea Ridge in Gorgrond.", ["rewardGold"] = 42135, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78192, ["x"] = 0.694, ["y"] = 0.09 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 78187, ["x"] = 0.398, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.09 }, ["mapCandidates"] = { ["npc"] = { 535, 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34336] = { ["id"] = 34336, ["name"] = "Ambushing the Enemy", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34337, 34338, 34339, 34340, 34341, 34347, 34409, 34410 }, ["description"] = "See that Iron Horde camp to the south, across the water? We've been watching their movements for days. We've seen a lot of correspondence between their lieutenant and the Iron Horde command in Nagrand. We need to disrupt their operation. Gather their supplies, and bring me their leader's head.", ["objectivesText"] = "Collect 5 Caravan Shipments and Lieutenant O'rok's Head . Progress: Those orcs were working on someone else's orders.", ["rewardGold"] = 464700, ["rewardXP"] = 1365, ["rewardItems"] = { 110230, 110231, 119139 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 78187, ["x"] = 0.398, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 78187, ["x"] = 0.398, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34337] = { ["id"] = 34337, ["name"] = "The Giant Cauldron", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34336, 34338, 34339, 34340, 34341, 34347, 34409, 34410 }, ["description"] = "A high value artifact at Cragplume Canyon, hmmm? Let's see if we can't beat the Iron Horde to it. Let's move fast. Speak to Choluna , and we'll be on our way.", ["objectivesText"] = "Speak to Choluna .", ["rewardGold"] = 46350, ["rewardXP"] = 685, ["rewardItems"] = { 119093 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 78187, ["x"] = 0.398, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 78251, ["x"] = 0.542, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34339] = { ["id"] = 34339, ["name"] = "A Goren's Feast", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34336, 34337, 34338, 34340, 34341, 34347, 34409, 34410 }, ["description"] = "Goren. This caldera is full of them. I can even smell their stench from here. I suspect that these goren are more than just primitive beasts, but in order to prove my theories, I need more data. During your mission, if you should slay a goren or two, would you examine their stomachs for me? I'd like to know what these curious creatures eat.", ["objectivesText"] = "Collect 8 Engorged Stomachs and examine their contents.", ["rewardGold"] = 464700, ["rewardXP"] = 1365, ["rewardItems"] = { 110278 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 89179, ["x"] = 0.542, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 89179, ["x"] = 0.542, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 549, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34340] = { ["id"] = 34340, ["name"] = "Heating Up", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34336, 34337, 34338, 34339, 34341, 34347, 34409, 34410 }, ["description"] = "Greetings, <name>. I have been conducting research on the steam geysers of Gorgrond for some time now. Cragplume Cauldron is one of the largest caldera in this region, but we have been unable to do a geographical survey due to the dangerous creatures in this area. Since you are venturing into the depths, could you take a temperature reading for me? It would add greatly to our understanding of these natural caverns.", ["objectivesText"] = "Use Aren's Thermometer near the Hissing Geyser inside Cragplume Cauldron.", ["rewardGold"] = 87975, ["rewardXP"] = 1365, ["rewardItems"] = { 110288 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74125, ["x"] = 0.471, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74125, ["x"] = 0.471, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34341] = { ["id"] = 34341, ["name"] = "The Beating Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34335, 34336, 34337, 34338, 34339, 34340, 34341, 34347 }, ["series"] = { 34335, 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["description"] = "One thing is certain. We now possess an item of great value to the Iron Horde. We had better secure this... \"Heart of Gorgorek\" at once.", ["objectivesText"] = "Deliver the Heart of Gorgorek to Warmaster Zog at your garrison.", ["rewardGold"] = 464700, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 78251, ["x"] = 0.542, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34344] = { ["id"] = 34344, ["name"] = "Lurkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34344 }, ["series"] = { 34345, 34348 }, ["description"] = "Dis be a dangerous place, boss-mon. Filled with big monsters and savage giants. Well, like my family loa say, 'If ya can't beat it, poison it.' We gonna be needin' some venom from the lurkers out there on the Cracking Plains. Dem lurkers be mighty sneaky, and mighty creepy. Be watchin the ground for rumbles and shakes. I'll be stayin' here to make a cure in case you accidentally get too poisoned.", ["objectivesText"] = "Collect 8 doses of Lurker Venom. Progress: Dem lurkers scare ya off?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 106140, 106161, 106172, 107311, 110226 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34345] = { ["id"] = 34345, ["name"] = "Poulticide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34345 }, ["series"] = { 34344, 34348 }, ["description"] = "We be huntin' something so big, so savage, we gonna need anotha poison. We gonna need a big ol' poultice of poison! So... boss-mon? Ya think ya up for a little flower pickin'? We gonna need the leaves of them frostbloom plants that be growing along the shadows of rocks and ledges along the sides of the Cracking Plains. Be careful when pickin' them, boss-mon! They not always be by themselves...", ["objectivesText"] = "Collect 10 Frostbloom Leaves . Progress: I'd pick de flowers myself, but I got allergies. Ha ha!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110227 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34346] = { ["id"] = 34346, ["name"] = "Frosted Fury", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34346 }, ["description"] = "The furies of Draenor are different than the elementals of Azeroth. But don't be fooled. Some be wicked, boss-mon. Wicked. The trap we are making be needing some proper frostshards . You can get them, if ya willing, from the ice furies. Dey be wandering the Cracking Plains, freezin' all dat dey touch, an' bein' wicked. Bring us some o' these frostshards , boss-mon, an' we gonna whip ya up one deadly trap.", ["objectivesText"] = "Collect 3 Frostshards . Progress: A shadow huntah knows much of da spirits. We be talkin'. We be tradin'. But these ice furies, dey be wicked, boss-mon.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110228 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78209, ["x"] = 0.525, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78209, ["x"] = 0.525, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34347] = { ["id"] = 34347, ["name"] = "Bladefury's Orders", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34336, 34337, 34338, 34339, 34340, 34341, 34409, 34410 }, ["description"] = "Lieutenant O'rok: Send an elite strike team to Cragplume Cauldron. Retrieve a high-value artifact from the crater and deliver it to my command post in northern Talador. With your remaining forces, go to Gorgorek's Fall. Protect and prepare the ancient magnaron specimen for retrieval. Immediate action is required. - Bladefury", ["objectivesText"] = "Deliver Bladefury's Orders to Thisalee Crow at Skysea Ridge.", ["rewardGold"] = 232350, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 78187, ["x"] = 0.398, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 118, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34348] = { ["id"] = 34348, ["name"] = "The Real Prey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34348 }, ["series"] = { 34344, 34345 }, ["description"] = "Eh boss-mon. Time for us to be huntin' the real prey now. To the north, there be a cave. In the cave, there be right mean ogron dey call \" Grosh the Mighty .\" That ogron got a big stash of pillaged hides and leathers we gonna be needin' for the troops at the garrison. I made a special poison from the stuff ya gathered. Dis be a magic poison, and it gonna put that ogron down to sometin' a bit more manageable. Take these vials to the cave and see if ya can't win us a treasure.", ["objectivesText"] = "Find Iceblister Den and then slay Grosh the Mighty . Progress: Why be killin' five hundred clefthoof when ya can just kill one big ogron dat killed five hundred clefthoof?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110270 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34351] = { ["id"] = 34351, ["name"] = "We Must Construct Additional Pylons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 34458, 35249 }, ["description"] = "We came here to retrieve a reserve pylon to power Auchindoun's defenses, but we've been pinned to this position by the Shadow Council for hours! I need to get these injured back to Exarch's Refuge, but we still need the backup system! Please, gather Arkonite crystals and an Arkonite pylon from the tomb and meet me at the refuge as quickly as you can!", ["objectivesText"] = "Collect 6 Arkonite Crystals and an Arkonite Pylon from the Tomb of Lights. Progress: Do you have the arkonite pylon and the crystals?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 110253, 110271 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78520, ["x"] = 0.552, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34352] = { ["id"] = 34352, ["name"] = "Darktide Defender", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34352 }, ["series"] = { 34353, 34355, 34365, 34397, 34450, 35861, 35876 }, ["description"] = "<Rexxar looks at you as you inspect the dead goblin. It's clear what he wants you to do.>", ["objectivesText"] = "Kill 5 Darktide Pilferers and 5 Darktide Engineers .", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 83494, ["x"] = 0.59, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[34353] = { ["id"] = 34353, ["name"] = "Shredder Suppressor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["series"] = { 34352, 34355, 34365, 34397, 34450, 35861, 35876 }, ["description"] = "The rylaks have no defense against the Iron Horde's technology. A true hunter would not need machines to capture their prey. Destroy the Iron Shredders and the scum that pilot them. Spirit will join you on your quest.", ["objectivesText"] = "Destroy Darktide Shredders on Darktide Roost.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 77982, ["x"] = 0.592, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77982, ["x"] = 0.592, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34354] = { ["id"] = 34354, ["name"] = "A Good Death", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["description"] = "These fools have no honor. They seem to enjoy torturing these poor beasts. The only humane thing we can do at this point is find injured rylaks and put them out of their misery. Take this axe and aim for their vitals, <name>. These rylaks deserve a good death.", ["objectivesText"] = "Use Rexxar 's axe to kill Injured Rylaks at Darktide Roost.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77982, ["x"] = 0.592, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34355] = { ["id"] = 34355, ["name"] = "Dirty Rats", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["series"] = { 34352, 34353, 34365, 34397, 34450, 35861, 35876 }, ["description"] = "These shredders are more of a hassle than I expected. I've been peering through the eyes of the rats on the island. There are number of unmanned shredders west of here. The rats have an uncontrollable appetite for this bait. Throw it onto Unmanned Shredders and let the rats destroy them from the inside.", ["objectivesText"] = "Use the rats to destroy Unmanned Shredders on Darktide Roost.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 110268, 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 77982, ["x"] = 0.592, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34362] = { ["id"] = 34362, ["name"] = "The Shadow Gate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289, 34362 }, ["series"] = { 34281, 34284, 34285, 34286, 34287, 34288, 34289 }, ["description"] = "Okay, we're gonna have to be quick. I've seen Borgal form magical portals before so he might try to use one to escape. If he does that our only option will be to follow after 'em. On top of that he always keeps his lieutenant Grubnor nearby so we may have a bit of a tussle in store. <Owynn peeks into the cave.> Keep yer head down, something's going on in there.", ["objectivesText"] = "Defeat Grubnor Wargut and follow after Borgal.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78239, ["x"] = 0.402, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78470, ["x"] = 0.395, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 104, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34364] = { ["id"] = 34364, ["name"] = "For the Horde!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Without you, none of us would have made it to the shores of my homeland. You will be the one to lead our forces here on Draenor. This is your garrison to found. I leave it to you to plant the banner and claim this territory. When you are ready, I will have Khadgar open a portal to bring through a few necessary reinforcements.", ["objectivesText"] = "Plant the Horde Banner to Claim the Land.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 111907, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70859, ["x"] = 0.388, ["y"] = 0.560667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.560667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34365] = { ["id"] = 34365, ["name"] = "Releasing Rylak", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["series"] = { 34352, 34353, 34355, 34397, 34450, 35861, 35876 }, ["description"] = "These goblins have been conducting horrible experiments on the rylaks. This fool gave me the location for three of their prized experiments. Set these mutated rylaks free. Maybe freedom will help these tortured souls find some peace in life.", ["objectivesText"] = "Free the Caged Rylaks on Darktide Roost.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34366] = { ["id"] = 34366, ["name"] = "Tanaan 01: Front of the Portal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34366 }, ["description"] = "- Gul'dan will ask you for freedom, which you ignore. -You plant your mana bomb but it doesn't work. -Khadgar concedes and you kill felbreakers to free Gul'dan. -A noble NPC leads the distraction sacrifice troops while you and Khadgar escape 'round back.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34375] = { ["id"] = 34375, ["name"] = "Back to Work", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Alright, boss. We're gonna need some lumber if we're gonna get this garrison started off right. If you mark some trees to be cut down, your peons will do the rest.", ["objectivesText"] = "Mark 6 Trees. Progress: There aren't a lot of trees around. Go mark 'em!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34378] = { ["id"] = 34378, ["name"] = "Establish Your Garrison", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "It's time for the main event! We've got the materials, we've got the manpower, we've got another thing that starts with \"m.\" Let's build this thing! I got a gaggle of assistants up on that ridge to the west. They should have your personal surveying stand set up by now. Head on over there and you should be able to watch our progress from it.", ["objectivesText"] = "Watch the construction of your garrison by using the Master Surveyor Progress: I'm almost as excited about building this as you are. I want to see if it falls apart!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34379] = { ["id"] = 34379, ["name"] = "Den of Wolves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33657, 33784, 33816, 34380 }, ["description"] = "Durotan wishes for us to join him now that you have established your foothold. I hope he will accept your help.", ["objectivesText"] = "Ride the Frostwolf Rylak to Wor'gol.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76411, ["x"] = 0.447, ["y"] = 0.661 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34380] = { ["id"] = 34380, ["name"] = "Rally the Frostwolves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33657, 33784, 33816, 34379 }, ["description"] = "My brother, in his haste, has already taken some of my clan with him and has begun an assault on Bladespire Citadel before we were ready. Draka awaits by our war horn. Please let her know that it is time to rally the clan! With the aid of you and your forces, we might actually stand a chance at victory against the ogres.", ["objectivesText"] = "Ask Draka to sound the war horn. Progress: Draka will know what to do.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76557, ["x"] = 0.218667, ["y"] = 0.519333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34381] = { ["id"] = 34381, ["name"] = "The Shadow Gate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34469 }, ["description"] = "Dere be ogres in da cave, I smell de stink of 'em. Keep ye weapon handy, we gonna have ta move quick and take down de ogres before dey start tossing da mojo. <Bwu'ja peeks into the cave.> Watch ye self mon, something be going down in dere.", ["objectivesText"] = "Defeat Grubnor Wargut and follow after Borgal.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110378, 110394, 110606, 110607, 110608, 110664 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78785, ["x"] = 0.405, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78792, ["x"] = 0.395333, ["y"] = 0.235333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34392] = { ["id"] = 34392, ["name"] = "Onslaught's End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34393, 34398, 34420, 35933, 36881 }, ["description"] = "\"Guard Gul'dan and his Shadow Council with your lives! The portal cannot function without our prisoners' fel magic. Fail me and watch all that you hold dear turn to ash. -Grommash Hellscream.\" The Iron Horde appear to be holding prisoners that are crucial to keeping the portal open. Search the nearby spires!", ["objectivesText"] = "Disable the two fel spires of the Dark Portal. Progress: See the drifting energy from the tips of those spires? They clearly have some effect upon the portal. With any hope, the portal falls along with them.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34393] = { ["id"] = 34393, ["name"] = "The Portal's Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34398, 34420, 35933, 36881 }, ["description"] = "This portal is fueled by powers neither mechanical nor arcane. Look to either side of us, <name>. The screaming souls of slain prisoners are being channeled into the heart of the portal itself. And they are channeling these souls through the body of Gul'dan . Find a way into the chamber beneath us, and do whatever it takes to get Gul'dan to stop his channeling. Our last hope rests on you, <name>.", ["objectivesText"] = "Enter the Soul Engine beneath the Dark Portal, then shut the Dark Portal down. Progress: Go now, hero! Lives hang in the balance!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112387, 112388, 112389, 112391, 112392, 112393, 112395, 113579, 120304, 143742, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34397] = { ["id"] = 34397, ["name"] = "Downsizing the Darktide", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["series"] = { 34352, 34353, 34355, 34365, 34450, 35861, 35876 }, ["description"] = "This pathetic excuse for life sold out all of his companions. All it took was a little squeeze of the neck. Find the leaders of this operation and bring me their heads. Haratha will accompany you on your quest.", ["objectivesText"] = "Takedown the Darktide leadership. Progress: The Iron Horde have no concept of honor.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34398] = { ["id"] = 34398, ["name"] = "Warlords of Draenor: The Dark Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 1519, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34393, 34420, 35933, 36881 }, ["description"] = "ATTENTION HEROES ADVENTURERS DEFENDERS OF AZEROTH Archmage Khadgar , hero of the Second War, is assembling a coalition of Azeroth's strongest to bravely step through the Dark Portal and stop the Iron Horde's invasion of Azeroth. Champions who are interested in glory can meet Khadgar at the base of the Dark Portal in Blasted Lands. Safety not guaranteed.", ["objectivesText"] = "Speak with Archmage Khadgar at the foot of the Dark Portal in Blasted Lands.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34399] = { ["id"] = 34399, ["name"] = "Trouble In The Mine", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34399 }, ["series"] = { 34709 }, ["description"] = "The Jorune Mine is in trouble! We recently unearthed an exceedingly large and powerful arcane crystal; however, something has gone terribly wrong and the energy from the crystal is flooding the mine. The Auchenai have already sent their Vindicators into the mine to assist us. Speak with Vindicator Doruu inside of the mine, he'll know how you can help.", ["objectivesText"] = "Speak with Vindicator Doruu .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 52944, 54292, 54293, 55885, 131838, 131856 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78534, ["x"] = 0.498, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78538, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34400] = { ["id"] = 34400, ["name"] = "Frenzied Manafeeders", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34400 }, ["description"] = "There is a rare breed of moth in Talador known as the Manafeeder. These moths sustain themselves by feeding on arcane crystal dust from the mine. Typically speaking, these moths are nothing more than an occasional nuisance. However, they are now gorging themselves upon the intense arcane energy flooding out of the mine and have become highly territorial and aggressive. I have attuned this crystal to disperse arcane energy. Please use it on the Frenzied Manafeeders to soothe them.", ["objectivesText"] = "Use the Arcane Dissipator on 8 Frenzied Manafeeders. Progress: Have you used the Arcane Dissipator on the Manafeeders yet?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 97919, 110468, 137663 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78534, ["x"] = 0.498, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78534, ["x"] = 0.498, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34401] = { ["id"] = 34401, ["name"] = "Arcane Essence", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34401 }, ["description"] = "Kaelynara will not stop until she has drained every last drop of arcane energy from the crystal...and destroyed this entire mine in the process. The arcane shield she guards herself with cannot be penetrated by normal means, but I have a plan. If I had a focusing crystal powerful enough to momentarily pierce her shield, Kaelynara could then be dealt with. Fortunately, we are in the perfect place to build one. Start by bringing me arcane essence from the creatures rampaging throughout the mine.", ["objectivesText"] = "Retrieve 6 Arcane Essence . Progress: Have you retrieved the arcane essence for me?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110390 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34402] = { ["id"] = 34402, ["name"] = "Of Wolves and Warriors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "The return of many of my people is a boon to us, and I thank you for your part in their survival. Come, ride with me. We have much to discuss.", ["objectivesText"] = "Ride with Durotan .", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78272, ["x"] = 0.453, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70859, ["x"] = 0.388, ["y"] = 0.560667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34403] = { ["id"] = 34403, ["name"] = "Arcane Essence", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34403 }, ["description"] = "Kaelynara's lust for arcane power has consumed her and she threatens the safety of all in this mine. She must be stopped. Unfortunately, there is nothing we can do while she shields herself. We will need to find a way to penetrate her shielding spell. Perhaps if I were to build a focusing crystal, I could use it to lower her shield...I'll need you to search the crystal mine for the necessary components. First, I'll need arcane essence from the Crystal Ragers and Arcane Wraiths in the mine.", ["objectivesText"] = "Retrieve 6 Arcane Essence . Progress: Have you collected enough arcane essence yet?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110390 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78513, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78513, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34404] = { ["id"] = 34404, ["name"] = "Crystals of Unusual Power", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34404 }, ["description"] = "Arcane crystals of this size and power are quite rare even on Draenor. It is no coincidence that the Draenei built Shattrath and Auchindoun so close to this mine. I am interested in learning more about these particular crystals and their arcane nature. Return to me with any unrefined power crystals that you may find and I will make sure that you are adequately compensated for your effort.", ["objectivesText"] = "Collect 10 Unrefined Power Crystals . Progress: Have you collected the unrefined power crystals I need for my research?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110391 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34406] = { ["id"] = 34406, ["name"] = "Caught In The Chaos", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34406 }, ["description"] = "Not all of the Draenei miners made it out when the chaos erupted, <name>. Many of them are injured and still trapped inside the mine. Kaelynara's disruption has caused all hell to break loose. Arcane Wraiths are forming from the unleashed energy and attacking everything they see. The elementals that slumbered beneath the ground are emerging from the rocks frenzied and dangerous. Please find as many injured miners as you can and ensure that they return safely.", ["objectivesText"] = "Rescue 8 Injured Miners.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78513, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78513, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34407] = { ["id"] = 34407, ["name"] = "Holding the Line", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "It is good to see you again, champion. Demons are assaulting Auchindoun and we are barely standing our ground against them. We need to push our front lines forward lest our losses reach critical mass. If your blade is with us, shove it into these foul creatures' throats.", ["objectivesText"] = "Slay 15 demons in the Burning Front.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 108733, 142450, 237812 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34409] = { ["id"] = 34409, ["name"] = "Garrison Campaign: Crows In The Field", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34336, 34337, 34338, 34339, 34340, 34341, 34347, 34410 }, ["description"] = "Our druids set up a wide network of scouts to follow up on your intel from Nagrand. We've identified a suspicious Iron Horde excavation near some salt pools on the western coast of Gorgrond. We have reason to believe that these orcs are pursuing a valuable artifact deep in the desert. I'm putting together a small mission for a focused, surgical strike. I'd like you to be part of that team.", ["objectivesText"] = "Speak to Thisalee Crow at Skysea Ridge in Gorgrond.", ["rewardGold"] = 42135, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 78187, ["x"] = 0.398, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34410] = { ["id"] = 34410, ["name"] = "The Beating Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34336, 34337, 34338, 34339, 34340, 34347, 34409, 34410 }, ["series"] = { 34335, 34336, 34337, 34338, 34339, 34340, 34341, 34347, 34409 }, ["description"] = "One thing is certain. We now possess an item of great value to the Iron Horde. We had better secure this... \"Heart of Gorgorek\" at once.", ["objectivesText"] = "Deliver the Heart of Gorgorek to Morthis Whisperwing at your garrison.", ["rewardGold"] = 421350, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 78251, ["x"] = 0.542, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 107, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34414] = { ["id"] = 34414, ["name"] = "An'dure The Giant", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34414 }, ["description"] = "In order to break through Kaelynara's arcane shield, we will need a focusing crystal of rare power and quality. Within the mine is a crystal giant known to the Draenei as An'dure. The giant has slept beneath the rocky earth for ages, but due to Kaelynara's recklessness it has awakened. The heart of a crystal giant is a truly powerful artifact. Defeat An'Dure and return to me with a crystal giant heart . Once I have the heart, I will have everything I need to construct the focusing crystal!", ["objectivesText"] = "Retrieve the Crystal Giant Heart . Progress: Do you have the crystal giant heart ?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110418, 110667 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34415] = { ["id"] = 34415, ["name"] = "An'dure The Giant", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34415 }, ["description"] = "In order to break through Kaelynara's arcane shield, we will need a focusing crystal of rare power and quality. Within the mine is a crystal giant known to the Draenei as An'dure. The giant has slept far beneath the earth for ages, but due to Kaelynara's recklessness it has awakened. The heart of a crystal giant is a truly powerful artifact. Defeat An'Dure and return to me with a crystal giant heart . When you return I will construct the focusing crystal and together we will stop Kaelynara.", ["objectivesText"] = "Retrieve the Crystal Giant Heart . Progress: Do you have the crystal giant heart ?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110418 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78513, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78513, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34418] = { ["id"] = 34418, ["name"] = "Holding the Line", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["series"] = { 34696 }, ["description"] = "Auchindoun is under attack! The Auchenai are valiant warriors in their own right, but they cannot hold against these endless demon hordes alone. We came here to stop the Legion from engulfing Draenor... working together is our best shot. I need you to thin out the demons' numbers so we can regroup our forces safely and push forward into the Burning Front. We will stop their march here and now!", ["objectivesText"] = "Slay 15 demons in the Burning Front.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 142450, 237812 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34420] = { ["id"] = 34420, ["name"] = "The Cost of War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34393, 34398, 35933, 36881 }, ["description"] = "They called this operation a suicide mission, but I don't plan on throwing away any lives meaninglessly. Everybody, with me!", ["objectivesText"] = "Follow Archmage Khadgar .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 110799, 113579, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34421] = { ["id"] = 34421, ["name"] = "Bled Dry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34421, 34422, 34423, 35241 }, ["description"] = "<The orc spits out his last words.> They kept us in cages. They... drain our blood, for... rituals... <The Frostwolf coughs violently.> ...many left -- -- my... people... <The orc dies.>", ["objectivesText"] = "Free the slaves from the 2 Bleeding Hollow Cages in Heartblood.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34422] = { ["id"] = 34422, ["name"] = "Blaze of Glory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34421, 34422, 34423, 35240, 35241, 35242 }, ["description"] = "We can't stay here forever. We NEED to keep moving. But first - we need a distraction. <Khadgar conjures a small gem.> This bead should burn anything flammable that you get close to. With your skill, and a bit of luck, you might be able to take the attention of the Bleeding Hollow orcs off our group.", ["objectivesText"] = "Use the Lucifrium Bead to destroy 8 Bleeding Hollow huts. Progress: We cannot hold out here forever, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112431, 112432, 112433, 112434, 113191, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34423] = { ["id"] = 34423, ["name"] = "Altar Altercation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34421, 34422, 34423, 35240, 35241, 35242 }, ["series"] = { 34425 }, ["description"] = "You see that altar down there? There's a magical eye settled at its peak, and I fear our group will not survive if it sees us. Distract the eye, <name>. Cause a commotion, kill some ritualists, whatever you have to do - just occupy that thing long enough for me to guide the rest of our group past its gaze. <Khadgar looks over his shoulder.> Bring that strapping orc with you. The one that's not Thrall.", ["objectivesText"] = "Speak with Ariok , then help him distract the Eye of Kilrogg.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34425] = { ["id"] = 34425, ["name"] = "The Kargathar Proving Grounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34427, 34429, 34478 }, ["series"] = { 34423 }, ["description"] = "The orcs in this area look like members of the Shattered Hand clan. You can tell by looking at their hands. Let's join up with the others. We must find a way out of here.", ["objectivesText"] = "Follow Khadgar. Progress: Yes?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34427] = { ["id"] = 34427, ["name"] = "A Potential Ally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34427, 34429 }, ["description"] = "One of the captured orcs is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the amusement of his captors. Use this runestone. It should handily deal with the ring of fire that surrounds him.", ["objectivesText"] = "Use the Frostflurry Focus near the ring of fire in Kargathar Proving Grounds to free Farseer Drek'Thar .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112440, 112441, 112442, 112443 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34429] = { ["id"] = 34429, ["name"] = "Kill Your Hundred", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34427, 34429, 34478 }, ["description"] = "I see only one way out of this trap, <name>, and it's right through the middle of that arena. This might be the end of us.", ["objectivesText"] = "Survive Kargath's Arena.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 86594, 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34431] = { ["id"] = 34431, ["name"] = "Masters of Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding. All of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me. < Luuka takes a deep breath.> Ungra , Gurran, and... umm... oh! Ankova. Will you protect me from them?", ["objectivesText"] = "Slay Ungra , Taskmaster Gurran , and Ankova the Fallen . Progress: How goes your mission?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34432] = { ["id"] = 34432, ["name"] = "The Shadowmoon Clan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, <name>.", ["objectivesText"] = "Slay 10 Shadowmoon Orcs or Void Wolves within the Umbral Halls.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112663, 112664, 112665, 112666 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 78554, ["x"] = 0.549, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34434] = { ["id"] = 34434, ["name"] = "Yrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "Forgive me if I'm a bit flustered - I've never killed anyone before. My name is Yrel , and I am a student of Karabor. You say you have an ARMY with you? The Light must truly be watching over me today. I will follow you, then. Lead the way, <name>.", ["objectivesText"] = "Escort Yrel to safety.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34436] = { ["id"] = 34436, ["name"] = "Keli'dan the Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him. I will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", ["objectivesText"] = "Slay Keli'dan the Breaker .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34437] = { ["id"] = 34437, ["name"] = "The Prodigal Frostwolf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["series"] = { 34442, 34925 }, ["description"] = "I can get back to Drek'Thar myself... after I run this stinking shovel through a few Blackrock stomachs.", ["objectivesText"] = "Report to Farseer Drek'Thar at the Blackrock Quarry in Tanaan Jungle.", ["rewardGold"] = 29325, ["rewardXP"] = 710, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34439] = { ["id"] = 34439, ["name"] = "The Battle of the Forge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["description"] = "Our troops are armed - the time to strike is now! Strike swift and true, <name>!", ["objectivesText"] = "Slay 15 Blackrock Orcs and 3 Ogron Warcrushers . Progress: This dam thing is tougher than it looks.", ["rewardGold"] = 509400, ["rewardXP"] = 2125, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34440] = { ["id"] = 34440, ["name"] = "FLAG: Khadgar out of Portal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34440 }, ["series"] = { 34987, 35253, 35297, 35983 }, ["rewardGold"] = 114000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34442] = { ["id"] = 34442, ["name"] = "Ga'nar of the Frostwolf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["series"] = { 34437, 34925 }, ["description"] = "We must move on, there isn't time to waste! One of the elders of my clan, Ga'nar , is out there somewhere. I can sense him, but I cannot find him. Keep an eye out for Ga'nar . He is a strong-willed orc, and will languish in captivity.", ["objectivesText"] = "Find Ga'nar .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34445] = { ["id"] = 34445, ["name"] = "A Taste of Iron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34445, 34446, 35747, 35884 }, ["series"] = { 35747 }, ["description"] = "The way I see it, there's two ways to keep this tank from going through the portal: break the tank, or USE the dang tank ta' BLOW UP the dang portal. I can get 'er workin', I just need time. Hop in that turret off the starboard bow and keep 'em off my back.", ["objectivesText"] = "Enter the Worldbreaker Side Turret and destroy 200 Iron Horde troops. Progress: Almost there, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 65, ["name"] = "Escape From Tanaan", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34446] = { ["id"] = 34446, ["name"] = "The Home Stretch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34445, 34446, 35747 }, ["description"] = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank! Let's join up with the rest and get out of here!!", ["objectivesText"] = "Get to the docks.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 65, ["name"] = "Escape From Tanaan", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34447] = { ["id"] = 34447, ["name"] = "Kaelynara Sunchaser", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34447 }, ["description"] = "The focusing crystal is complete, <name>. When you are ready I will use the crystal to shatter Kaelynara's shield. However, it is unsafe to confront her within the mine. The moment her shield is down I will teleport us to a safe location outside of the Jorune Mine. She will be much easier to deal with when she is far away from the crystal. Speak with me when you are ready to begin.", ["objectivesText"] = "Confront Kaelynara Sunchaser . Progress: Are you prepared to end Kaelynara's madness?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 110667, 113011, 113012, 113013, 119050, 119055 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78515, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78538, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
