[34450] = { ["id"] = 34450, ["name"] = "Rylak Rescue", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["series"] = { 34352, 34353, 34355, 34365, 34397, 35861, 35876 }, ["description"] = "I managed to squeeze even more information out of our little friend here. The Darktide Matriarch is at the top of the hill. One of their lead engineers is attempting to tame the matriarch with his technology. We must stop him, <name>.", ["objectivesText"] = "Kill Razz Ricketroz at Darktide Roost.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 78937, ["x"] = 0.678, ["y"] = 0.9 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34451] = { ["id"] = 34451, ["name"] = "Sunsworn Camp", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "We no longer have a need to work alongside the Auchenai, champion. I have arranged for their lead soulbinders to continue to advise us, but I believe any action is best left to us at this point. Meet me at Sunsworn Camp, southeast of here. I can sense more demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", ["objectivesText"] = "Meet Lady Liadrin at Sunsworn Camp in Talador .", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75246, ["x"] = 0.61, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34452] = { ["id"] = 34452, ["name"] = "Light's Rest", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "With the brute force of our enemy neutralized, we must turn our sights on quelling the aftermath and preparing for any future assaults. We still need Auchindoun's defenses reinvigorated. Meet me at Light's Rest, not far south of here. We have reports coming in of demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", ["objectivesText"] = "Meet Exarch Maladaar at Light's Rest in Talador .", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 109744, 110683 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75250, ["x"] = 0.572, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34455] = { ["id"] = 34455, ["name"] = "Free their Minds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34455 }, ["description"] = "This device is what the goblins are using to control the rylaks. There is a button on the controller labeled do not touch. Get within range of a Controlled Rylak and touch the button.", ["objectivesText"] = "Use the Rylak Mind Controller on Controlled Rylaks.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 110447 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 89158, ["x"] = 0.598, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[34456] = { ["id"] = 34456, ["name"] = "Spirit of the Wolf", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34456 }, ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 25974, 25975, 25976, 25977 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34458] = { ["id"] = 34458, ["name"] = "Powering the Defenses", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 34351, 35249 }, ["description"] = "What few soulpriests we don't have on the front lines are working fervently to maintain Auchindoun's defenses. They aren't going to be able to keep it up much longer alone. Soulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. I need you to find her and get her and the pylon back here safely.", ["objectivesText"] = "Find Soulbinder Tuulani in the Tomb of Lights.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 110253, 110271 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 81789, ["x"] = 0.556, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34462] = { ["id"] = 34462, ["name"] = "Winds of Change", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Commander, I have bad news. Olin Umberhide , the tauren who escaped with you from Tanaan, was ambushed when near the eastern perimeter of the Garrison. He was seen being dragged off by the pale. These are dangerous, disturbing creatures that some believe were once orcs. Now they are husks of barely living flesh bent by dark magics. Olin is resourceful, but outnumbered. I would advise travelling east to effect a rescue as soon as possible, before they eat him alive... slowly.", ["objectivesText"] = "Rescue Olin Umberhide . Progress: Have you found Olin? Was he alive or dead?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34463] = { ["id"] = 34463, ["name"] = "Mysterious Ring", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 535, ["storyline"] = { 34463 }, ["series"] = { 34464, 34465, 34466, 34472 }, ["description"] = "This elegantly crafted ring is covered in ornate decorations and symbols, the most prominent of which being the letter \"V\" in a glowing rune. The ring seems to fade in and out of view as if passing back and forth through time. Someone at Khadgar's Tower may have an interest in such an artifact.", ["objectivesText"] = "Bring the Mysterious Ring to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: Time magic is a young field of research.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110459 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[34464] = { ["id"] = 34464, ["name"] = "Mysterious Boots", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 535, ["storyline"] = { 34464 }, ["series"] = { 34463, 34465, 34466, 34472 }, ["description"] = "Phasing back and forward in time, these flickering ornate boots are adorned with a lavish \"V\" on them. Someone at Khadgar's Tower might have insights to the nature of these strange items.", ["objectivesText"] = "Bring the Mysterious Boots to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: I was wondering \"when\" I would see you again. Ah...? Ah...? Get it? Look, for as long as anyone was speaking the bronze dragons got to hog all of the good time jokes. Well now the guardians of time are taking a break and there is no one left to stop me!", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110469 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34465] = { ["id"] = 34465, ["name"] = "Mysterious Hat", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34465 }, ["series"] = { 34463, 34464, 34466, 34472 }, ["description"] = "Energy flows from this mystical hat with an unseen strength. It hums as it drifts back and forward in time where it rests on the ground. This is the sort of object that someone at Khadgar's Tower would find very interesting.", ["objectivesText"] = "Bring the Mysterious Hat to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: It is so nice to finally be able to research my passion without those interfering bronze dragons showing up.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110470 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34466] = { ["id"] = 34466, ["name"] = "Mysterious Staff", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 535, ["storyline"] = { 34466 }, ["series"] = { 34463, 34464, 34465, 34472 }, ["description"] = "Fluctuations in reality surround this staff so much that it is hard to identify any recognizable markings aside from a large, lavish \"V\" on its apex. This might require help to identify by someone from Khadgar's Tower.", ["objectivesText"] = "Bring the Mysterious Staff to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: I did my time with fire and the other arcane arts. They were good. Nothing compares to hurling a giant ball of fire. But temporal wizardry? So much fun! Really hard to master but you always have plenty of time.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110471 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34469] = { ["id"] = 34469, ["name"] = "Cleansing the Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381 }, ["description"] = "Not all spirits are destroyed by the Soulgrinder. Some souls manage to survive more or less intact like myself. Others have become twisted and maddened. End their misery, take my soul shard and use it to purify them. Their rage will blind them to the effects of its energy so you must defeat them before you use it.", ["objectivesText"] = "Cleanse 10 Crazed Souls.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 110378, 110394, 110606, 110607, 110608, 110664 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34472] = { ["id"] = 34472, ["name"] = "Temporal Juxtaposition", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34472 }, ["series"] = { 34463, 34464, 34465, 34466 }, ["description"] = "I think I figured out what those mysterious artifacts you collected were for. It would seem someone is attempting to affect a temporal shift by sending items back into this timeline from your own timeline. Technically that shouldn't be possible. But whoever this is found a way. I think I may try a ritual to bring the traveler through.", ["objectivesText"] = "Wait for Zooti Fizzlefury 's temporal ritual to complete.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77853, ["x"] = 0.845333, ["y"] = 0.315333 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34475] = { ["id"] = 34475, ["name"] = "Garrison Invasion!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34475 }, ["description"] = "Your garrison is under attack! Use this magic device to get back there and defend it!", ["objectivesText"] = "Speak with Sergeant Grizzleface in your garrison. Provided item:", ["rewardGold"] = 28500, ["rewardXP"] = 50, ["rewardItems"] = { 110560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34478] = { ["id"] = 34478, ["name"] = "A Potential Ally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34429, 34478 }, ["description"] = "One of the captured draenei is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the orcs' amusement. Use this runestone. It should handily deal with the ring of fire that surrounds this draenei.", ["objectivesText"] = "Use the Frostflurry Focus near the ring of fire in Kargathar Proving Grounds to free Exarch Maladaar .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112440, 112441, 112442, 112443, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 1, ["flags"] = 0 } } },
