[34729] = { ["id"] = 34729, ["name"] = "Blood Oath of Na'Shra", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34729 }, ["description"] = "You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?", ["objectivesText"] = "Accept the Blood Oath of Blademaster Na'Shra.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76452, ["x"] = 0.646, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
