[35374] = { ["id"] = 35374, ["name"] = "That Pounding Sound", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35374 }, ["series"] = { 35375 }, ["description"] = "Commander. The frostwolf and I were just discussing the merits of various 'hunting' approaches. I assured her that the shadow hunters are well-equipped to deal with any situation, even ones out in the wild. She seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.' We're not going to let her get away with saying that, right? Let's take down some clefthoof.", ["objectivesText"] = "Collect 12 Pairs of Leatherhide Ears from Leatherhide clefthoof. Progress: It's unbelievable how arrogant these frostwolves can be.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113100, 118135, 118136, 118137, 118187, 118188, 118189 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82078, ["x"] = 0.825, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82078, ["x"] = 0.825, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35375] = { ["id"] = 35375, ["name"] = "Queen of the Clefthoof", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35375 }, ["series"] = { 35374 }, ["description"] = "Ogka told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense? This is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these frostwolves. We'll show Ogka how a true professional works.", ["objectivesText"] = "Collect the Horn of Banthar from Banthar. Progress: Banthar's horn. Hemet would be green with envy to have another shot at such a powerful beast.", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 113105 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82078, ["x"] = 0.825, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82078, ["x"] = 0.825, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35376] = { ["id"] = 35376, ["name"] = "Shooting the Breeze", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35376 }, ["description"] = "Taz and I are having a spirited debate over who kills more efficiently: shadow hunters or frostwolves. Care to get in on the wager, commander? I've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", ["objectivesText"] = "Collect 24 Breezestrider Horns from Breezestrider talbuk. Progress: This outsider really thinks he can come here and best me in my own land? Oh... sorry, commander. Present company excluded, of course.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113102 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82080, ["x"] = 0.825, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82080, ["x"] = 0.825, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35377] = { ["id"] = 35377, ["name"] = "Someone's Missing Axe", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35377 }, ["series"] = { 35378 }, ["description"] = "<A throwing axe of frostwolf make is sticking out of the side of this talbuk. Perhaps Stalker Ogka will be interested in your find.>", ["objectivesText"] = "Take the Frostwolf Axe to Stalker Ogka at Wor'var. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113109 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82080, ["x"] = 0.825, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["startItems"] = { 113109 } },
[35378] = { ["id"] = 35378, ["name"] = "King of the Breezestriders", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35378 }, ["series"] = { 35377 }, ["description"] = "Let me guess, you found it in a talbuk's flank? <Ogka seems lost in thought for a moment.> That axe was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot. I suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", ["objectivesText"] = "Collect Tall Buck's Tail from Tall Buck. Progress: How goes the hunt for Tall Buck?", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 113104, 114695, 114696, 114697, 114698 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82080, ["x"] = 0.825, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82080, ["x"] = 0.825, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35379] = { ["id"] = 35379, ["name"] = "Hemet's Happy Hunting Grounds", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35379 }, ["rewardGold"] = 849000, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550 },
[35380] = { ["id"] = 35380, ["name"] = "Second in Command", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35407 }, ["description"] = "Wait... I remember something else. Sir Edward ... he was shouting... looking for someone. I... I can't remember who. There were so many screams...", ["objectivesText"] = "Speak to Sir Edward at Admiral Taylor's Garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 113095, 113106, 113122, 113127 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82126, ["x"] = 0.375, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82194, ["x"] = 0.376, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 4, ["flags"] = 0 } } },
