[35834] = { ["id"] = 35834, ["name"] = "Wake of the Genesaur", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["description"] = "One moment we see a great metal beast rolling into our camp, the next a genesaur follows it and sends a wave of pure chaotic life at us. The manifestations left behind by the genesaur must be culled so we have time to salvage what we can before leaving. If you are here to help, then start killing as many of the violent plants that are assailing us as possible.", ["objectivesText"] = "Slay 9 Wild Overgrowth. Progress: This has not been a good day.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112608, 112609, 112610, 112611 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80922, ["x"] = 0.642, ["y"] = 0.518 }, { ["mapID"] = 543, ["npcID"] = 80987, ["x"] = 0.582, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80987, ["x"] = 0.582, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35835] = { ["id"] = 35835, ["name"] = "The Ebon Hunter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35713, 35716, 35719, 35739, 35782, 35878, 35879 }, ["description"] = "We're ready to set up the laser, but we're going to need more firepower to cut through this stuff. The Ebon Hunter stalks the delta just southeast from here. It has an apparatus on its face that can fire a laser way stronger than what we have hooked up. We need that. You should go get it while we set up the laser.", ["objectivesText"] = "Collect an Organic Laser Apparatus from the Ebon Hunter. Progress: By the way, that laser is very dangerous. Be careful!", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 113441, 116394 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 13, ["flags"] = 0 } } },
[35837] = { ["id"] = 35837, ["name"] = "Garrison Campaign: Deep Recon", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 35837, 35838, 35839, 35840, 35841 }, ["description"] = "One of my top field operatives, Jeanine Amrell , is stationed deep in Iron Horde territory in northern Nagrand. She reports that the warlords of the orcish clans are planning to convene in secret at Mok'gol Watchpost. This may be a critical opportunity for us to gain intel on their future plans. I need you to meet up with agent Amrell immediately. This may be our chance, <name>!", ["objectivesText"] = "Find Jeanine Amrell at the Hidden Camp in Nagrand.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83051, ["x"] = 0.498, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 102, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35838] = { ["id"] = 35838, ["name"] = "The Warlord's Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35837, 35838, 35839, 35840, 35841 }, ["description"] = "Upon closer inspection, you notice a piece of leather parchment looped around her neck. Scrawled upon it angrily are the words: \"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", ["objectivesText"] = "Find out who is behind the written note.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83051, ["x"] = 0.498, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83053, ["x"] = 0.418, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 102, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35839] = { ["id"] = 35839, ["name"] = "Plans of War", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35837, 35838, 35839, 35840, 35841 }, ["description"] = "I managed to get my hands on Jeanine's notebook. She identified several key items in the nearby buildings to investigate, but couldn't follow up before her demise. The least we can do is follow the lead that she left us. Search the camp for the intelligence. I'll keep the orcs distracted.", ["objectivesText"] = "Find the Scale Model of Gorgorek , Miniature War Machine , and Map of Tanaan Jungle .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83053, ["x"] = 0.418, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 102, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35840] = { ["id"] = 35840, ["name"] = "Intercepting the Orders", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35837, 35838, 35839, 35840, 35841 }, ["description"] = "Intelligence is the name of the game, friend. The more we know about Hellscream's plans, the easier it will be to thwart them. The Mok'gol orcs often act as Hellscream's couriers, carrying mission orders from this place to his outposts all over Draenor. Kill these riders, and recover any orders that you can find.", ["objectivesText"] = "Collect the Frostfire Mission Orders , Shadowmoon Mission Orders , and Spires of Arak Mission Orders . Progress: Do you have something for me?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 113492, 113493, 113494 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83053, ["x"] = 0.418, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 102, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35841] = { ["id"] = 35841, ["name"] = "Putting Down the Packleader", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35837, 35838, 35839, 35840, 35841 }, ["description"] = "Operations at Mok'gol Watchpost are entrusted to a mighty warrior named Packleader Vor'gash . If we can take out this fierce leader, we can shut down their communications temporarily. You can find Vor'gash patrolling the compound to the northeast. Slay him.", ["objectivesText"] = "Slay Packleader Vor'gash .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83053, ["x"] = 0.418, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 102, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35842] = { ["id"] = 35842, ["name"] = "Putting Down the Packleader", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35842, 35843, 35844, 35845, 35846 }, ["series"] = { 35843, 35844, 35845, 35846 }, ["description"] = "Da one in charge a Mok'gol Watchpost be Packleader Vor'gash . We take him out, we shut dem down. Ya ken find 'im patrolling da compound ta da nor'east. Kill 'im.", ["objectivesText"] = "Slay Packleader Vor'gash .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83054, ["x"] = 0.418, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 112, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
