[35940] = { ["id"] = 35940, ["name"] = "Orc Tooth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 35940 }, ["objectivesText"] = "Progress: It doesn't matter which tooth, an incisor... canine, premolar, whatever. I know an Orc tooth when I see one.", ["rewardGold"] = 339600, ["rewardItems"] = { 112122, 170073 }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 82909, ["x"] = 0.434, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "standard" },
