[35944] = { ["id"] = 35944, ["name"] = "Proof of Strength: Goren Tooth", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35944 }, ["description"] = "This tooth is proof of your strength at slaying goren and your gladiator friend has born witness! Take the tooth back to Jonaa and claim your accolades!", ["objectivesText"] = "Take the proof to Rangari Jonaa at Highpass in Gorgrond . Provided item:", ["rewardGold"] = 421350, ["rewardXP"] = 1570, ["rewardItems"] = { 113586 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81076, ["x"] = 0.529, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.529, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["startItems"] = { 113586 } },
[35945] = { ["id"] = 35945, ["name"] = "Greblin Fastfizzle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35945, 35970, 35972, 35973, 35985, 36095 }, ["series"] = { 35970, 35972, 35973, 36117, 37511, 37516 }, ["description"] = "I've been hanging here forever! I was flying around, surveying the area for Nixxie when -- blamo! One of those stupid ogres throws a rock right at me! My glider busted and here I am... and boy is this uncomfortable. Help me down will ya? I'll make it worth your while.", ["objectivesText"] = "Help Greblin Fastfizzle down.", ["rewardGold"] = 33100, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83686, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83734, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 105, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 116, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35946] = { ["id"] = 35946, ["name"] = "Peckers the Majestic", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 35946 }, ["description"] = "You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?", ["objectivesText"] = "Accept the Blood Oath of Blademaster Na'Shra.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[35947] = { ["id"] = 35947, ["name"] = "The Power of Poison", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 36022, 36028, 36047, 36166 }, ["description"] = "G.V.? We need a name and a location. Not damned initials. <Velonara pulls out a small vial.> This is my last vial of wracking poison . We use it to extract information from prisoners. It is... potent. Coat your weapon with it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care of the rest. I've had enough of these orcs.", ["objectivesText"] = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 97919, 107694, 109254, 111968, 111980, 111986, 113587, 116394, 116431, 119001, 137663 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35948] = { ["id"] = 35948, ["name"] = "Proof of Strength: Goren Tooth", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35948 }, ["description"] = "This tooth is proof of your strength at slaying goren and your gladiator friend has born witness! Take the tooth back to Limbflayer and claim your accolades!", ["objectivesText"] = "Take the proof to Limbflayer at Beastwatch in Gorgrond . Provided item:", ["rewardGold"] = 421350, ["rewardXP"] = 1570, ["rewardItems"] = { 113590, 116160 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 76688, ["x"] = 0.462, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["startItems"] = { 113590 } },
[35959] = { ["id"] = 35959, ["name"] = "The Power of Poison", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35926, 36023, 36029, 36048, 36165 }, ["description"] = "G.V.? We need a full name. A location! I have an idea fer how we can find those out. <Hulda pulls out a small vial.> This is my last vial o' wracking poison. We use it when we need tae extract information from prisoners. Coat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.", ["objectivesText"] = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 46725, 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 116394, 116431, 119001, 137663 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83773, ["x"] = 0.535, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83773, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35970] = { ["id"] = 35970, ["name"] = "Preservation Capitalization", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35945, 35970, 35972, 35973, 35985, 36095 }, ["series"] = { 35945, 35972, 35973, 36117, 37511, 37516 }, ["description"] = "I'm looking for precious artifacts. The kind of artifacts that can help solve some of the greatest mysteries of Draenor, and make the Steamwheedle Preservation Society a ton of moolah. And ladies love the moolah, know what I'm sayin? So, get me the artifacts, I'll get the ladies, and you get... wait, what are you looking for again?", ["objectivesText"] = "Collect a Redtooth Necklace , Purpletooth Necklace , and an Ogre Bust . Progress: What do you find? Anything worth selling? Err.. preserving.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 113594, 113603, 113615 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83734, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83734, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 105, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 116, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35972] = { ["id"] = 35972, ["name"] = "Ogre Onslaught", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35945, 35970, 35972, 35973, 35985, 36095 }, ["series"] = { 35945, 35970, 35973, 36117, 37511, 37516 }, ["description"] = "Those ogres are standing in the way of a full Steamwheedle Preservation excavation. They are brutal, violent, horrible smelling beasts. And if I'm being completely honest with myself, I'm pretty mad they broke my glider. Do me a favor will ya? Wipe 'em off the face of Draenor. It will make everyone's life easier, or at the very least, it will make my life easier.", ["objectivesText"] = "Kill 3 Ogres and 3 Ogron.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83734, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83734, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 105, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 116, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35973] = { ["id"] = 35973, ["name"] = "Brokyo Beatdown", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35945, 35970, 35972, 35973, 35985, 36095 }, ["series"] = { 35945, 35970, 35972, 36117, 37511, 37516 }, ["description"] = "I'm almost done here, but I can't leave in good conscience. I spotted an ogron named Brokyo that is wearing a priceless ring. Priceless as in crazy expensive. I'm sure Nixxie will give me a promotion if I bring that ring back to her.", ["objectivesText"] = "Kill Brokyo. Progress: Did you take care of Brokyo?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 114121 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 76508, ["x"] = 0.406, ["y"] = 0.13 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 76508, ["x"] = 0.406, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 105, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 116, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35974] = { ["id"] = 35974, ["name"] = "Assault on Darktide Roost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["storyline"] = { 35974 }, ["description"] = "The Iron Horde has Goblins now? Take them out!", ["objectivesText"] = "Disrupt the Iron Horde and gather intelligence on them.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 115020, 116978, 119093, 119364, 119400, 119411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Darktide Roost Assaulted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Collect Giant Rylak Eggs", ["amount"] = 20, ["type"] = 2, ["objectID"] = 235826, ["orderIndex"] = 1 }, { ["text"] = "Collect Large Rylak Eggs", ["amount"] = 34, ["type"] = 2, ["objectID"] = 235823, ["orderIndex"] = 2 }, { ["text"] = "Collect Rylak Eggs", ["amount"] = 100, ["type"] = 2, ["objectID"] = 234587, ["orderIndex"] = 3 }, { ["text"] = "Collect Rylak Eggs", ["amount"] = 100, ["type"] = 2, ["objectID"] = 238984, ["orderIndex"] = 4 }, { ["text"] = "Kill Iron Horde Vignette", ["amount"] = 10, ["type"] = 0, ["objectID"] = 85726, ["orderIndex"] = 5 }, { ["text"] = "Kill Iron Horde Elite", ["amount"] = 34, ["type"] = 0, ["objectID"] = 85728, ["orderIndex"] = 6 }, { ["text"] = "Kill Iron Horde Boss", ["amount"] = 50, ["type"] = 0, ["objectID"] = 85727, ["orderIndex"] = 7 }, { ["text"] = "Kill Iron Horde Soldier", ["amount"] = 100, ["type"] = 0, ["objectID"] = 83800, ["orderIndex"] = 8 }, { ["text"] = "Kill Iron Horde Peon", ["amount"] = 334, ["type"] = 0, ["objectID"] = 85729, ["orderIndex"] = 9 }, { ["text"] = "Injured Rylak", ["amount"] = 100, ["type"] = 3, ["objectID"] = 78183, ["orderIndex"] = 10 } } },
