[36047] = { ["id"] = 36047, ["name"] = "We Have Him Now", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 35947, 36022, 36028, 36166 }, ["description"] = "We have Gardul right where we want him, commander. You're far more equipped to face him than I am. Dispose of him, take his formula from his corpse, and grab as many barrels of poison as you can. I'll guard this ramp and make sure no reinforcements come to his aid.", ["objectivesText"] = "Collect Venomshiv's Secret Formula and 6 Poison Barrels . Progress: Do you have everything we need?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113630, 113635, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83899, ["x"] = 0.568, ["y"] = 0.343333 }, { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.343333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 5, ["flags"] = 0 } } },
[36048] = { ["id"] = 36048, ["name"] = "We Have Him Now", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35926, 35959, 36023, 36029, 36165 }, ["description"] = "We have Gardul right cornered, commander. Ye have a much better chance against him than me. Take him out, grab the formula from his corpse, and grab as many barrels o' poison as ye can carry. I'll stay here and make sure nae reinforcements come to Gardul's aid.", ["objectivesText"] = "Collect Venomshiv's Secret Formula and 6 Poison Barrels . Progress: I don't want to stick around here any longer than we need to.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83900, ["x"] = 0.567333, ["y"] = 0.342667 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83900, ["x"] = 0.567333, ["y"] = 0.342667 }, { ["mapID"] = 542, ["npcID"] = 83904, ["x"] = 0.571, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.567333, ["y"] = 0.342667 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 5, ["flags"] = 0 } } },
[36054] = { ["id"] = 36054, ["name"] = "Sealing Fate: Gold", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36054 }, ["objectivesText"] = "Progress: Gold is indeed treasure, but additional treasure for gold? That's the offer I present. A Seal of Twisted Fate twists time, providing a burst of additional luck just when you need it. Remember, you can only obtain three Seals of Twisted Fate per week. This counts as one of those three. Next week, I may have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36055] = { ["id"] = 36055, ["name"] = "Sealing Fate: Apexis Crystals", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36055 }, ["objectivesText"] = "Progress: You seem like the type who is always seeking power, no? These seals provide an investment, if you will, in your future power. I also seek power, but one that is a more immediate and tangible. If you manage to find some crystals, we can make a deal. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I may have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36056] = { ["id"] = 36056, ["name"] = "Sealing Fate: Garrison Resources", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36056 }, ["objectivesText"] = "Progress: That extravagant fortification you built is impressive. Tell me, does it keep all the bad things away? Yes? How about an exchange for a bit of fate? A wall can be thick enough, but one is never lucky enough. Besides, safety can be so overpriced... Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I may have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36057] = { ["id"] = 36057, ["name"] = "Sealing Fate: Honor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36057 }, ["objectivesText"] = "Progress: To kill another for honor is peculiar...a relic of an older time, perhaps? No matter, this seal is of no use to me. It is far too burdened with power for me to control. Remember, you can only collect three seals per week. This counts as one of those three. Next week, I may have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36059] = { ["id"] = 36059, ["name"] = "A Worthy Vessel", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35733, 35734, 35895, 35896, 35897, 36059 }, ["series"] = { 35896 }, ["description"] = "The time has come, $p. Awaken the Talon King from his long slumber. Call him into this world so that he may destroy our enemies!", ["objectivesText"] = "Awaken the Talon King.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80153, ["x"] = 0.4636, ["y"] = 0.4612 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84122, ["x"] = 0.465333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4636, ["y"] = 0.4612 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 47, ["name"] = "Terokk's Legend", ["orderIndex"] = 5, ["flags"] = 0 } } },
