[36131] = { ["id"] = 36131, ["name"] = "Proving Your Worth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36131 }, ["series"] = { 34758, 36132, 36141 }, ["description"] = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the icespine stingers you brought me. Use it to catch the Zangar eels in these coastal waters.", ["objectivesText"] = "Prove your worth to Mokugg Lagerpounder by catching 5 Zangar Eels using the supplied bait. Progress: Catch those eels?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110292, 114625, 114628 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 79896, ["x"] = 0.556, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 79896, ["x"] = 0.556, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36132] = { ["id"] = 36132, ["name"] = "Anglin' In Our Garrison", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36132 }, ["series"] = { 34758, 36131, 36141 }, ["description"] = "You have proven your worth, traveler. Now take this frostwolf fishing journal back to your garrison and study up. You will be catching all you can eat in no time.", ["objectivesText"] = "Return to Mak'jin with the Frostwolf Fishing Journal . Progress: We can use that as bait?!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 114627, 248335 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 79896, ["x"] = 0.556, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36134] = { ["id"] = 36134, ["name"] = "Garrison Campaign: Awakening", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36134 }, ["series"] = { 36341 }, ["description"] = "We've tracked Warlord Bladefury and the stolen artifact to the salt fields of western Gorgrond. Thisalee Crow will meet you there with an advance scouting team. The entire garrison is on high alert. We must be ready to intercept the enemy if necessary.", ["objectivesText"] = "Speak to Thisalee Crow at Gorgorek's Rest in Gorgrond. Progress: This isn't looking good.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84185, ["x"] = 0.41, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36136] = { ["id"] = 36136, ["name"] = "Garrison Campaign: Awakening", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36136 }, ["series"] = { 36342 }, ["description"] = "We've tracked Warlord Bladefury an' da stolen artifact ta northern Gorgrond. Choluna be dere wit a scouting team. I got dey entire garrison on high alert. Go, meet wit her, and intercept da enemy if necessary.", ["objectivesText"] = "Speak to Choluna at Gorgorek's Rest in Gorgrond.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 88530, ["x"] = 0.41, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36137] = { ["id"] = 36137, ["name"] = "Easing into Lumberjacking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36137 }, ["series"] = { 36138 }, ["description"] = "<Sir/Ma'am>, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work. While I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree an able-bodied lazy-good-for-nothing peon will come and chop it down and give you the timber. Frostfire isn't the best place for timber, but I did see a suitable small tree nearby.", ["objectivesText"] = "Harvest a Timber Sample from Small Timber and return it to Lumber Lord Oktron . Progress: This garrison isn't going to build itself, commander! We need timber!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 114827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36138] = { ["id"] = 36138, ["name"] = "Turning Timber into Profit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36138 }, ["series"] = { 36137 }, ["description"] = "Now that you know how to put peons to work harvesting timber , we're going to create a work order for your mill. But first we're going to need some timber to process! All around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order. And as usual, let the peons do the hard work. Just keep 'em protected. Draenor's a dangerous place!", ["objectivesText"] = "Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill. Progress: We need lots and lots of timber , commander!", ["rewardGold"] = 509400, ["rewardXP"] = 2125, ["rewardItems"] = { 114781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36140] = { ["id"] = 36140, ["name"] = "Pandaria 88-90", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 36140 }, ["rewardGold"] = 114000, ["rewardXP"] = 400, ["rewardItems"] = { 156698 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[36141] = { ["id"] = 36141, ["name"] = "Icespine Stingers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36141 }, ["series"] = { 34758, 36131, 36132 }, ["description"] = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior. The canyon north of us is full of icespine stingers . Slaughter them and bring their stingers back to me. They should work well as bait in these local waters.", ["objectivesText"] = "Prove your worth to Mokugg Lagerpounder by collecting 4 Icespine Stingers . Progress: Have those stingers for me?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 114679 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 79896, ["x"] = 0.556, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 79896, ["x"] = 0.556, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36142] = { ["id"] = 36142, ["name"] = "Sharper Blades, Bigger Timber", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36142 }, ["description"] = "Incredible news, Commander <name>. Your ever-loyal servant (that's me) has managed to secure us timber lords. Now maybe you don't know what a timber lord is, so let explain: think of a blood-crazed, mass murderer who enjoys nothing more than killing. Now take that same enthusiasm for killing and apply it to killing trees! That's a timber lord. What this means is that we can now cut medium sized timber - but first we need to give these timber lords a test run. There's a suitable tree nearby. Good luck!", ["objectivesText"] = "Harvest a Timber Sample from Timber and return it to Lumber Lord Oktron . Progress: Did you harvest that timber sample yet?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 114898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
