[36160] = { ["id"] = 36160, ["name"] = "Garrison Campaign: Every Rose Has Its Thorn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 36160, 36161, 36162 }, ["description"] = "These feelings are too strong. I can no longer hide my love away. I need to tell Thorn the truth. I need to tell Thorn, I love her. She mentioned her favorite flower is a rose. I've been so heads down with my work... I don't even know where I could find a rose on Draenor.", ["objectivesText"] = "Find Baros a rose for Thorn. Progress: We are under attack!", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 114779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 108, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[36161] = { ["id"] = 36161, ["name"] = "Where There Is Smoke...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 36160, 36161, 36162 }, ["description"] = "Burning Blade assassins have infiltrated the garrison. We must not let them take the Heart of Gorgorek, commander.", ["objectivesText"] = "Kill Rag'sla Thunkblade , Akatha Blazeburn , and Drek the Firecaller .", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 108, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36162] = { ["id"] = 36162, ["name"] = "A Stolen Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 36160, 36161, 36162 }, ["description"] = "Don't let Azuka take the heart, commander. Don't let her win.", ["objectivesText"] = "Kill Azuka Bladefury .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 108, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[36163] = { ["id"] = 36163, ["name"] = "Garrison Campaign: The Exarch's Call", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 36163, 36164, 36167, 36168, 36169, 36193 }, ["series"] = { 36164, 36167, 36168, 36169 }, ["description"] = "Ahhh, just the <race> I were hopin' ta see, my dear. Yrel stopped by the garrison earlier lookin' fer ya. Such a lovely lass, that one! Asked me all about ma family back home when I be feelin' homesick. Bless her. Anyway, what were I goin' on about ag'in? Oh! She asked if ye'd meet her at Elodor to the east. She's been invited by the draenei council ta face the Exarch trials, whatever those may be. Anyway, ye'd better scooch!", ["objectivesText"] = "Speak to Yrel at Elodor in Shadowmoon Valley.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 106, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[36164] = { ["id"] = 36164, ["name"] = "The Trial of Courage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36163, 36164, 36167, 36168, 36169, 36193 }, ["series"] = { 36163, 36167, 36168, 36169 }, ["description"] = "An Exarch must be a pillar of strength, and no greater strength is there than the courage to face danger. Far to the northwest, among the snowy crags of Frostfire Ridge, lives a primal fury named Everburn . Only when you face one of these creatures eye to eye, will you know the extent of your courage.", ["objectivesText"] = "Kill Everburn .", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80078, ["x"] = 0.584, ["y"] = 0.260571 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84973, ["x"] = 0.75, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.260571 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 106, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36165] = { ["id"] = 36165, ["name"] = "No Time to Waste", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35926, 35959, 36023, 36029, 36048 }, ["description"] = "We're in luck, commander. The antidote is relatively easy tae make. I've made a small amount with what I had on me. You should take it tae Kolrigg before it's too late. It'll keep him alive long enough for me tae make more.", ["objectivesText"] = "Administer the Spiresalve to Kolrigg Stoktron in Southport. Progress: <Kolrigg grumbles incoherently.>", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 114820, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83900, ["x"] = 0.567333, ["y"] = 0.342667 }, { ["mapID"] = 542, ["npcID"] = 83904, ["x"] = 0.571, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84261, ["x"] = 0.396, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.567333, ["y"] = 0.342667 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 6, ["flags"] = 0 } } },
[36166] = { ["id"] = 36166, ["name"] = "No Time to Waste", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 35947, 36022, 36028, 36047 }, ["description"] = "Commander, we're in luck. The antidote recipe is fairly simple. I was able to make a small amount with what I had on me. You should take it to Lunzul before it's too late. It should keep her alive long enough for me to make more.", ["objectivesText"] = "Administer the Spiresalve to Lunzul in Axefall. Progress: < Lunzul grumbles incoherently.>", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 114820, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84259, ["x"] = 0.4, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 6, ["flags"] = 0 } } },
[36167] = { ["id"] = 36167, ["name"] = "The Trial of Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36163, 36164, 36167, 36168, 36169, 36193 }, ["series"] = { 36163, 36164, 36168, 36169 }, ["description"] = "The Trial of Heart is a test of your willingness to persevere in the face of great adversity. Far to the west, there is a rangari outpost at Cerulean Lagoon. They have sent a request for help. Some sort of infection is making everyone in the area sick. They desperately need aid. Go and seek out the rangari stationed there. Help them find the cause of this terrible ailment.", ["objectivesText"] = "Speak to Yrel at Cerulean Lagoon, then find out the cause of the poisonous mist.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84975, ["x"] = 0.752, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.589667, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 106, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[36168] = { ["id"] = 36168, ["name"] = "The Trial of Faith", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36163, 36164, 36167, 36168, 36169, 36193 }, ["series"] = { 36163, 36164, 36167, 36169 }, ["description"] = "No Exarch trial is complete without a holy pilgrimage to the sacred resting place of our fallen champions. On the way, I ask that you take Vindicator Maraad's ashes and lay them to rest within the hallowed halls of Auchindoun. There, the spirits of our fallen ancestors will test Yrel's greatest weakness. Good luck.", ["objectivesText"] = "Speak to Soulbinder Tuulani outside the entrance to Auchindoun, then pass the Trial of Faith.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84974, ["x"] = 0.75, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.6184, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 106, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[36169] = { ["id"] = 36169, ["name"] = "The Trial of Champions", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36163, 36164, 36167, 36168, 36169, 36193 }, ["series"] = { 36163, 36164, 36167, 36168 }, ["description"] = "The first three trials you have passed with flying colors. For the final trial, you shall face the Exarch Council. Speak to me when you are ready to begin.", ["objectivesText"] = "Defeat the Exarch Council.", ["rewardGold"] = 842700, ["rewardXP"] = 1365, ["rewardItems"] = { 115530, 119144, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84974, ["x"] = 0.75, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84974, ["x"] = 0.75, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 106, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[36170] = { ["id"] = 36170, ["name"] = "Treasure: Femur of Improbability", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 36170 }, ["rewardGold"] = 171000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36171] = { ["id"] = 36171, ["name"] = "Botani Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36171 }, ["description"] = "The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.", ["objectivesText"] = "Repel the botani invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["rewardItems"] = { 122404 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36176] = { ["id"] = 36176, ["name"] = "A Call for Huntsman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36176 }, ["series"] = { 36177, 36185 }, ["description"] = "<The note is barely legible, but it seems to be an advertisement for a local hunting competition out of Embaari Village.> \"Any and all competitors are welcome to test their skills in a friendly hunting challenge.\"", ["objectivesText"] = "Deliver the Dirty Note to Fanara in Embaari Village to join the competition. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 114877 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84385, ["x"] = 0.442, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 114877 } },
[36179] = { ["id"] = 36179, ["name"] = "Unwanted Pests", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "Those creatures out in the shallows keep busting the turrets as fast as we can get them operational. I'm supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this! Could you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop? Just let Gazwitz know you covered for me so I can get reimbursed for the repair.", ["objectivesText"] = "Kill 10 Spore Drifters or Fungal Hulks in Sporemist Shallows.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85062, ["x"] = 0.625, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81128, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 11, ["flags"] = 0 } } },
[36182] = { ["id"] = 36182, ["name"] = "Tree-i-cide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36182 }, ["description"] = "Commander, the goblins have brought you a present. They call it the Tree Murderer 9000. What's it do? I reckon it murders trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot! There's a large piece of timber ready to be murdered nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", ["objectivesText"] = "Harvest a Timber Sample from Large Timber and return it to Lumber Lord Oktron . Progress: Did you harvest that timber sample yet?", ["rewardGold"] = 1123600, ["rewardXP"] = 2830, ["rewardItems"] = { 114899 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36183] = { ["id"] = 36183, ["name"] = "Admiral Taylor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35295, 35322, 36183 }, ["description"] = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself. We never heard from him again, but we have our orders. Please... please find him. He went towards the farm.", ["objectivesText"] = "Find Admiral Taylor at Admiral Taylor 's Farm.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 114945, 118079, 118080, 118081, 118082, 118083, 118084, 118085, 118086, 119348 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82278, ["x"] = 0.376, ["y"] = 0.538 }, { ["mapID"] = 542, ["npcID"] = 82293, ["x"] = 0.376, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82375, ["x"] = 0.368, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 7, ["flags"] = 0 } } },
[36184] = { ["id"] = 36184, ["name"] = "Mother Lode", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 36184 }, ["rewardGold"] = 28090, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[36185] = { ["id"] = 36185, ["name"] = "Fair Trade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36185 }, ["series"] = { 36176, 36177 }, ["description"] = "Alright. Here you go. Be sure to deliver them to Garaal quickly. He has a heavy interest in detail and fine craftsmanship. He'll surely appreciate your work.", ["objectivesText"] = "Garaal awaits your delivery. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111818, 114902, 115358, 211279 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84385, ["x"] = 0.442, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84492, ["x"] = 0.45, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36189] = { ["id"] = 36189, ["name"] = "Easing into Lumberjacking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36189 }, ["series"] = { 36192 }, ["description"] = "<Sir/Ma'am>, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work. While I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree a lumberjack will come chop it down and give you the timber. Let's give our lumberjacks a test run. There's a tree nearby!", ["objectivesText"] = "Harvest a Timber Sample from Small Timber and return it to Justin Timberlord . Progress: This garrison isn't going to build itself, commander! We need timber!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 114827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36192] = { ["id"] = 36192, ["name"] = "Turning Timber into Profit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36192 }, ["series"] = { 36189 }, ["description"] = "Now that you know how to put lumberjacks to work harvesting timber , we're going to create a work order for your mill. But first we're going to need some timber to process! All around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order. And as usual, let the lumberjacks do the hard work. Just keep 'em protected. Draenor's a dangerous place!", ["objectivesText"] = "Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill. Progress: We need lots and lots of timber , commander!", ["rewardGold"] = 509400, ["rewardXP"] = 2125, ["rewardItems"] = { 114781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36193] = { ["id"] = 36193, ["name"] = "An Act of Kindness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36163, 36164, 36167, 36168, 36169, 36193 }, ["description"] = "I know that you and Vindicator Yrel are here on important matters, but I must ask you a favor. A squad of rangari left on patrol just before the poisonous mist set in. If they were caught out in the swamp, they are surely in trouble. Harvest the Restorative Goldcaps growing among the reeds, and use them to restore any fallen rangari that you find. If you find yourself in trouble, eat one to combat the poison.", ["objectivesText"] = "Use Restorative Goldcaps to revive fallen rangari. Progress: Were you able to find the others?", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 114926 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84459, ["x"] = 0.494, ["y"] = 0.166 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84459, ["x"] = 0.494, ["y"] = 0.166 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.166 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 106, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[36194] = { ["id"] = 36194, ["name"] = "Sharper Blades, Bigger Timber", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36194 }, ["description"] = "Incredible news, Commander <name>. Your ever-loyal servant has managed to secure us commandojacks. Now maybe you don't know what a commandojack is, so let me explain: they're like lumberjacks, only highly trained in the art of killing. Mostly they're out of work mercenaries and assassins. What this means is that we can now cut medium sized timber - but first we need to give these commandojacks a test run. There's a suitable tree nearby. Good luck!", ["objectivesText"] = "Harvest a Timber Sample from Timber and return it to Justin Timberlord . Progress: Did you harvest that timber sample yet?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 114898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36195] = { ["id"] = 36195, ["name"] = "Tree-i-cide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36195 }, ["description"] = "Commander, your engineers have brought you a present. They call it the Wood Annihilator XXI the Third, Jr. What's it do? I reckon it annihilates trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot! There's a large piece of timber ready to be annihilated nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", ["objectivesText"] = "Harvest a Timber Sample from Large Timber and return it to Justin Timberlord . Progress: Did you harvest that timber sample yet?", ["rewardGold"] = 1123600, ["rewardXP"] = 2830, ["rewardItems"] = { 114899 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36199] = { ["id"] = 36199, ["name"] = "Moonshell Claws", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36199 }, ["series"] = { 34194, 36201, 36202 }, ["description"] = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior. The beach southeast of us is full of moonshell crawlers. Slaughter them and bring their claws back to me. They should work well as bait in these local waters.", ["objectivesText"] = "Prove your worth to Madari by collecting 4 Moonshell Claws . Progress: Have those claws for me?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 60854, 114873, 114874, 114876 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84372, ["x"] = 0.27, ["y"] = 0.065 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84372, ["x"] = 0.27, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36201] = { ["id"] = 36201, ["name"] = "Proving Your Worth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36201 }, ["series"] = { 34194, 36199, 36202 }, ["description"] = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the moonshell claws you brought me. Use it to catch the shadow sturgeon in these coastal waters.", ["objectivesText"] = "Prove your worth to Madari by catching 5 Shadow Sturgeon using the supplied bait. Progress: Catch those sturgeon?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 34861, 110292, 114873, 114874, 114876 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84372, ["x"] = 0.27, ["y"] = 0.065 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84372, ["x"] = 0.27, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36205] = { ["id"] = 36205, ["name"] = "The Fractured Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36205 }, ["series"] = { 36207, 36230, 36238 }, ["description"] = "It is obvious that this elaborate smithing hammer has seen better days. Now fractured and dirty, it is merely a shadow of its former self. One thing is certain, its previous owner was neither ogre nor Iron Horde. Perhaps someone at Stonefang Outpost would know who this belongs to.", ["objectivesText"] = "Search Stonefang Outpost for the hammer's previous owner. Progress: What do you want, <race>?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 114965 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78989, ["x"] = 0.412, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["startItems"] = { 114965 } },
[36208] = { ["id"] = 36208, ["name"] = "The Crystal Shard", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I'm glad you arrived when you did. The Laughing Skull orcs practice some strange spirit magic, but one of their traditions could be quite useful in our situation. While I make preparations, can you gather the reagents? First, we'll need crystals from the husks of goren corpses. You can find their bodies in the canyon.", ["objectivesText"] = "Collect 25 Goren Crystals from Longtooth Gorgers. Progress: I have learned some of the Laughing Skull traditions. This is less strange than many.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 23985, 23986, 23989, 112863, 112864, 112865, 112911, 119076, 119085 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 27, ["flags"] = 0 } } },
[36209] = { ["id"] = 36209, ["name"] = "What's Under There?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "It is done. With this enchantment, not only can you roam amongst the goren freely, but you can move as they do. Your travels through the canyon are now made easier. You have safe access to places otherwise impossible to reach. Perhaps these tunnels will lead to more information that could be used against the Iron Horde.", ["objectivesText"] = "Use the goren disguise to explore locations in Gorgrond . Progress: That goren disguise smells awful.", ["rewardGold"] = 254700, ["rewardXP"] = 2090, ["rewardItems"] = { 112958, 114963 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 30, ["flags"] = 0 } } },
[36210] = { ["id"] = 36210, ["name"] = "Hard Shell", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I have already learned much from watching the Laughing Skull. Traveling through goren tunnels was thought to be impossible due to the acid they leave behind, but the orcs found a way around it. We will need some of the shells of goren within the canyon. If you see any of their tunnel craters ready to burst, approach them and goren will come pouring out. This way, you can kill many at once and find the shells more quickly.", ["objectivesText"] = "Collect 9 Goren Shells from Boneyard Gorgers. Progress: Goren seem willing to eat anything in their path, alive or otherwise.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112786 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 28, ["flags"] = 0 } } },
[36219] = { ["id"] = 36219, ["name"] = "Garrison Campaign: The Ring of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36220, 36221, 36222, 36280, 36281, 36282 }, ["description"] = "Hey Champ, You were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? Who am I kidding, who wouldn't be interested in fame, fortune, and brawlin'? I'll meet you at my stash so we can talk a bit in private before your big debut. <A map is included with a dollar sign scrawled on an abandoned ogre tower.>", ["objectivesText"] = "Speak to Gurgthock at Gurgthock 's Stash in Nagrand.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84637, ["x"] = 0.63, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[36220] = { ["id"] = 36220, ["name"] = "How Tough Are You?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36219, 36221, 36222, 36280, 36281, 36282 }, ["description"] = "Mogor's holding a special match over at the Ring of Blood to crown the new Blood Champion and I think you have what it takes! Now, these ogres respect one thing and one thing only: badass...ness. They have a big fella at the front door making sure only the toughest gladiators enter the proving grounds. If you're in, kill the grizzled gladiator Lug'dol at the tower just up the road and present his head to Kroggol the Wall . That oughta show 'em what you're made of.", ["objectivesText"] = "Kill Lug'dol and present his head to Kroggol the Wall outside the Gorian Proving Grounds. Progress: Nobody gets in da proving grounds unless I say so.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 63151, 63152, 63153, 63154, 63155, 114976, 175616, 175617, 175618, 175619 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84637, ["x"] = 0.63, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84720, ["x"] = 0.568, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36221] = { ["id"] = 36221, ["name"] = "Entry Fee", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36219, 36220, 36222, 36280, 36281, 36282 }, ["description"] = "You looking for da Ring of Blood? HAH! That good one. Not just anybody able to compete in da ring. You gotta pay the entry fee: fifty blood marks. How do you get them? Oh, tiny one, you killing me! <Kroggol hands you a small stone caked in blood.> Dat one is yours. You kill others in da proving grounds to get da rest. Take dem to Wodin da troll servant by Mogor when you done. Don't talk to Mogor, though. Mogor da boss.", ["objectivesText"] = "Gather 50 Blood Stones and bring them to Wodin the Troll Servant. Progress: Don't be wastin' my time, <race>. What business do you be havin' with Mogor?", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 114996 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84720, ["x"] = 0.568, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84784, ["x"] = 0.568, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[36222] = { ["id"] = 36222, ["name"] = "The Champion of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36219, 36220, 36221, 36280, 36281, 36282 }, ["description"] = "You have da blood stones required as proof of your worth. Hmm. Yes, you might be da champion Mogor be lookin' for. You be one of only two to complete da blood stone trial. Da two of ya be fightin' for da glory of becoming Blood Champion. Speak to Gurgthock and we be seein' if you be a champion... or just another stain on da arena floor.", ["objectivesText"] = "Speak to Gurgthock to participate in the Blood Champion fight. Progress: Only da very best be havin' a chance at bein' da Blood Champion, mon.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 7736, 41815, 63792, 90459, 237812 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84784, ["x"] = 0.568, ["y"] = 0.13 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84784, ["x"] = 0.568, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[36223] = { ["id"] = 36223, ["name"] = "Leave Every Soldier Behind", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The ogron possess something of value to the Iron Horde. I am sure they're unaware, likely just bored and in need of something to torture. We could simply leave them to their fate, but we should follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond 's most fearsome creatures into weapons. Try to find Corporal Thukmar and his notes.", ["objectivesText"] = "Find Corporal Thukmar and recover his intel. Progress: Again you've done well, friend.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 113629 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 31, ["flags"] = 0 } } },
[36230] = { ["id"] = 36230, ["name"] = "The Restless Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36230 }, ["series"] = { 36205, 36207, 36238 }, ["description"] = "This hammer was once used to craft magnificent weapons for my Frostwolf brothers and sisters. When I was taken prisoner by the Thunderlords, however, I refused to wield it. How could I craft weapons to be used against my own people? It saddens me to see that it has been damaged and abused. I wished to one day pass it down to Kugra, but now, her anger prevents her from even visiting my grave. Please $p, can you help me repair my hammer and seek revenge on those that caused this? For Kugra....", ["objectivesText"] = "Slay Kurgthuk the Merciless and use Waruk's hammer to salvage equipment from the Thunderlord orcs. Progress: So, it is done?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 114964, 114969, 114977 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 84494, ["x"] = 0.436, ["y"] = 0.507 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84494, ["x"] = 0.436, ["y"] = 0.507 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.507 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36236] = { ["id"] = 36236, ["name"] = "The Cryptic Tome of Tailoring", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36236 }, ["series"] = { 36262, 36266, 36269 }, ["description"] = "The different sections of the tome describe tailoring techniques that seem strange compared to traditional methods. The author's name does not appear anywhere in the tome. Maybe someone in your garrison knows more about the book's origins.", ["objectivesText"] = "Speak to Aerun in your garrison. Progress: What have you there, child?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 114972 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["startItems"] = { 114972 } },
[36239] = { ["id"] = 36239, ["name"] = "A Mysterious Satchel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36239 }, ["series"] = { 36240, 36241 }, ["description"] = "An empty satchel with an old, magical aura. It appears quite dilapidated, with remnants of herbs and mushrooms along the inner lining. Perhaps exploring Umbrafen will offer a clue.", ["objectivesText"] = "Find the satchel's owner. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 104260, 111815, 111923, 114984, 114986 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84724, ["x"] = 0.578, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 114984 } },
[36241] = { ["id"] = 36241, ["name"] = "The Power of Preservation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36241 }, ["series"] = { 36239, 36240 }, ["description"] = "The ink is very precious to our people. It has the ability to preserve ancient texts. Master Ardule can explain further. He's just inside.", ["objectivesText"] = "Deliver the ink to Master Ardule.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111815, 111923, 114984, 114986, 114987, 114989 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84724, ["x"] = 0.578, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84728, ["x"] = 0.582, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36242] = { ["id"] = 36242, ["name"] = "Where There Is Smoke...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 36242, 36248, 36261 }, ["series"] = { 36248, 36261 }, ["description"] = "You garrison is under attack by the Burning Blade! Kill the Burning Blade masters that are leading the assault and report back to Warmaster Zog .", ["objectivesText"] = "Kill Rag'sla Thunkblade , Akatha Blazeburn , and Drek the Firecaller .", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 119, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[36248] = { ["id"] = 36248, ["name"] = "A Stolen Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 36242, 36248, 36261 }, ["series"] = { 36242, 36261 }, ["description"] = "This invasion is clearly an attempt to seize the Heart of Gorgorek. We need to fortify our guard before it's too late!", ["objectivesText"] = "Defeat Azuka Bladefury .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 119, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36255] = { ["id"] = 36255, ["name"] = "Enchanted Highmaul Bracer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36255 }, ["series"] = { 36256, 36257, 36260 }, ["description"] = "A powerful enchantment emanates from these ancient Highmaul bracers. Maybe Yu'rina the Mystic , your garrison enchanting quartermaster, can tell you more about the bracer.", ["objectivesText"] = "Take the bracer to Yu'rina the Mystic in your Garrison. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 115008 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 115008 } },
[36257] = { ["id"] = 36257, ["name"] = "Failed Apprentice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36257 }, ["series"] = { 36255, 36256, 36260 }, ["description"] = "Oru'kai was the first ogre mage to master the art of enchanting. Upon his death, his items were scattered across Draenor. I have tracked his scepter to the field you see before us. As you can see, the scepter's enchantment is making it difficult to retrieve. A would-be apprentice, Torag Stonefury , took one of Oru'kai's rings in to break the enchantment, but he failed and became trapped in ice. Free Torag, take the ring, and complete his task, and I will consider a reward.", ["objectivesText"] = "Find and release Torag from his icy prison.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 84739, ["x"] = 0.543, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84747, ["x"] = 0.558, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.543, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36260] = { ["id"] = 36260, ["name"] = "Oru'kai's Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36260 }, ["series"] = { 36255, 36256, 36257 }, ["description"] = "If I had known being an enchanter was this dangerous, I would have stayed in Wor'gol. Here, take this ring. The bird man told me to use the ring on the scepter to nullify the enchantment. Bring the scepter back to him and maybe he will teach you what he promised to teach me.", ["objectivesText"] = "Retrieve Oru'kai's scepter and return it to Delath. Progress: Do you have it? Give it to me.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111817, 111922, 114990, 115011 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 84747, ["x"] = 0.558, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84739, ["x"] = 0.543, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36261] = { ["id"] = 36261, ["name"] = "Garrison Campaign: Missing Grunt", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 36242, 36248, 36261 }, ["series"] = { 36242, 36248 }, ["description"] = "With the Heart of Gorgorek residing inside the garrison walls, we need to stay vigilant. The Burning Blade are known for attacking swiftly, and without warning. I have a number of grunts patrolling the keep. Dul'zak , one of our newer recruits, should have reported back by now.", ["objectivesText"] = "Find Dul'zak .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 119, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[36269] = { ["id"] = 36269, ["name"] = "Hexcloth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36269 }, ["series"] = { 36236, 36262, 36266 }, ["description"] = "I shall now impart to you the finer points of creating hexcloth. The process is quite simple. It involves immersing carefully woven fur into the ichor drawn from Gorgrond Flytraps. Normally, you would need to harvest it yourself, but I actually managed to liberate some from the Shadowmoon during their last raid. You are welcome to use it.", ["objectivesText"] = "Use Ameeka 's Flytrap Ichor to create a Swatch of Hexweave. Progress: Were you successful, friend?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111816, 115357 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84523, ["x"] = 0.582, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84523, ["x"] = 0.582, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36271] = { ["id"] = 36271, ["name"] = "Breaking into the Trap Game", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36271 }, ["description"] = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here. We can get a load of leather from the elekk, or furs from the talbuk, right here in Shadowmoon. Take this iron trap and use it on a wounded adult talbuk or elekk, then bring the trap on back here and we'll start a work order.", ["objectivesText"] = "Use the Iron Trap to capture an Elekk or Talbuk in Shadowmoon Valley and then place a Work Order at your Barn. Progress: Have you tried your hand at trapping yet?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 86607, 111556, 111557, 113991, 114821, 137663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36272] = { ["id"] = 36272, ["name"] = "Feeding An Army", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36272 }, ["description"] = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one! Mind giving 'er a run, commander? The Improved Iron Trap will let you capture some of the meatiest wildlife, like the big boars and riverbeasts out in Gorgrond . We'll be able to turn them into some tasty steaks.", ["objectivesText"] = "Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn. Progress: Did ya try the trap out yet?", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 97919, 115009 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36273] = { ["id"] = 36273, ["name"] = "Whacking Weeds", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36273 }, ["description"] = "Something needs to be done about the podling menace in Spiteleaf Thicket! Alongside Hemet Nesingwary, I've hunted some of the largest and most terrifying beasts around. Never in my life have I encountered a creature as vile, depraved, nefarious or degenerate as a podling! The vicious little monsters spread themselves like weeds and if something isn't done, they'll spread across the entire continent! Make your way into Spiteleaf Thicket and slay as many podlings as you can find!", ["objectivesText"] = "Slay 20 Spiteleaf podlings.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84632, ["x"] = 0.774, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84632, ["x"] = 0.774, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[36274] = { ["id"] = 36274, ["name"] = "Bigger Trap, Better Rewards", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36274 }, ["description"] = "Good news, commander! With the materials we've gathered here in Draenor, we've been able to construct a trap strong enough to immobilize even the mightiest beast! Why don't you head on out to Nagrand and give it a try? Word has it that the western plains are home to some of the most magnificent beasts this side of Crystal Lake. I'm going to warn you, though, these beasts are tough. You may want to bring some friends along.", ["objectivesText"] = "Use the Deadly Iron Trap to capture an Ironhide Bull, Direfang Alpha, or Wetland Trampler. Progress: Well? How'd it go?", ["rewardGold"] = 339600, ["rewardXP"] = 5990, ["rewardItems"] = { 97919, 115010, 137663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[36275] = { ["id"] = 36275, ["name"] = "The Search For Research", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36275 }, ["series"] = { 35146, 36284, 36285 }, ["description"] = "My research notes are missing! They must have gone missing during the podling attack on the research station. All of my work will be lost if they are not found! Come to think of it, I'm also missing my expedition supply bag, as well as my anti-fungal boots .... How can I do biological research without my equipment?! No... this will not do at all. Please, go and search the Zangar Shore for my missing belongings so that I may continue my fungal research!", ["objectivesText"] = "Return the Research Journal , Expedition Supplies , and Anti-fungal Boots to Dr. Hadley Ricard . Progress: Have you retrieved my missing belongings?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 115272, 115274, 115275, 116829, 116830, 116831, 119063, 119071 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84861, ["x"] = 0.866, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84861, ["x"] = 0.866, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.866, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[36280] = { ["id"] = 36280, ["name"] = "Garrison Campaign: The Ring of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36219, 36220, 36221, 36222, 36281, 36282 }, ["description"] = "Hey Champ, You were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? You're the one that brought a new meaning to pain at the Ring of Trials not too long ago, right? This is the next step in your climb to fame! You've gotta get down here. I'll meet you at my stash so we can talk a bit in private before your big debut. <A map is included with a dollar sign scrawled on an abandoned ogre tower.>", ["objectivesText"] = "Speak to Gurgthock at Gurgthock 's Stash in Nagrand.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84637, ["x"] = 0.63, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[36281] = { ["id"] = 36281, ["name"] = "Garrison Campaign: The Ring of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36219, 36220, 36221, 36222, 36280, 36282 }, ["description"] = "Hey Champ, You were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? If you think the Stonemaul arena was a thrill, this is way, way bigger than that. It's going to be HUGE, I'm calling it now. I'll meet you at my stash so we can talk a bit in private before your big debut. <A map is included with a dollar sign scrawled on an abandoned ogre tower.>", ["objectivesText"] = "Speak to Gurgthock at Gurgthock 's Stash in Nagrand.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84637, ["x"] = 0.63, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[36282] = { ["id"] = 36282, ["name"] = "Garrison Campaign: The Ring of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["series"] = { 36219, 36220, 36221, 36222, 36280, 36281 }, ["description"] = "Hey Champ, You were out when I stopped by. You're the talk of the arena, friend! I mean, the Ring of Trials? Stonemaul? You're killing it out there! I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? I'll meet you at my stash so we can talk a bit in private before your big debut. <A map is included with a dollar sign scrawled on an abandoned ogre tower.>", ["objectivesText"] = "Speak to Gurgthock at Gurgthock 's Stash in Nagrand.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84637, ["x"] = 0.63, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 114, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[36284] = { ["id"] = 36284, ["name"] = "A Fascinating Fungus", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36284 }, ["series"] = { 35146, 36275, 36285 }, ["description"] = "The Zangar Shore is home to many peculiar strains of fungi, some of which are similar to those of our native Azeroth. However, one strain in particular is most fascinating! I call it \"Zangarium Draenormycota,\" due to its prevelance in Draenor's fungal ecosystem. This unique strain of fungus is highly adaptable and can be found on many of the living organisms throughout Zangar Shore. Why does it exist? What properties does it hold? To answer these questions, I will need additional spore samples.", ["objectivesText"] = "Collect 12 Fungal Spores . Progress: Have you collected the spore samples for my research?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 115276 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84861, ["x"] = 0.866, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84861, ["x"] = 0.866, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.866, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[36285] = { ["id"] = 36285, ["name"] = "Dirgemire", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36285 }, ["series"] = { 35146, 36275, 36284 }, ["description"] = "In order to fully understand the nature and properties of the Zangarium Draenormycota, I need to examine the strain within a complex fungal structure. The fungal brain of a spore giant would do nicely. Not just any spore giant will serve though, it needs to be big... mean... primordial... the perfect specimen! In a cavern deep below the surface is an ancient spore giant the locals fearfully refer to as Dirgemire. Slay the monster, but be sure to carefully preserve the fungal brain for our research!", ["objectivesText"] = "Retrieve the Fungal Brain from Dirgemire. Progress: Without a fungal brain to examine, the mysteries of the Zangar ecosystem will remain unsolved!", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 115277 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84861, ["x"] = 0.866, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84861, ["x"] = 0.866, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.866, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[36286] = { ["id"] = 36286, ["name"] = "Transponder 047-B", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36286 }, ["series"] = { 36287 }, ["description"] = "The back of the transponder is etched in scribbled writing. <URGENT: If found, please return to Goggles near Eledor. It is of the utmost importance!>", ["objectivesText"] = "Return the transponder to Goggles . Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 114943, 115278 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84825, ["x"] = 0.608, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 115278 } },
[36289] = { ["id"] = 36289, ["name"] = "Out of the Shadows", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36219, 36220, 36221, 36222, 36280, 36281, 36282, 36289 }, ["description"] = "Congratulations again, Blood Champion. You be fightin' like nobody I ever seen. While you were in da ring, one ayour bruddas came by and asked for you ta return ta your base. He called himself Bodrick Grey .", ["objectivesText"] = "Speak to Bodrick Grey at your Garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84784, ["x"] = 0.568, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 103, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
