[36301] = { ["id"] = 36301, ["name"] = "Trega's Tailoring Kit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36301 }, ["series"] = { 36417, 36419 }, ["description"] = "The bag is filled with patterns and unfamiliar tailoring tools. You find the name \" Trega \" embroidered on the inside of the bag. You seem to recall seeing her in Wor'gol. With any luck, she's still there.", ["objectivesText"] = "Find Trega in Wor'gol. Progress: That's my sewing kit! I never thought I would see this again.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 114973 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84689, ["x"] = 0.204, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.204, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["startItems"] = { 114973 } },
[36307] = { ["id"] = 36307, ["name"] = "Investigating the Invasion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 4, ["mapID"] = 17, ["storyline"] = { 36307 }, ["description"] = "I'm going to lead a small squad behind enemy lines. Meet me by Dreadmaul, <class>. From there we can decide our next course of action.", ["objectivesText"] = "Meet Maraad behind enemy lines.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 82270, ["x"] = 0.666, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 84929, ["x"] = 0.52, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 4 } }, ["questType"] = "standard" },
[36308] = { ["id"] = 36308, ["name"] = "Enchanted Highmaul Bracer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36308 }, ["series"] = { 36310, 36313, 36315 }, ["description"] = "A powerful enchantment emanates from these ancient Highmaul bracers. Maybe Eileese Shadowsong , your garrison enchanting quartermaster, can tell you more about the bracer.", ["objectivesText"] = "Take the bracer to Eileese Shadowsong in your Garrison. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 115281 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["startItems"] = { 115281 } },
[36309] = { ["id"] = 36309, ["name"] = "The Strength of Iron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36309 }, ["series"] = { 36311 }, ["description"] = "A stitched patch along the side of the satchel clearly identifies its owner. You remember hearing stories of a great blacksmith just north of Embaari.", ["objectivesText"] = "Deliver the satchel to Haephest . Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 115343 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80827, ["x"] = 0.452, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 115343 } },
[36311] = { ["id"] = 36311, ["name"] = "Father and Son", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36311 }, ["series"] = { 36309 }, ["description"] = "Please find my boy! Before the looters came we were on the hill just northeast of here. There weren't many of them, but I'm a blacksmith, not a fighter! Have I let my only son down?", ["objectivesText"] = "Find Haephest 's son.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111813, 115343, 115356, 119037 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80827, ["x"] = 0.452, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80827, ["x"] = 0.452, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36313] = { ["id"] = 36313, ["name"] = "Failed Apprentice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36313 }, ["series"] = { 36308, 36310, 36315 }, ["description"] = "Oru'kai was the first ogre mage to master the art of enchanting on Draenor. Upon his death, his items were scattered across Draenor. I have tracked his staff to the shore you see before us. As you can see, the staff's enchantment is making it difficult to retrieve. A would-be apprentice, Deema , took one of Oru'kai's rings in to break the enchantment, but she failed and became trapped as well. Find and free Deema , take the ring, complete her task, and I will consider a reward.", ["objectivesText"] = "Find and release Deema from her time prison.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84966, ["x"] = 0.373, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84963, ["x"] = 0.356, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36314] = { ["id"] = 36314, ["name"] = "The Intricate Pendant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36314 }, ["series"] = { 36352, 36378, 36380 }, ["description"] = "The crimson gem used in this pendant is unlike any you've seen before, and the filigree wrapped around it is masterfully crafted. There's likely to be much you can learn from the person who made this. Perhaps someone at your garrison will recognize the work.", ["objectivesText"] = "Ask around your garrison to see if anyone recognizes the pendant. Progress: Why hello <name>, what do we have here?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 115287, 115503 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 115287 } },
[36315] = { ["id"] = 36315, ["name"] = "Oru'kai's Staff", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36315 }, ["series"] = { 36308, 36310, 36313 }, ["description"] = "If I had known being an enchanter was this dangerous, I would have stayed in Shattrath. Here, take this ring. The arakkoa told me to use the ring on the staff to nullify the enchantment. Bring the scepter back to him and maybe he will teach you what he promised to teach me.", ["objectivesText"] = "Retrieve Oru'kai's staff and return it to Delath. Progress: The staff! Give it to me!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111817, 111922, 115290, 115372 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84963, ["x"] = 0.356, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84966, ["x"] = 0.373, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36316] = { ["id"] = 36316, ["name"] = "Victory is Within Reach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6988, ["mapID"] = 542, ["storyline"] = { 36316 }, ["series"] = { 35704, 36085 }, ["description"] = "We have dealt a crippling blow to the Adherents, but our fight is not yet finished. Gather your allies and prepare for the final siege on Skyreach! \"Shadows gather when the raven swallows the day. Burning sky is extinguished as black wings fold gently about the heavens. Rest, my children, rest. For even the sun must sleep.\" This was Rukhmar's lullaby, sung by her to the first arakkoa. My, how we've lost our way.", ["objectivesText"] = "Slay Ranjit , Araknath , Rukhran and High Sage Viryx in the Skyreach dungeon. Progress: Let us finish what we have started.", ["rewardGold"] = 679200, ["rewardXP"] = 8230, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6988 } }, ["questType"] = "dungeon" },
[36338] = { ["id"] = 36338, ["name"] = "Assault on Shattrath Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["storyline"] = { 36338 }, ["objectivesText"] = "Shadow Council Assaulted Defeat Minus Enemies Defeat Normal Enemies Defeat Lieutenant Enemies Defeat Miniboss Enemies Caches Siege Cannons Soul Crystals Fel Fires Arkonite Crystals Sha'tari Belongings Orc Bodies Captured Guards", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119386, 119402, 119403, 119413 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Shadow Council Assaulted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Defeat Minus Enemies", ["amount"] = 500, ["type"] = 0, ["objectID"] = 85197, ["orderIndex"] = 1 }, { ["text"] = "Defeat Normal Enemies", ["amount"] = 100, ["type"] = 0, ["objectID"] = 85000, ["orderIndex"] = 2 }, { ["text"] = "Defeat Lieutenant Enemies", ["amount"] = 34, ["type"] = 0, ["objectID"] = 85195, ["orderIndex"] = 3 }, { ["text"] = "Defeat Miniboss Enemies", ["amount"] = 4, ["type"] = 0, ["objectID"] = 85200, ["orderIndex"] = 4 }, { ["text"] = "Caches", ["amount"] = 20, ["type"] = 2, ["objectID"] = 234433, ["orderIndex"] = 5 }, { ["text"] = "Siege Cannons", ["amount"] = 45, ["type"] = 0, ["objectID"] = 84754, ["orderIndex"] = 6 }, { ["text"] = "Soul Crystals", ["amount"] = 50, ["type"] = 0, ["objectID"] = 83856, ["orderIndex"] = 7 }, { ["text"] = "Fel Fires", ["amount"] = 50, ["type"] = 0, ["objectID"] = 84279, ["orderIndex"] = 8 }, { ["text"] = "Arkonite Crystals", ["amount"] = 10, ["type"] = 0, ["objectID"] = 85370, ["orderIndex"] = 9 }, { ["text"] = "Sha'tari Belongings", ["amount"] = 34, ["type"] = 0, ["objectID"] = 84997, ["orderIndex"] = 10 }, { ["text"] = "Orc Bodies", ["amount"] = 100, ["type"] = 0, ["objectID"] = 85393, ["orderIndex"] = 11 }, { ["text"] = "Captured Guards", ["amount"] = 34, ["type"] = 0, ["objectID"] = 85103, ["orderIndex"] = 12 } } },
[36341] = { ["id"] = 36341, ["name"] = "Primal Fury", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36341 }, ["series"] = { 36134 }, ["description"] = "It looks like this is it, commander. We must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Bodrick Grey to deploy your troops to the Gates of Tanaan at once. By the time you get to northern Talador, he should be waiting for you... with an entire army. There is no time to delay.", ["objectivesText"] = "Meet Bodrick Grey near the Gates of Tanaan in Talador, then defeat Gorgorek and Warlord Azuka Bladefury .", ["rewardXP"] = 1365, ["rewardItems"] = { 120311, 120312, 120313 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84185, ["x"] = 0.41, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 109, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 109, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36342] = { ["id"] = 36342, ["name"] = "Primal Fury", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36342 }, ["series"] = { 36136 }, ["description"] = "It looks like this is it, commander. We must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Shadow Hunter Rokhan to deploy your troops to the Gates of Tanaan at once. By the time you get to northern Talador, he should be waiting for you... with an entire army. There is no time to delay.", ["objectivesText"] = "Speak to Shadow Hunter Rokhan in northern Talador, then defeat Gorgorek and Warlord Azuka Bladefury .", ["rewardXP"] = 1365, ["rewardItems"] = { 98098, 110560, 119093, 120311, 120312, 120313 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 88530, ["x"] = 0.41, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 120, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 120, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36344] = { ["id"] = 36344, ["name"] = "Feeding An Army", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36344 }, ["description"] = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one. The Improved Iron Trap will let you capture some of the meatiest beasts on Draenor. You will find that a single riverbeast or boar from Gorgrond can feed many warriors. Trap one and bring it back, and we will cook you a savage meal.", ["objectivesText"] = "Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn. Progress: Did you try the trap out yet?", ["rewardGold"] = 339600, ["rewardXP"] = 2615, ["rewardItems"] = { 115009, 119093, 137663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36345] = { ["id"] = 36345, ["name"] = "Breaking into the Trap Game", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36345 }, ["description"] = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here. Although the plains are frozen, there are many clefthooves and wolves in Frostfire. We can gather leather from the clefthooves, or furs from the wolves. Take this iron trap and use it on a wounded adult beast. Bring the trapped creature back to us, and we will begin our work.", ["objectivesText"] = "Use the Iron Trap to capture a Clefthoof or Wolf in Frostfire Ridge and then place a Work Order at your Barn. Progress: Have you tried your hand at trapping yet?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 86607, 111556, 111557, 113991, 114821 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36346] = { ["id"] = 36346, ["name"] = "Bigger Trap, Better Rewards", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36346 }, ["description"] = "Ah, commander, it is good to see you again. With the materials we have gathered here in Draenor, we have been able to construct a trap strong enough to immobilize even the mightiest beast. These enormous creatures can be found on the western side of Nagrand , among the most fertile plains. A word of warning: these beasts are great and powerful. You may want to bring some friends along.", ["objectivesText"] = "Use the Deadly Iron Trap to capture a Ironhide Bull, Direfang Alpha, or Wetland Trampler. Progress: Did you manage to break one of the great beasts?", ["rewardGold"] = 339600, ["rewardXP"] = 5990, ["rewardItems"] = { 86607, 97919, 115010, 118472, 137663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
