[36352] = { ["id"] = 36352, ["name"] = "Locating the Lapidarist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 36352 }, ["series"] = { 36314, 36378, 36380 }, ["description"] = "Are you sure I can't take this off your hands? I'll give you a fair price! Alright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol. Rumor has it there is a master craftsman there who's skilled in manipulating precious metals and stones. Might be your guy.", ["objectivesText"] = "Search for the owner of the pendant in Wor'gol.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 115489 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85106, ["x"] = 0.2, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.2, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
