[36481] = { ["id"] = 36481, ["name"] = "Firebird's Challenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 36481 }, ["description"] = "You're ready to fly high and give the Firebird's challenge a shot? That's great! Simply collect 15 rings to win! Speak to me when you're ready for takeoff!", ["objectivesText"] = "Collect 15 rings while flying. Progress: How was the flight?", ["rewardItems"] = { 93724, 116115 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[36482] = { ["id"] = 36482, ["name"] = "A Green Ogron?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Kaz always told me green ogron are bad. The botani here have a green ogron and it is mean. It was strong enough to take out my dad's entire hunting party. Are you strong enough to kill it?", ["objectivesText"] = "Kill the Infested Ogron .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112591, 112592, 112593, 112594 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82254, ["x"] = 0.436, ["y"] = 0.84 }, { ["mapID"] = 543, ["npcID"] = 82274, ["x"] = 0.427538, ["y"] = 0.811077 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82274, ["x"] = 0.427538, ["y"] = 0.811077 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 17, ["flags"] = 0 } } },
[36483] = { ["id"] = 36483, ["name"] = "Battle Pet Roundup", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36483 }, ["description"] = "Looks like we've got some visitors in the battle pen today, and they're looking for a fight. Why don't you show 'em how a master of pet battles handles <himself/herself>?", ["objectivesText"] = "Defeat the pets in the battle area. Progress: Those pets looked tough. How'd you do?", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 54847, 116378, 116415, 163036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36488] = { ["id"] = 36488, ["name"] = "Thieving Dwarves", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Cutter is on the trail of the artifact the dwarves stole. He has the nose of a wolf when it comes to hunting in the jungle. Follow the canyons south until you find him. It would seem the wolf queen and I are going to do more damage here before we leave. We will follow as quickly as we can.", ["objectivesText"] = "Find Cutter at Bastion Rise.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82228, ["x"] = 0.42, ["y"] = 0.858 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85601, ["x"] = 0.464, ["y"] = 0.935 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.858 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 18, ["flags"] = 0 } } },
[36489] = { ["id"] = 36489, ["name"] = "Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 36489 }, ["description"] = "The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!", ["objectivesText"] = "Destroy Iron Horde weapons cache and take out as many of them as you can.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 119225, 119226, 119227, 119228, 119229, 119230 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Blackrock Foundry Assaulted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Iron Horde", ["amount"] = 100, ["type"] = 0, ["objectID"] = 85228, ["orderIndex"] = 1 }, { ["text"] = "Kill Iron Horde", ["amount"] = 20, ["type"] = 0, ["objectID"] = 85229, ["orderIndex"] = 2 }, { ["text"] = "Kill Iron Horde", ["amount"] = 5, ["type"] = 0, ["objectID"] = 85230, ["orderIndex"] = 3 }, { ["text"] = "Kill Iron Horde", ["amount"] = 200, ["type"] = 0, ["objectID"] = 86298, ["orderIndex"] = 4 }, { ["text"] = "Destroy Training Manuals", ["amount"] = 100, ["type"] = 2, ["objectID"] = 236277, ["orderIndex"] = 5 }, { ["text"] = "Free Laughing Skull Prisoners", ["amount"] = 50, ["type"] = 2, ["objectID"] = 236444, ["orderIndex"] = 6 } } },
[36494] = { ["id"] = 36494, ["name"] = "News from Talador", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36494 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Rokhan sends word that you are needed at Frostwall. The Iron Horde have landed on the shores of Talador .", ["objectivesText"] = "Speak to Rokhan at your garrison in Frostfire Ridge.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36495] = { ["id"] = 36495, ["name"] = "News from Talador", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36495 }, ["series"] = { 34558, 34676, 35702, 36576, 37183, 49565, 92692 }, ["description"] = "Bodrick Grey sends word from your garrison that they have spotted a fleet of Iron Horde at the shores of Talador . We must not allow them to destroy Shattrath.", ["objectivesText"] = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36498] = { ["id"] = 36498, ["name"] = "Iron Horde Invasion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 1519, ["mapID"] = 17, ["storyline"] = { 36498 }, ["series"] = { 35460 }, ["description"] = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in Blasted Lands . Use the portal at the Wizard's Sanctum in Stormwind to head directly to the front line. This new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped. For the glory and honor of the Alliance!", ["objectivesText"] = "Speak with Vindicator Maraad at the Shattered Beachhead in Blasted Lands .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 82270, ["x"] = 0.666, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
