[36502] = { ["id"] = 36502, ["name"] = "Trophy of Glory: Biolante", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36502 }, ["description"] = "Defeating Biolante has yielded you a trophy worthy of showing off at your outpost. Return this to Maraad to increase your glory!", ["objectivesText"] = "Take the trophy to Maraad at Highpass in Gorgrond . Provided item:", ["rewardGold"] = 842700, ["rewardXP"] = 2615, ["rewardItems"] = { 116159 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["startItems"] = { 116159 } },
