[36589] = { ["id"] = 36589, ["name"] = "Heavy Arms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36589 }, ["series"] = { 36594, 36627 }, ["description"] = "The burned out shell of some sort of weapon of mass destruction. It might be worth asking around your garrison to see if anyone can help get it working again.", ["objectivesText"] = "Look around the garrison for help with the repairs. Progress: Yo, boss. Whatchya got for me?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 116438 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 116438 } },
