[36662] = { ["id"] = 36662, ["name"] = "Scrappin'", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36662 }, ["description"] = "Ever since we built da menagerie, a lot o' \"visitors\" been showin' up. I know da look, and they be lookin' for a fight. <Brudda/Sista>, you show 'em you da real master 'round here.", ["objectivesText"] = "Defeat the pets in the battle area. Progress: Did you show 'em the mojo?", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 45002, 90173, 98112, 98114, 116378, 116415, 163036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
