[36691] = { ["id"] = 36691, ["name"] = "Assault on Socrethar's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36691 }, ["description"] = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrathar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.", ["objectivesText"] = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119360, 119368, 119377, 119382, 119387, 119396, 119431, 251329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36692] = { ["id"] = 36692, ["name"] = "Assault on Darktide Roost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36692 }, ["description"] = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.", ["objectivesText"] = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 115020, 116978, 119093, 119364, 119400, 119411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36693] = { ["id"] = 36693, ["name"] = "Assault on Mok'gol Watchpost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36693 }, ["description"] = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", ["objectivesText"] = "Assault the Warsong force at Mok'gol Watchpost in Nagrand.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119355, 119380 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36694] = { ["id"] = 36694, ["name"] = "Assault on the Broken Precipice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36694 }, ["description"] = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", ["objectivesText"] = "Assault the ogron forces at the Broken Precipice in Nagrand.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 118099, 119370, 119389, 119405 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36695] = { ["id"] = 36695, ["name"] = "Assault on the Everbloom Wilds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36695 }, ["description"] = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Rokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.", ["objectivesText"] = "Assault the Botani forces in the Everbloom Wilds in Gorgrond. Progress: Da assault be goin' well I hope?", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119357, 119361, 119367, 119381, 119391, 119395, 119406, 119412, 119414, 119432 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36696] = { ["id"] = 36696, ["name"] = "Assault on the Iron Siegeworks", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36696 }, ["description"] = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", ["objectivesText"] = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119359, 119366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36697] = { ["id"] = 36697, ["name"] = "Assault on Magnarok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36697 }, ["description"] = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", ["objectivesText"] = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 111534, 111545, 119349, 119376, 119415, 119416, 122403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36698] = { ["id"] = 36698, ["name"] = "Battle in Ashran", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36698 }, ["description"] = "As we do battle all across Draenor, the cowardly Alliance try to seize our territory within Ashran. Our men would be inspired to see you join the battlefield, striking terror into the hearts of the Alliance.", ["objectivesText"] = "Join the battle in Ashran.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 114125, 114843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36699] = { ["id"] = 36699, ["name"] = "Assault on the Heart of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36699 }, ["description"] = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.", ["objectivesText"] = "Assault the Sargerei force in Shattrath City in Talador. Progress: Da assault be goin' well I hope?", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 119170, 119352, 119353, 119375, 119383, 119388, 119393, 119394, 251547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[36700] = { ["id"] = 36700, ["name"] = "Challenge at the Ring of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36700 }, ["description"] = "A challenge has been issued at the Ring of Blood. Bring friends and do battle to prove your right as champion.", ["objectivesText"] = "Do battle at the Ring of Blood.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 25759, 25760, 25761, 25762, 25763, 25764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[36701] = { ["id"] = 36701, ["name"] = "Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36701 }, ["description"] = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.", ["objectivesText"] = "Assault the Blackrock forces at the Pit in Gorgrond. Progress: Da assault be goin' well I hope?", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 119225, 119226, 119227, 119228, 119229, 119230 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[36702] = { ["id"] = 36702, ["name"] = "Meatball", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6298, ["storyline"] = { 36702 }, ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[36705] = { ["id"] = 36705, ["name"] = "The Ring of Blood: Mogor!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36705 }, ["description"] = "You've really done it this time, champ. Mogor has challenged you to uphold his title as lord of the ring! I wish I could give you tips to help you make it out of there in one piece, but I've never seen Mogor fight. Nobody's ever gotten this far! Good luck.", ["objectivesText"] = "Defeat Mogor in the Ring of Blood.", ["rewardItems"] = { 25759 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84783, ["x"] = 0.568, ["y"] = 0.13 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84783, ["x"] = 0.568, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "group" },
[36706] = { ["id"] = 36706, ["name"] = "Ashran Appearance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 36706 }, ["series"] = { 36707, 36708, 36709 }, ["description"] = "Our base on Ashran is almost complete, commander. It would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area. I can arrange a flight if you are interested.", ["objectivesText"] = "Speak with Private Stomphoof at Warspear in Ashran.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36707] = { ["id"] = 36707, ["name"] = "Warspear Welcome", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7333, ["storyline"] = { 36707 }, ["series"] = { 36706, 36708, 36709 }, ["description"] = "Lieutenant Kragil said you might be showing up. I've been ordered to take you to the inn.", ["objectivesText"] = "Speak with Lieutenant Kragil .", ["rewardGold"] = 14665, ["rewardXP"] = 355, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7333 } }, ["questType"] = "standard" },
[36708] = { ["id"] = 36708, ["name"] = "Inspiring Ashran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7333, ["storyline"] = { 36708 }, ["series"] = { 36706, 36707, 36709 }, ["description"] = "I hope you will find our facilities to be up to your high standards. This inn is run by Narnin Dawnglow , in my opinion this is the best place to hearth in Draenor. We have new recruits coming through the portal daily. In fact one of out latest recruits, Zarjhin , just came through the portal today. If you are looking for weapons or armor Beska Redtusk will be happy to help.", ["objectivesText"] = "Speak with Narnin Dawnglow , Beska Redtusk , and Zarjhin . Progress: How did your walk go?", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7333 } }, ["questType"] = "standard" },
[36709] = { ["id"] = 36709, ["name"] = "Burning Beauty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7333, ["storyline"] = { 36709 }, ["series"] = { 36706, 36707, 36708 }, ["description"] = "Before you go, there is someone you should meet. She might set some of your stuff on fire, but I believe she's the best mage this side of Draenor. She belongs on the front lines with you, commander.", ["objectivesText"] = "Speak with Vivianne .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7333 } }, ["questType"] = "standard" },
