[36741] = { ["id"] = 36741, ["name"] = "Vintage Free Action Potion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6941, ["mapID"] = 588, ["storyline"] = { 36741 }, ["description"] = "I hear our heroes in the front line are becoming victim to massive amounts of snares, roots and stuns! Luckily I have just the potion for them. The recipe is a little old, but it'll work. A key ingredient I need can be found here in Ashran , at the beach near that Ogre Tower.", ["objectivesText"] = "Bring Gimlett Ginfizz 10 Ashmaul Pearls . Progress: Have you got the pearls, <name>?", ["rewardGold"] = 339600, ["rewardItems"] = { 116925, 117011 }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 85749, ["x"] = 0.442, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 6941 } }, ["questType"] = "standard" },
