[36790] = { ["id"] = 36790, ["name"] = "The Initiate's Revenge", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["description"] = "I... I'm finished. My spirit will be with the Raven Mother soon. I beg of you, stranger... avenge me! Slay these filthy beasts.", ["objectivesText"] = "Kill 18 Bloodmane Saberon.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 86381, ["x"] = 0.515, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80746, ["x"] = 0.52, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 12, ["flags"] = 0 } } },
[36791] = { ["id"] = 36791, ["name"] = "Phantom Potion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6941, ["mapID"] = 588, ["storyline"] = { 36791 }, ["description"] = "Every turn you take in Ashran you run into danger. But don't fret <name>, I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. I'm just missing one of the ingredients: cave mushrooms. Luckily, a variety grows right here in Ashran .", ["objectivesText"] = "Bring Gimlett Ginfizz 10 Ghost Truffles . Progress: Are those the truffles?", ["rewardGold"] = 339600, ["rewardItems"] = { 114124, 117017 }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 85749, ["x"] = 0.442, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 6941 } }, ["questType"] = "standard" },
