[36800] = { ["id"] = 36800, ["name"] = "Fire Ammonite Lunker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36800 }, ["objectivesText"] = "Progress: Woooo daddy! Now that's a lunker <name>! I don't think I will ever get used to fishing in lava but nothing is really normal about this crazy place.", ["rewardXP"] = 175, ["rewardItems"] = { 87791, 116819, 116825, 116826, 117397, 117401, 117404, 117405 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36801] = { ["id"] = 36801, ["name"] = "One Step Ahead", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36801 }, ["series"] = { 34087, 34088, 34959 }, ["description"] = "Commander, Vindicator Maraad set off with Yrel and Thaelin Darkanvil to track the Iron Horde's movements in the nearby forest. They await your arrival on a small rise to the southwest.", ["objectivesText"] = "Speak to Vindicator Maraad at Redemption Rise.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 86442, ["x"] = 0.696, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36802] = { ["id"] = 36802, ["name"] = "Abyssal Gulper Lunker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36802 }, ["objectivesText"] = "Progress: I'm surprised you made it back in one piece! Abyssal Gulpers are a delicacy to local Arakkoa in Spires of Arak.", ["rewardXP"] = 175, ["rewardItems"] = { 33820, 34832, 44050, 87791, 92747, 116818, 116825, 116826, 117397, 117401, 117404, 117405 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36803] = { ["id"] = 36803, ["name"] = "Blackwater Whiptail Lunker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36803 }, ["objectivesText"] = "Progress: Those Draenei bother you over in Talador? I never fancied them fisherman but word is they are very territorial with local fishing spots. No matter, it looks like you got the prize this time!", ["rewardXP"] = 175, ["rewardItems"] = { 87791, 116817, 116825, 116826, 117397, 117401, 117404, 117405 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
