[36830] = { ["id"] = 36830, ["name"] = "Shadow Council Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36830 }, ["description"] = "The demons are at our heels, Commander. Cow's milk is sour. A crone gave me an evil look this morning. The sky just doesn't seem... right.", ["objectivesText"] = "Repel the Shadow Council invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
