[36848] = { ["id"] = 36848, ["name"] = "Ogre Waygates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36848 }, ["description"] = "Six unique gates exist in Draenor, built by ogre magi in ages past. We've discovered their potency has not diminished over the millennia. If you can collect enough ogre waystones to activate one of these ancient waygates, we can build a portal from your garrison to that location.", ["objectivesText"] = "Collect 25 Ogre Waystones and use them to activate an Ogre Waygate in Draenor. Progress: Did you activate a waygate?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 117491 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36861] = { ["id"] = 36861, ["name"] = "Pinchwhistle Gearworks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 542, ["storyline"] = { 36861 }, ["series"] = { 35077, 35080, 35082, 35619, 35620, 36862 }, ["description"] = "Commander, a goblin courier arrived this morning. He mentioned that he is from a settlement in the Spires of Arak called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster. If we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", ["objectivesText"] = "Speak to Dungar Longdrink to secure a flight to the Pinchwhistle Gearworks.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36862] = { ["id"] = 36862, ["name"] = "Pinchwhistle Gearworks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 542, ["storyline"] = { 36862 }, ["series"] = { 35077, 35080, 35082, 35619, 35620, 36861 }, ["description"] = "Commander, a courier arrived this morning. He said he's from a goblin settlement in Spires of Arak called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster. We're spread thin but if we can earn their trust then we might be able to gain a valuable ally. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", ["objectivesText"] = "Speak to Bron Skyhorn the Wingman to secure a flight to the Pinchwhistle Gearworks.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36864] = { ["id"] = 36864, ["name"] = "Three Feet Under", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 36864 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 86597, ["x"] = 0.358, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 86597, ["x"] = 0.358, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[36870] = { ["id"] = 36870, ["name"] = "Luring Nat", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36870 }, ["series"] = { 36608, 36609, 36612 }, ["description"] = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here. If we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor. Head out to local waters here in Shadowmoon Valley and see what you can do. All that time you spend honing your skill here in Draenor should pay off now.", ["objectivesText"] = "Catch an Arcane Trout in Shadowmoon Valley and bring it back to Segumi . Progress: Find anything worth keeping?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 6367, 19970, 19971, 50287, 88710, 116754, 118041, 118380, 118391 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36874] = { ["id"] = 36874, ["name"] = "Warlord of Draenor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36874 }, ["description"] = "Durotan... < Raza'kul spits.> He cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies. Enemies that have taken our homes and driven us from our ancestral lands. There is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood. Join me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief! Return here when your bloodthirst is sated.", ["objectivesText"] = "Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror's Tribute. Progress: I will not rest until this bloodied ground overflows with the bones of our enemies.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36876] = { ["id"] = 36876, ["name"] = "Warlord of Draenor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36876 }, ["description"] = "The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will. I wish to join your Alliance and rid this world of Horde. ALL HORDE - \"Iron\" or otherwise. This Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror's tribute worthy of your unrelenting bloodthirst. Kill. Them. All.", ["objectivesText"] = "Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror's Tribute. Progress: I will not rest until this bloodied ground overflows with the bones of our enemies.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 115206, 118043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
[36881] = { ["id"] = 36881, ["name"] = "Warlords of Draenor: The Dark Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 5840, ["mapID"] = 17, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34393, 34398, 34420, 35933 }, ["description"] = "<name>, is it? I'm glad you're here. We can use every able-bodied <class> that we can get. I am assembling a coalition of Azeroth's strongest to step through this Dark Portal and stop the Iron Horde invasion. This may be the only way to save Azeroth. Will you join us?", ["objectivesText"] = "Speak with Archmage Khadgar at the foot of the Dark Portal in Blasted Lands.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 78423, ["x"] = 0.548, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36882] = { ["id"] = 36882, ["name"] = "The Great Angler Returns", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 36882 }, ["description"] = "What's this species, an arcane trout you say? I have never even heard of a fish like this, much less seen one in person! I have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up. Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", ["objectivesText"] = "Return to Segumi with Nat's journal page as proof that you found him. Progress: You found Nat? The real Nat Pagle ?!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 34832, 116747, 118391 }, ["starts"] = { { ["mapID"] = 418, ["npcID"] = 63721, ["x"] = 0.684, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 418, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 418 }, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[36884] = { ["id"] = 36884, ["name"] = "Worgen Snout", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 36884 }, ["objectivesText"] = "Progress: GOT SOMETHING FOR ME, CALLMEDEAD?", ["rewardGold"] = 339600, ["rewardItems"] = { 112119, 170074 }, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 83869, ["x"] = 0.458, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 83869, ["x"] = 0.458, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[36889] = { ["id"] = 36889, ["name"] = "Nemesis: Hunter - Hunted", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36889 }, ["description"] = "Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion. Around me stand effigies of our most hated adversaries. You will be their downfall, <name>. You will become nemesis and they will run in fear at the sight of you. Now select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.", ["objectivesText"] = "Burn a Nemesis Effigy at the Gladiator's Sanctum then speak to Raza'kul .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
