[36965] = { ["id"] = 36965, ["name"] = "Nemesis: Becoming Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36965 }, ["description"] = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a troll in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", ["objectivesText"] = "Kill a Troll Player in Player versus Player combat while in Draenor and retrieve their Troll Heart . Progress: Have you recovered the heart of a worthy foe?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118360 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
