[37058] = { ["id"] = 37058, ["name"] = "Clefthoof Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37058 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37059] = { ["id"] = 37059, ["name"] = "Clefthoof Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37059 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116656, 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37060] = { ["id"] = 37060, ["name"] = "Lost in Transition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37060 }, ["description"] = "<Sir/Ma'am>, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for. Unfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters. If you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", ["objectivesText"] = "Gather 5 Crate of Surplus Materials . Progress: Hello commander, what can I do for you?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37062] = { ["id"] = 37062, ["name"] = "Tricks of the Trade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37062 }, ["description"] = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean. Sometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time. Luckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", ["objectivesText"] = "Find and rouse the missing Trader. Progress: Trading isn't always the most exciting enterprise. But I do enjoy it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118418 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37063] = { ["id"] = 37063, ["name"] = "Elekk Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37063 }, ["description"] = "This beast is surely at home in Nagrand , and after the years of domestication by Draenei it will be quite easy to train. We shall face it against the ogres of the region that you are familiar with. The Gorian Beast-Lasher , the one that smells of blood and fear, see how this elekk reacts to him.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37064] = { ["id"] = 37064, ["name"] = "Elekk Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37064 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37065] = { ["id"] = 37065, ["name"] = "Elekk Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37065 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your elekk. See if you can keep it focused and defeat the moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37066] = { ["id"] = 37066, ["name"] = "Elekk Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37066 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall , and we will see how your mount fares.", ["objectivesText"] = "Defeat Thundercall while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37067] = { ["id"] = 37067, ["name"] = "Elekk Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37067 }, ["description"] = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37068] = { ["id"] = 37068, ["name"] = "Elekk Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37068 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37069] = { ["id"] = 37069, ["name"] = "Elekk Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37069 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116662, 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37071] = { ["id"] = 37071, ["name"] = "Riverbeast Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37071 }, ["description"] = "This bulbous beast has spent a number of years in the wilds of Talador . We will begin the training there. It is already docile, as well, so I do not think it will take as long to train as the others. As you know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", ["objectivesText"] = "Defeat Gezz'ran while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37072] = { ["id"] = 37072, ["name"] = "Riverbeast Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37072 }, ["description"] = "In the far south, in the Spires of Arak , the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited. Taking on a strange creature, like the fungal giant Bulbapore , will grant you a chance to expose your mount to unfamiliar predators.", ["objectivesText"] = "Defeat Bulbapore while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37073] = { ["id"] = 37073, ["name"] = "Riverbeast Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37073 }, ["description"] = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your beast reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37074] = { ["id"] = 37074, ["name"] = "Riverbeast Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37074 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37075] = { ["id"] = 37075, ["name"] = "Riverbeast Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37075 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your riverbeast. See if you can keep it focused and defeat the moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
