[37077] = { ["id"] = 37077, ["name"] = "Riverbeast Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37077 }, ["description"] = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37078] = { ["id"] = 37078, ["name"] = "Riverbeast Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37078 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37079] = { ["id"] = 37079, ["name"] = "Riverbeast Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37079 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116676, 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37082] = { ["id"] = 37082, ["name"] = "Call of the Gladiator", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 37082 }, ["series"] = { 37083 }, ["description"] = "Your merciless rampage has not gone unnoticed, gladiator. So many of your enemies have fallen before your might. It is because of your unrelenting savagery that Imperator Mar'gok himself has requested your presence at the grand Highmaul Coliseum. It is at Highmaul that a battle of epic proportions awaits. Should you heed the call of the gladiator, present this sigil to my brother, Kharg . He is the arena master residing outside of the Coliseum in Nagrand .", ["objectivesText"] = "Take the Sigil of Highmaul to Kharg outside the Highmaul Coliseum in Nagrand . Provided item:", ["rewardXP"] = 1365, ["rewardItems"] = { 118909 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87311, ["x"] = 0.33, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
[37083] = { ["id"] = 37083, ["name"] = "Fight, Kill, Salute!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37083 }, ["series"] = { 37082 }, ["description"] = "The greatest gladiators on Draenor have fought for glory and honor inside the Coliseum. Will you become a legend like Kargath Bladefist or will you be nothing more than bone dust beneath the boots of a more savage gladiator? There is only one way to find out. You must enter the competition and fight! The price of victory is 100 lives! I will admit you without cost once per day, but if you fail and wish to fight again you must pay the price of admission in blood and bone!", ["objectivesText"] = "Kill 100 Gladiators at the Coliseum in Highmaul. You may access the Coliseum by talking to Kharg at Highmaul or Boneslag at your Gladiator's Sanctum.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 18660, 71153, 117398, 118043, 118191, 118904, 119215, 119217, 119218, 119219, 120142 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87311, ["x"] = 0.33, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87311, ["x"] = 0.33, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "pvp" },
[37086] = { ["id"] = 37086, ["name"] = "Salvaging the Situation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37086 }, ["description"] = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful. I have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", ["objectivesText"] = "Use the Small Sack of Salavaged Goods near the incinerator at your Salvage Yard. Progress: Have you burned through that bag of salvage yet?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 118471, 118473, 139593 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37087] = { ["id"] = 37087, ["name"] = "Lost in Transition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37087 }, ["description"] = "<Sir/Ma'am>, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for. Unfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters. If you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", ["objectivesText"] = "Gather 5 Crate of Surplus Materials . Progress: Hello commander, what can I do for you?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37088] = { ["id"] = 37088, ["name"] = "Tricks of the Trade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37088 }, ["description"] = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean. Sometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time. Luckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", ["objectivesText"] = "Find and rouse the missing Trader.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118418 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37091] = { ["id"] = 37091, ["name"] = "Unconventional Inventions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37091 }, ["description"] = "The workshop is bustling with the whir of minds and motors. We're coming up with new inventions all the time. Try out today's glorious invention on the workbench behind me.", ["objectivesText"] = "Acquire an invention from the workbench at the Gnomish Gearworks.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37093] = { ["id"] = 37093, ["name"] = "Talbuk Training: Great-Tusk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37093 }, ["description"] = "The talbuk is ready for more training, and for this, we will return to its home in Shadowmoon Valley . One of the great beasts of this land, Great-Tusk , has taken the valley for his own. Pit your beast against him in combat, and if you should survive, it will have greater confidence in its own abilities.", ["objectivesText"] = "Defeat Great-Tusk while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37094] = { ["id"] = 37094, ["name"] = "Talbuk Training: Rakkiri", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37094 }, ["description"] = "We shall start training the talbuk here, on the icy plains of Frostfire Ridge . We must train it rigorously, or else it may become afraid at the sight of combat, and run. Find the great blood-sucker, Rakkiri , out on the frozen plains, and bring him down astride your talbuk. That will give it a taste for combat.", ["objectivesText"] = "Defeat Rakkiri while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37095] = { ["id"] = 37095, ["name"] = "Talbuk Training: Riplash", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37095 }, ["description"] = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge. Take your beast to the nest of the great Riplash , and see if you cannot emerge victorious.", ["objectivesText"] = "Defeat Riplash while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37096] = { ["id"] = 37096, ["name"] = "Talbuk Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37096 }, ["description"] = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning is the stalker. Stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador .", ["objectivesText"] = "Defeat Gezz'ran while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37097] = { ["id"] = 37097, ["name"] = "Talbuk Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37097 }, ["description"] = "In the far south, in the Spires of Arak , the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited. Taking on a strange creature, like the fungal giant Bulbapore , will grant you a chance to expose your mount to unfamiliar predators.", ["objectivesText"] = "Defeat Bulbapore while riding your Talbuk-In-Training.", ["rewardGold"] = 117300, ["rewardXP"] = 5145, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
