[37101] = { ["id"] = 37101, ["name"] = "Talbuk Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37101 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall , and we will see how your mount fares.", ["objectivesText"] = "Defeat Thundercall while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37102] = { ["id"] = 37102, ["name"] = "Talbuk Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37102 }, ["description"] = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37103] = { ["id"] = 37103, ["name"] = "Talbuk Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37103 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37104] = { ["id"] = 37104, ["name"] = "Talbuk Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37104 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", ["objectivesText"] = "Defeat Maimclaw while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 112003, 116774, 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37105] = { ["id"] = 37105, ["name"] = "Wolf Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37105 }, ["description"] = "The wolves of this land are the most savage beasts I have seen, and surely do not fear orc nor ogre. Bring him to bear against once of the ogres that you are familiar with. The Gorian Beast-Lasher , the one that smells of blood and fear, see how the wolf reacts to him.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37106] = { ["id"] = 37106, ["name"] = "Wolf Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37106 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37107] = { ["id"] = 37107, ["name"] = "Wolf Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37107 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your wolf. See if you can keep it focused and defeat the moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Snarler-In-Training.", ["rewardGold"] = 117300, ["rewardXP"] = 1365, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37108] = { ["id"] = 37108, ["name"] = "Wolf Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37108 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall , and we will see how your mount fares.", ["objectivesText"] = "Defeat Thundercall while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37109] = { ["id"] = 37109, ["name"] = "Wolf Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37109 }, ["description"] = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37110] = { ["id"] = 37110, ["name"] = "Wolf Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37110 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37111] = { ["id"] = 37111, ["name"] = "Wolf Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37111 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 112003, 116784, 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37112] = { ["id"] = 37112, ["name"] = "Rest and Relaxation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 11, 35, 37, 40, 45, 46, 47, 52, 59, 60, 62, 71, 76, 83, 84, 85, 86, 87, 88, 106, 107, 111, 112, 114, 123, 147, 176, 5545, 26152, 37112 }, ["description"] = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn! My best friend, Innkeeper Farley , runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink. To find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", ["objectivesText"] = "Speak with Innkeeper Farley at the Lion's Pride Inn.", ["rewardXP"] = 25, ["rewardItems"] = { 159, 4656, 57395, 57396, 57397, 131715, 132094 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 6774, ["x"] = 0.454667, ["y"] = 0.480667 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 295, ["x"] = 0.438, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.480667 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 566, ["name"] = "Elwynn Forest", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37113] = { ["id"] = 37113, ["name"] = "Thisalee Crow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 37113 }, ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37119] = { ["id"] = 37119, ["name"] = "The Headhunter's Harvest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37119 }, ["description"] = "The inn provides a perfect place for adventurers to take a rest between their travels. It's also a great place to talk them into joining our cause over a few rounds of drinks. Go through my selection and let's see if we can obtain a new recruit. I'll give you a little something as a finder's fee for your efforts.", ["objectivesText"] = "Recruit a follower from Lysa Serion in the Lunarfall Inn. Progress: Find a recruit that you like?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 70165 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37121] = { ["id"] = 37121, ["name"] = "The Black Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37121 }, ["description"] = "Behind me, as ye can probably see, is a giant black claw. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", ["objectivesText"] = "Ask Fanny Firebeard about the Black Claw of Sethe.", ["rewardGold"] = 127350, ["rewardXP"] = 1060, ["rewardItems"] = { 116668, 118469 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37122] = { ["id"] = 37122, ["name"] = "Teeth of a Predator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37122 }, ["description"] = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything!", ["objectivesText"] = "Ask Fanny Firebeard about the Garn-Tooth Necklace.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 118470 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37123] = { ["id"] = 37123, ["name"] = "The Black Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37123 }, ["description"] = "You've probably seen this enormous, black claw in our pile of supplies. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", ["objectivesText"] = "Ask Sage Paluna about the Black Claw of Sethe. Progress: Yes?", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37124] = { ["id"] = 37124, ["name"] = "Teeth of a Predator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37124 }, ["description"] = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything.", ["objectivesText"] = "Ask Sage Paluna about the Garn-Tooth Necklace.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37125] = { ["id"] = 37125, ["name"] = "A Rare Find", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37125 }, ["objectivesText"] = "Progress: Every once in a while an archaeologist experiences a rare find... an artifact that time has delicately preserved through the ages, as if it had simply fallen out of a time machine. Even thinking about the thrill of such a find makes me get all emotional... relics like that are worth a freakin' fortune!", ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87393, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87393, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37126] = { ["id"] = 37126, ["name"] = "An Ogre Without His Sword...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 37126 }, ["description"] = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\" I want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse. It would mean a great deal to me. An ogre without his sword isn't an ogre at all.", ["objectivesText"] = "Retrieve Tormmok's Favorite Sword from Vizier Dar'gud at Broken Precipice in Nagrand. Progress: I want my sword more than I can tell you, commander.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37127] = { ["id"] = 37127, ["name"] = "The Light of Exodus", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["storyline"] = { 37127 }, ["description"] = "My grandfather always told me stories of a powerful crystal made of the Light that would grant power to those who intended to use it for good. He called it the Light of Exodus . I never believed him... until now. Your scouts have found a crystal that sounds just like it. It has been taken by a terrible demon and is being corrupted at the Beacon of Sha'tar in Shattrath. We have to hurry!", ["objectivesText"] = "Retrieve the Light of Exodus from Ambassador Hellmaw at Beacon of Sha'tar in Shattrath City in Talador. Progress: If the Light of Exodus is half as powerful as my grandfather told me, we cannot let it fall into the Legion's hands.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109076, 115506, 115530, 118546, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37128] = { ["id"] = 37128, ["name"] = "Settling Grievances", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["storyline"] = { 37128 }, ["description"] = "Our scouts have found a powerful draenei crystal being corrupted by Ambassador Hellmaw at the Beacon of Sha'tar in Shattrath. The draenei call it the Light of Exodus . Commander, I'd like to accompany you on this mission. Hellmaw slew my brother in Outland... this is personal.", ["objectivesText"] = "Retrieve the Light of Exodus from Ambassador Hellmaw at Beacon of Sha'tar in Shattrath City in Talador. Progress: We cannot allow the Legion to gain any advantage.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118546 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37129] = { ["id"] = 37129, ["name"] = "Unwelcome Memories", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 37129 }, ["description"] = "The botani in the Everbloom Wilds are doin' some sorta foul magic to create these plant... well... zombies, basically. I've seen what happens with armies o' mindless slaves. The Lich King... <Delvar's eyes close.> No matter. We cannae let this escalate any further. I heard o' a particularly nasty one they've just made... let's kill it and see what makes it tick.", ["objectivesText"] = "Retrieve Infested Orc Remains from Acanthus at Everbloom Wilds in Gorgrond. Progress: No zombies, plant o' otherwise, are goin' ta walk this world if ol' Delvar has anythin' to say about it.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[37131] = { ["id"] = 37131, ["name"] = "The Dark Lady's Concern", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 37131 }, ["description"] = "The botani in the Everbloom Wilds kill anything foolish enough to wander too close to their blooms and are raising their corpses as mindless soldiers. This is all too reminiscent of the Scourge... and the Dark Lady has taken notice. She has a special mission for us, commander. There is a particularly large infested creature that was recently raised. We are to destroy it and retrieve its remains.", ["objectivesText"] = "Retrieve Infested Orc Remains from Acanthus at Everbloom Wilds in Gorgrond. Progress: I assure you, commander, the Dark Lady has the Horde's best interests at heart. We must stop these botani immediately.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[37137] = { ["id"] = 37137, ["name"] = "Scrying Hard or Hardly Scrying", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37137 }, ["description"] = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs. They have begun to master their craft... they call to the shadows beyond this realm... I desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", ["objectivesText"] = "Retrieve Urna's Fathomstaff from Urna Darkfathom at Shadowmoon Enclave in Shadowmoon Valley. Progress: Taking out our enemies and gaining great power in one motion... my people have a saying for this: Killing two orcs with one stone.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118570 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37140] = { ["id"] = 37140, ["name"] = "Leorajh's Prayer Beads", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37140 }, ["description"] = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements. One day bird-men attacked and took prayer beads. Took them to Skettis. Master, you help Leorajh get prayer beads back?", ["objectivesText"] = "Retrieve Leorajh's Prayer Beads from Kirox the Wind Dancer in Skettis. Progress: Elements don't speak to Leorajh like they used to.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118571 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37141] = { ["id"] = 37141, ["name"] = "Talonpriest Ishaal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37141 }, ["rewardGold"] = 421350, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83959, ["x"] = 0.465, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83959, ["x"] = 0.465, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37142] = { ["id"] = 37142, ["name"] = "Ogre Ancestry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37142 }, ["description"] = "Lunk no like fight, want to learn. You help Lunk learn? Find Lunk ancestors. Lunk have many question. Where Lunk come from? Why Lunk Lunk ? Lunk stay here. Small ogres mean, big ogres meaner.", ["objectivesText"] = "Collect an Ogre Family Tree from the Bloodmaul Slag Mines . Progress: How can Lunk Lunk if Lunk not know what Lunk is?", ["rewardGold"] = 679200, ["rewardXP"] = 2830, ["rewardItems"] = { 118646, 119036, 119037, 119040, 119041, 119042, 119043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37144] = { ["id"] = 37144, ["name"] = "Talon Guard Kurekk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37144 }, ["rewardGold"] = 421350, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 }, { ["mapID"] = 542, ["npcID"] = 86475, ["x"] = 0.657333, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37145] = { ["id"] = 37145, ["name"] = "Budd's Gambit", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37145 }, ["description"] = "Listen, I don't know how I got here, but I have it on good authority that there is an entire island made of shiny things and it's just off of the coast a ways. All we have to do is hop in the water and swim out there, then we can load up our pockets and swim back! I'm just going to rest up and do some stretching before heading out. Don't try and stop me!", ["objectivesText"] = "Collect a Very Shiny Thing from the Iron Docks . Progress: What?", ["rewardGold"] = 679200, ["rewardXP"] = 4180, ["rewardItems"] = { 32572, 109932, 118111, 118647, 119036, 119037, 119040, 119041, 119042, 119043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37146] = { ["id"] = 37146, ["name"] = "Go Fetch", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37146 }, ["description"] = "Now THIS is a savage land worthy of my level of heroism! Oh, hello, I did not see you standing there, staring at me. Perhaps you have noticed that every piece of my armor is an ancient relic, forgotten by time. As you have properly surmised, an adventurer of my stature does not have time to complete the menial requests I am given daily. I must remain here, yelling aloud to the trade district so that others may witness my heroicness and be inspired. Today I require a Nightmare Bell , do find one.", ["objectivesText"] = "Collect a Nightmare Bell from Auchindoun . Progress: What do you want?", ["rewardGold"] = 1239200, ["rewardXP"] = 5530, ["rewardItems"] = { 109847, 110560, 118648, 119036, 119037, 119040, 119041, 119042, 119043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37147] = { ["id"] = 37147, ["name"] = "Sky Dancers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37147 }, ["description"] = "Greetings, <name>, and I thank you for your hospitality. The Shado-pan have sent several warriors to aid against the Iron Horde, however we can. We are few, though, and they are many. The arakkoa in the south are both beautiful and deadly. They appear lighter than air, their attacks a deadly dance that flits from opponent to opponent. The winds are on their side, as the four winds lighten the steps of my own allies. Bring me a sample of their winds, if you are able. It will surely aid us.", ["objectivesText"] = "Collect a Bottled Windstorm from Skyreach . Progress: Did you find the fifth wind?", ["rewardGold"] = 679200, ["rewardXP"] = 8230, ["rewardItems"] = { 84613, 118649, 119036, 119037, 119040, 119041, 119042, 119043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37148] = { ["id"] = 37148, ["name"] = "Oralius' Adventure", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37148 }, ["description"] = "Me n' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an' plenty of ogres to kill! < Oralius rubs his belly.> We did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over. Ol' Winky, he couldn't take the guilt. Went on back by himself he did, to stop them! Or... to JOIN them! Winky, ye two-timing son of an orc. Ye've got to stop him!", ["objectivesText"] = "Collect a Spire Flamefly in Upper Blackrock Spire . Progress: Did ye stop him?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 109065, 116432, 118650, 118922, 119036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37149] = { ["id"] = 37149, ["name"] = "The Void-Gate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37149 }, ["description"] = "My 'master' is an idiot, but you look like you've got some smarts in that oddly-shaped head. Listen up, the Twisting Nether is a chaotic abyss, and things work differently there. I've felt some disturbances, and they don't bode well for any of us. Yes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don't try to wrap your head around how that works, you'll only hurt yourself. It's simple: bring me a Void-Gate Key , and maybe I can stop the bad things.", ["objectivesText"] = "Find a Void-Gate Key in the Shadowmoon Burial Grounds . Progress: You do know that any time you waste talking to me brings us closer to doom, right?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 109065, 116432, 118651, 118936 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37150] = { ["id"] = 37150, ["name"] = "For the Birds", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37150 }, ["description"] = "Hi! Have you ever held a peachick hatchling? <Without warning, Mylune grabs both of your hands and then stuffs a tiny chirping bird in them.> Isn't it so small and light and downy? Like you're holding a beaky peepy lil' CLOUD! It's so adorable you can't help but hug it and cuddle it and stuff regurgitated food in its teeny-tiny mouth. <name>, the plantfolk in the Everbloom are turning peachicks into monsters before they can grow into beautiful swans. Or whatever they grow into. Please help them!", ["objectivesText"] = "Find a Tiny Peachick Hatchling in The Everbloom . Progress: Have you rescued a peachick? We're all they have, and those awful plant creatures are doing terrible things to them! < Mylune 's voice suddenly drops two octaves and sends a chill up your spine.> Terrible. Things.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 109065, 116432, 118652, 118921, 119036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37151] = { ["id"] = 37151, ["name"] = "Cold Steel", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37151 }, ["description"] = "Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn't understand us, didn't need us. I want that world to love us as much as we love it. But we don't really belong there, not anymore. War is part of us, and we can't go back. To everyone back there, we're expendable. The only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy. <Keeshan stares into his mug of ale.>", ["objectivesText"] = "Find an Iron Autocannon in Grimrail Depot . Progress: Leave me alone.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 109065, 116432, 118653, 118918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37152] = { ["id"] = 37152, ["name"] = "Cro's Revenge", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37152 }, ["description"] = "HA! The fruit vendor was so cunning, but I, Cro Threadstrong , am even MORE cunning. I have come back into the past to defeat the ogre army before that fruit vendor can turn them against me! Bring me the head of a big, strong ogre from the old slag mines, and I will have crushed the fruit vendor before a single apple has even grown! CAN YOU HEAR ME, FRUIT VENDOR? I WILL HAVE MY VICTORY!", ["objectivesText"] = "Collect a Giant Ogre Head from the Bloodmaul Slag Mines . Progress: THE FRUIT VENDOR STANDS NO CHANCE!", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118534, 119083 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37153] = { ["id"] = 37153, ["name"] = "Time-Lost Vikings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37153 }, ["description"] = "Oi, barely made it out of that place! We came through the portal to help, and the next thing you know, we're prisoners in the Bloodmaul Slag Mine. It was brutal! We were shackled for days, and covered in filth. And they took my SHIELD!", ["objectivesText"] = "Collect Olaf's Shield from the Bloodmaul Slag Mines . Progress: < Olaf sobs.>", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 114702, 116432, 118616, 118929 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37154] = { ["id"] = 37154, ["name"] = "The Cure For Death", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37154 }, ["description"] = "Greetings, and my thanks for the warmth of this inn and your hospitality. As you can see, this malady of death continues to plague me. My studies on Azeroth and in Northrend met with little luck, and all of my leads ran dry. I have come to Draenor in the hope of finding something, anything, to go on. My first pilgrimage will be to Auchindoun , a house where souls are put at ease. If you should head there yourself, do let me know if you should happen upon anything of interest.", ["objectivesText"] = "Collect a Soulweave Vessel from Auchindoun . Progress: Did you find anything?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 113082, 116432, 118620, 118931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37155] = { ["id"] = 37155, ["name"] = "The Brass Compass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37155 }, ["description"] = "Greetings, commander. I have come on a mission directly from the captain. Aboard any vessel on Azeroth that's manned by at least one orc, you'll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms. Perhaps it's just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.", ["objectivesText"] = "Find the Brass Compass at the Iron Docks . Progress: Did you find the compass?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 9172, 109065, 116268, 116432, 118618, 118925 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37156] = { ["id"] = 37156, ["name"] = "The Soulcutter", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37156 }, ["description"] = "Don't look at me! Who do you think you are? You and I are on the same side, you know. The necromancers here, we have to kill them. All of them. Don't you agree? Of course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.", ["objectivesText"] = "Collect a Soulsever Blade from Auchindoun . Progress: Did you find the blade?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118619, 119039 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37157] = { ["id"] = 37157, ["name"] = "Feeling A Bit Morose", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37157 }, ["description"] = "So many years of waking up as a spirit, reanimated by some unseen force time and again, has left one with certain desires - the comforting, velvet blackness of death being chief amongst them. One will, however, settle for the lesser prize of a solution capable of removing the scuff marks that the commander's wonderful compatriots left behind in the dining hall in their woefully short stay in Karazhan, whereupon they barely had enough time to irreparably damage the priceless furniture.", ["objectivesText"] = "Collect a barrel of Horribly Acidic Solution from the Iron Docks . Progress: Was the commander successful?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 28528, 109065, 116432, 118617, 119092 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37158] = { ["id"] = 37158, ["name"] = "Gloriously Incandescent", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37158 }, ["description"] = "I did not come here to fight, I have seen too many die already. I have killed so many with my own hands. I have come to seek the light, and redemption. The arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me. Bring me one of their Sun Crystals . I wish to see this light.", ["objectivesText"] = "Collect a Sun Crystal in Skyreach . Progress: Did you find the crystal?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 109693, 111245, 113588, 116432, 118621, 118928 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37159] = { ["id"] = 37159, ["name"] = "Aviana's Request", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37159 }, ["description"] = "The arakkoa are creatures of the sky, and are thus within the domain of the great Aviana. I have been sent to procure a feather, that we may parley with them through the language of the winds. We will extend an invitation of peace, and a place on the Great Bough. Would you aid us in this quest? The feather must come from an arakkoan of nobility. You will find them in the place known as Skyreach .", ["objectivesText"] = "Collect some Pristine Plumage in Skyreach . Progress: Did you bring a feather?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 9172, 109065, 113082, 116432, 118622, 119093 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37160] = { ["id"] = 37160, ["name"] = "Cleaving Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37160 }, ["description"] = "I, Gamon , have come through the dark portal to cleave many orc skulls. Yet my weapon has not kept pace with my rage, and is nicked and dull. Find me a new weapon - one that is good for removing Hellscream limbs.", ["objectivesText"] = "Find an Iron Limbcleaver in Grimrail Depot . Progress: What?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118643, 118644, 118937 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37161] = { ["id"] = 37161, ["name"] = "Family Traditions", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37161 }, ["description"] = "He ran off with it! Oh what am I going to do, what am I going to DO? My son, and my knife, they ran off to Blackrock Spire! Well, the knife didn't run, I suppose. That doesn't matter! You've got to get it back! Yes, the knife! You've got to get me back my knife! Go! Now! Stop talking!", ["objectivesText"] = "Find Pip's Improved Skinner in Blackrock Spire. Progress: Where's my knife?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 110609, 116432, 118623, 118926 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37162] = { ["id"] = 37162, ["name"] = "Damsels and Dragons", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37162 }, ["description"] = "What ho, squire <name>! Forgive my lips, as they bear gravest news. Dragons have taken up stinking residence within the hallowed halls of Blackrock Spire! These great wyrms hold a distressed damsel in their scaly graspers. Her name is Zaela, they say. Such a beautiful name! As my squire, it is your Light-given duty to adventure yourself into this spire and procure evidence of these dragons, lest I waste my heroism on a dragonless quest.", ["objectivesText"] = "Collect a Shed Proto-Dragon Claw . Progress: Did you find evidence of dragons?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 111557, 116432, 118624, 118927 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37163] = { ["id"] = 37163, ["name"] = "Shadowy Secrets", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37163 }, ["description"] = "Though the Lich King has been defeated, we are no closer to unlocking the secrets of the Frozen Throne than we were when jousting pointlessly at the Argent Tournament. Bolvar remains resigned to his fate. Perhaps there is something here, though, that can aid us. Ner'zhul was not always the Lich King, you know. Once, he was a mere orc dabbling in dark powers beyond his comprehension. Find whatever you can of his early studies, and we may have our answers.", ["objectivesText"] = "Collect a Dark Parchment from the Shadowmoon Burial Grounds . Progress: Did you find any of Ner'zhul 's notes?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118625, 119003 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37164] = { ["id"] = 37164, ["name"] = "The Huntresses", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37164 }, ["description"] = "I do not wish to come out of the shadows, but I mean you no harm. My purpose here is my own secret to keep, I simply needed a warm place to bed down for the night. I can see that you are not the type to be easily swayed into leaving. Very well, perhaps you can aid me in my search. I am looking for someone, it is not important who. All you need to know is that I will reward you for any sign of high elven weaponry that you should come across.", ["objectivesText"] = "Collect a Silver-Lined Arrow from the Shadowmoon Burial Ground. Progress: Did you find anything?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118626, 118923 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37165] = { ["id"] = 37165, ["name"] = "Cenarion Concerns", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37165 }, ["description"] = "Ey mon! De Cenarion Circle sent Zen'kiki out here ta check out dem primals. I woulda been here sooner, but I had a little bit o' trouble gettin' my flight form ta work, mon. De plants in dis place... I can hear dem talk. Dey be yellin' all the time. Angry an' violent yellin'. Would ya bring Zen'kiki back a leaf from dis Everbloom place dey be talkin' about? Maybe I can figure out what dey want.", ["objectivesText"] = "Collect a Strangely-Glowing Frond from Everbloom. Progress: Did ya have much luck, mon?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118627, 118935 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37166] = { ["id"] = 37166, ["name"] = "Titanic Evolution", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37166 }, ["description"] = "Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu'shan Vaults? I am more sturdy than I look! I have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place? At least, that is what I believe! Surely there are signs of the titans' presence here, even now. Should you find one, I would very much like to see it!", ["objectivesText"] = "Collect an Overgrown Artifact from The Everbloom . Progress: Have you found any signs of the titans here?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 116432, 118628, 118930 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37167] = { ["id"] = 37167, ["name"] = "And No Maces!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6984, ["storyline"] = { 37167 }, ["description"] = "There are far too many bright-eyed young rogues being sent through this portal and off to war. If I'm going to start up my academy again, some of them have got to survive this little excursion. While I'm here, I figured I might as well use the opportunity to gather some supplies for my grand opening. You can't start a business without plenty of daggers, after all. Grab me a crate of weaponry from the Grimrail Depot , there should be plenty lying around. I'll have something nice for you.", ["objectivesText"] = "Collect a Huge Crate of Weapons in Grimrail Depot . Progress: Did you find me some weapons?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 109065, 114072, 114073, 114074, 114079, 116432, 118643, 118644, 118924 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6984 } }, ["questType"] = "standard" },
[37168] = { ["id"] = 37168, ["name"] = "Leorajh, the Enlightened", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37168 }, ["rewardGold"] = 421350, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 87561, ["x"] = 0.542, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 87561, ["x"] = 0.542, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37177] = { ["id"] = 37177, ["name"] = "Call of the Talon King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37177 }, ["description"] = "$p, you have done much for my people. I wish to thank you on their behalf. Please visit Veil Terokk when you can.", ["objectivesText"] = "Speak with the Shade of Terokk in Veil Terokk.", ["rewardGold"] = 842700, ["rewardXP"] = 2060, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84122, ["x"] = 0.465333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37179] = { ["id"] = 37179, ["name"] = "For The Children!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37179 }, ["description"] = "Wait, wait! Don't attack me! I've changed! Really, I've turned over a new leaf, I promise. I haven't said \"DOOOOOOM!\" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war. That's why I'm here! Why, with just a single Miniature Iron Star , I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me! So, what do you think, sweetcheeks? Want to help ol' Milhouse save the orphans?", ["objectivesText"] = "Collect a Miniature Iron Star from Upper Blackrock Spire . Progress: Did you find the Iron Star?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118645, 118938 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37180] = { ["id"] = 37180, ["name"] = "An Ogre Without His Sword...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 37180 }, ["description"] = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\" I want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse. It would mean a great deal to me. An ogre without his sword isn't an ogre at all.", ["objectivesText"] = "Retrieve Tormmok's Favorite Sword from Vizier Dar'gud at Broken Precipice in Nagrand. Progress: I want my sword more than I can tell you, commander.", ["rewardGold"] = 58650, ["rewardXP"] = 1365, ["rewardItems"] = { 113913, 118545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37181] = { ["id"] = 37181, ["name"] = "Leorajh's Prayer Beads", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37181 }, ["description"] = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements. One day bird-men attacked and took prayer beads. Took them to Skettis. Master, you help Leorajh get prayer beads back?", ["objectivesText"] = "Retrieve Leorajh's Prayer Beads from Kirox the Wind Dancer in Skettis. Progress: Elements don't speak to Leorajh like they used to.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118571 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37182] = { ["id"] = 37182, ["name"] = "Scrying Hard or Hardly Scrying", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37182 }, ["description"] = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs. They have begun to master their craft... they call to the shadows beyond this realm... I desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", ["objectivesText"] = "Retrieve Urna's Fathomstaff from Urna Darkfathom at Shadowmoon Enclave in Shadowmoon Valley. Progress: Taking out our enemies and gaining great power in one motion... my people have a saying for this: Killing two orcs with one stone.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 116268, 118570 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37183] = { ["id"] = 37183, ["name"] = "The Critical Path", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 535, ["storyline"] = { 37183 }, ["series"] = { 34558, 34676, 35702, 36495, 36576, 49565, 92692 }, ["description"] = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast. Talador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos , who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", ["objectivesText"] = "Speak to Dungar Longdrink to secure a flight to Talador .", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79133, ["x"] = 0.698, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37184] = { ["id"] = 37184, ["name"] = "Taking the Fight to Nagrand", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 37184 }, ["series"] = { 34674, 34675, 34678, 34682, 49567 }, ["description"] = "Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand . I've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you. A gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, <sir/ma'am>.", ["objectivesText"] = "Speak with Lieutenant Balfor at the caravan in Nagrand .", ["rewardXP"] = 600, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79263, ["x"] = 0.864, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37191] = { ["id"] = 37191, ["name"] = "Sanketsu, The Burning Blade", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37191 }, ["description"] = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it. Perhaps someone at your garrison would be interested in seeing this weapon.", ["objectivesText"] = "Bring Sanketsu , the Burning Blade, to Lieutenant Thorn at your garrison.", ["rewardGold"] = 842700, ["rewardXP"] = 1365, ["rewardItems"] = { 120313 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 87764, ["x"] = 0.695, ["y"] = 0.058 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.058 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37192] = { ["id"] = 37192, ["name"] = "Sanketsu, The Burning Blade", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37192 }, ["description"] = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it. Perhaps someone at your garrison would be interested in seeing this weapon.", ["objectivesText"] = "Bring Sanketsu , the Burning Blade, to Warmaster Zog at your garrison.", ["rewardGold"] = 842700, ["rewardXP"] = 1365, ["rewardItems"] = { 120313 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 87764, ["x"] = 0.695, ["y"] = 0.058 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.058 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37201] = { ["id"] = 37201, ["name"] = "Cymre Brightblade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 37201 }, ["description"] = "I found some interesting artifacts on a recent dig, and I'd love to put them through their paces to see how they would have performed in their native cultures. Don't suppose you have anything small and furry that can put up a fight?", ["objectivesText"] = "Defeat Cymre Brightblade in a pet battle. Progress: Did you want to pet battle or just talk...", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 44721, 92738, 116415, 163036 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 83837, ["x"] = 0.51, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 83837, ["x"] = 0.51, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[37203] = { ["id"] = 37203, ["name"] = "Ashlei", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 37203 }, ["description"] = "I don't really like when my pets fight, but I love making them feel better when they're done.", ["objectivesText"] = "Defeat Ashlei in a pet battle. Progress: Hi.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 54436, 92738, 116415, 163036 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 87124, ["x"] = 0.5, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 87124, ["x"] = 0.5, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[37204] = { ["id"] = 37204, ["name"] = "Rekindling an Old Flame", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 37204 }, ["description"] = "I am dying, <race>. My flame, it smolders... soon my light will flicker and fade into nothing. You mustn't allow this. Retrieve for me the Essence of Flame. Allow me to live another day and I will burn every breaker to ash, I swear it. I will take vengeance for my brothers and sisters.", ["objectivesText"] = "Deliver the Essence of Flame to Firaga in Magnarok. Progress: Do you have it, <name>? Will you kindle my flame?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 122403, 127669 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 87971, ["x"] = 0.748, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 87971, ["x"] = 0.748, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[37205] = { ["id"] = 37205, ["name"] = "Gargra", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 37205 }, ["description"] = "Do you wish to offer challenge? My wolves must train to become strong.", ["objectivesText"] = "Defeat Gargra in a pet battle. Progress: My wolves grow restless.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 92738, 116415, 163036 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 87122, ["x"] = 0.686, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 87122, ["x"] = 0.686, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[37206] = { ["id"] = 37206, ["name"] = "Tarr the Terrible", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37206 }, ["description"] = "Tarr is the true warlord! Bring your army to fight and I show you.", ["objectivesText"] = "Defeat Tarr the Terrible in a pet battle. Progress: Tarr destroy your face!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 60955, 92738, 98715, 104159, 116415, 146953, 163036 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87110, ["x"] = 0.562, ["y"] = 0.098 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87110, ["x"] = 0.562, ["y"] = 0.098 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.098 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37207] = { ["id"] = 37207, ["name"] = "Vesharr", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37207 }, ["description"] = "I had a vision with one who had mastered pets came to challenge me. Has the vision finally come to pass?", ["objectivesText"] = "Defeat Vesharr in a pet battle. Progress: Can you defeat me?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 87526, 92738, 93040, 113216, 116415, 120050, 120051, 163036 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 87123, ["x"] = 0.464, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 87123, ["x"] = 0.464, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37208] = { ["id"] = 37208, ["name"] = "Taralune", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37208 }, ["description"] = "I strive to teach through non-lethal pet battle. Are you willing to learn?", ["objectivesText"] = "Defeat Taralune in a pet battle. Progress: You have not yet learned enough.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 92738, 116415, 136898, 163036 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 87125, ["x"] = 0.49, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 87125, ["x"] = 0.49, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37209] = { ["id"] = 37209, ["name"] = "Cold Steel Part II", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37209 }, ["description"] = "Hey, you. I wanted to thank you for what you did for me. The feel of that cannon in my hands is all the therapy I'll ever need. But now... <Keeshan stares off into the distance and grimaces.>...I'm all out of bullets. Guess I'll just sit here and wait to die.", ["objectivesText"] = "Find an Iron Autocannon in Grimrail Depot . Progress: Leave me alone.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 118653, 119036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37210] = { ["id"] = 37210, ["name"] = "Aogexon's Fang", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37210 }, ["objectivesText"] = "Progress: Aogexon is one of the most feared beasts in Nagrand , and one of the largest and most dangerous forest stalkers ever seen! I've already been approached by a number of a collectors interested in obtaining one of Aogexon's deadly fangs. If you are up for the challenge, Aogexon can sometimes be found lurking in the swamp not far from here. Good luck!", ["rewardGold"] = 339600, ["rewardItems"] = { 86574, 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172, 120182 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37211] = { ["id"] = 37211, ["name"] = "Bergruu's Horn", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37211 }, ["objectivesText"] = "Progress: An anonymous collector of valuable fossils and antiques has offered the preservation society a huge cash reward for Bergruu's horn . A huge reward, <name>... HUGE!", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37222] = { ["id"] = 37222, ["name"] = "Direhoof's Hide", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37222 }, ["objectivesText"] = "Progress: Most talbuk are peaceful creatures that will only attack when they are defending their herd. Not Direhoof though, that talbuk is one of the most aggresively dangerous beasts I've ever encountered... and one of the most magnificent talbuk I've ever seen! If you encounter Direhoof while adventuring and live to tell the tale, return to me with the beast's hide and I'll see that you're rewarded!", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37223] = { ["id"] = 37223, ["name"] = "Gagrog's Skull", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37223 }, ["objectivesText"] = "Progress: Deep in the forest of northern Nagrand is a giant Gronn known as Gagrog the Brutal. In case you're wondering, he didn't get his name by giving out free hugs... this Gronn is as savage and murderous as they come! Now look, I'm not telling you to go try and hunt this thing down... that would be suicide... but if by some miracle you fight Gagrog and live, make sure you bring back his skull!", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37224] = { ["id"] = 37224, ["name"] = "Mu'gra's Head", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37224 }, ["objectivesText"] = "Progress: Not far from here is a hippo of unusual size and ferocity known as Mu'gra. I've been contacted by a private collector that would like to acquire Mu'gra's teeth for a special exhibit. Hippo teeth are extremely difficult to extract, and we can't be selling damaged goods so just bring back the entire head, got it? Good luck!", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37225] = { ["id"] = 37225, ["name"] = "Thek'talon's Talon", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37225 }, ["objectivesText"] = "Progress: Windrocs can be found all over Nagrand , from the highest peaks to the lowest valleys. However, one windroc in particular is extremely elusive and is rarely sighted, it is known to the orcs as Thek'talon. If I know anything, it's that people will pay a lot of money for anything that is rare or elusive!", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37226] = { ["id"] = 37226, ["name"] = "Xelganak's Stinger", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37226 }, ["objectivesText"] = "Progress: Xelganak is as deadly as they come, <name>! I don't recommend going after Xelganak unless you love money, adventure, and glory. Xelganak's poison stinger would be an easy sell to the right collector, so if you're up for the challenge I'll make sure you get handsomely rewarded. Just don't go getting your face melted off like Bozzil, ok?", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37227] = { ["id"] = 37227, ["name"] = "Put a Bird on It", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37227 }, ["description"] = "<name>! Have you met the peachick you saved the other day? < Mylune holds up a peachick hatchling, then trills and twitters at it. She gestures to you, says your name, then continues chirping animatedly to the little bird. The two ignore you and engage in a lengthy bird-conversation, long enough to make you feel awkward. Finally the dryad turns her attention back to you.> Did you hear that? More peachicks are still trapped in the Everbloom ! If you don't save them... well, you heard what will happen!", ["objectivesText"] = "Find a Tiny Peachick Hatchling in The Everbloom . Progress: < Mylune stamps her hooves impatiently.>", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 118652, 119036, 119093 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37228] = { ["id"] = 37228, ["name"] = "A Fruitful Proposition", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37228 }, ["description"] = "The head of just ONE ogre won't be enough to stop the fruit vendor. No, the fruit vendor is wise, they would not put all of their fruit into one basket. Bring me the head of ANOTHER ogre! Ha! Then what will the fruit vendor do? Cry onto their bananas as they rot and fall to the ground. DESPAIR, FRUIT VENDOR. SO DELICIOUS!", ["objectivesText"] = "Collect a Giant Ogre Head from the Bloodmaul Slag Mines . Progress: THE FRUIT VENDOR STANDS NO CHANCE!", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 118534, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37229] = { ["id"] = 37229, ["name"] = "Like A Dwarf In A Mine", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37229 }, ["description"] = "Baelog and Eric swear there's got to be treasure at the bottom of the mine. Why? Because it's a mine! An' we sure do love rocks that sparkle. On our last trip, we were beaten back by huge ogres. Baelog held up the rear, swingin' his sword, while Eric rushed on ahead to try and find a quick exit. Wouldn't you know, in all that excitement, I done lost my shield AGAIN? < Olaf looks at you imploringly.>", ["objectivesText"] = "Collect Olaf's Shield from the Bloodmaul Slag Mines . Progress: < Olaf sobs.>", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118616, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37230] = { ["id"] = 37230, ["name"] = "Bloody Expensive", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37230 }, ["description"] = "Welcome back, commander. The commander is obviously in a great hurry, and certainly the thought of removing their coat or boots or not dripping all over the floor are much too far beyond consideration. The commander remembers the acidic solution, yes? Quite effective it was, though one barrel was not enough to remove ALL of the blood stains from the portraits, or the tapestries, or the ceiling. Surely this must have been the most heroic and viscous battle in recent history.", ["objectivesText"] = "Collect a barrel of Horribly Acidic Solution from the Iron Docks . Progress: Was the commander successful?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118617, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37231] = { ["id"] = 37231, ["name"] = "The Search Continues", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37231 }, ["description"] = "An old deckhand inspected that device you brought us, and thinks it was quite the forgery. This Iron Horde is trying to copy the mechanism, but they don't quite have the technology. When you get right down to it, we're not sure how these primitive beasts got a hold of this kind of tool. Wouldn't be half as good of a sea tale if we knew, ha! We've still got a pile of treasure with your name on it, if you can find us the real compass.", ["objectivesText"] = "Find the Brass Compass at the Iron Docks . Progress: Did you find the compass?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 422, 118618, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37232] = { ["id"] = 37232, ["name"] = "Soulcarver Voss", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37232 }, ["description"] = "You! You're the one that found me the blade, correct? I have need of your services again. The blade worked wonderfully, allowing me to sever the tormented undead from this world. Their screams were such beautiful music. However, the Soulsever Blade cannot be repaired, as it is partially woven with spirit energy that is drawn upon each time a soul is released. I need another, as there are still dark forces at work in this place, raising spirits and turning them.", ["objectivesText"] = "Collect a Soulsever Blade from Auchindoun . Progress: Did you find the blade?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118619, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37233] = { ["id"] = 37233, ["name"] = "Vessel of Virtue", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37233 }, ["description"] = "Hello, again, commander. This plague yet vexes me, but I shall remain resolute, with the light as my guide. The Soulweave Vessel has aided our investigations into the world beyond and the transition from life to death. With more vessels, we may be able to discover the truth behind the bridge between worlds. Perhaps there is a reason why the scourged do not fully make this transition. Any additional help would be greatly appreciated by the Argent Dawn.", ["objectivesText"] = "Collect a Soulweave Vessel from Auchindoun . Progress: Did you find anything?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118620, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37234] = { ["id"] = 37234, ["name"] = "The Dark Within", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37234 }, ["description"] = "The light... has gone out. I know not why. I am more troubled now than before. I can find little comfort in the everyday. Each day seems darker than the last. Please, bring me another one of the Sun Crystals . Its light is so warm, so comforting.", ["objectivesText"] = "Collect a Sun Crystal in Skyreach . Progress: Did you find the crystal?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 118621, 119037, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37235] = { ["id"] = 37235, ["name"] = "A Plea to the Sky", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37235 }, ["description"] = "We have, so far, been unsuccessful in our attempts to contact the arakkoa. Each attempt strips the plumage, and we are left with a feather that is tattered and broken. Aviana implores you, commander, to find another plume for her. We do not wish to see our brethren become victim of their own violent nature. All beings of the sky have a place with us, in life or beyond.", ["objectivesText"] = "Collect some Pristine Plumage in Skyreach . Progress: Did you bring a feather?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118622, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37236] = { ["id"] = 37236, ["name"] = "Like Father, Like Son", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37236 }, ["description"] = "He's done it again! My son took my knife and yelled something about a 'chromatic hide,' then ran off for the Spire! What would he even do with something like that, wear it around like a cape? If it's not too much to ask, would you keep an eye out for the knife? You know, next time you're around Upper Blackrock Spire . Which, hopefully, is soon. VERY soon.", ["objectivesText"] = "Find Pip's Improved Skinner in Blackrock Spire. Progress: Where's my knife?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 12607, 18509, 118623, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37237] = { ["id"] = 37237, ["name"] = "A Hero's Quest is Never Complete", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37237 }, ["description"] = "What ho, squire <name>! Since last we spoke, I have heroically approached the gates of Blackrock Spire and nobly intended to end the toothy reign of its dragons. Yet, as I neared the place, my mind drifted to thoughts of my Doloria's fair face, and to my own painfully unsatisfied desires. My sword arm fell limp at my side. I charge THEE then, squire, to go in my stead and search Upper Blackrock Spire . I must know if the dragons still squirm within its corridors.", ["objectivesText"] = "Collect a Shed Proto-Dragon Claw . Progress: Did you find evidence of dragons?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118624, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37238] = { ["id"] = 37238, ["name"] = "Secrets of Soulbinding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37238 }, ["description"] = "We have reviewed Ner'zhul 's notes, which you brought to us previously. Though we are closer to understanding how these warlocks have learned to bind souls and control the undead, the picture is incomplete. We will need more pages if we are to see the whole picture. I do not want to experiment with partial information and create an abomination. There are enough of those in Northrend as it is.", ["objectivesText"] = "Collect a Dark Parchment from the Shadowmoon Burial Grounds . Progress: Did you find any of Ner'zhul 's notes?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118625, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37239] = { ["id"] = 37239, ["name"] = "Fate of the Fallen", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37239 }, ["description"] = "I feel that I can trust you, perhaps. You have, at least, not spoken of my secret to anyone, and for that I thank you. I have need of your aid again, and in return, I will share some of my own information. I am here, you see, to find an elf by the name of Alleria. She was lost years ago, on Draenor. It is my faint hope that the twisting nether brought her here. I do not know if such a thing is even possible, but do keep an eye out for any signs of high elves as you travel.", ["objectivesText"] = "Collect a Silver-Lined Arrow from the Shadowmoon Burial Ground. Progress: Did you find anything?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 118626, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37240] = { ["id"] = 37240, ["name"] = "The Leaf-Reader", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37240 }, ["description"] = "Good ta see you again, mon! De Cenarion Circle sent Zen'kiki out here ta find some more of dem plants. We not likin' what we be seein' here. If ya find any more of dem leaves, bring one on back. Dey can see right through Zen'kiki 's tree disguise, even when he plant himself in da ground! And dat make it harder to run!", ["objectivesText"] = "Collect a Strangely-Glowing Frond from Everbloom. Progress: Did ya have much luck, mon?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118627, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37241] = { ["id"] = 37241, ["name"] = "Lessons of the Past", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37241 }, ["description"] = "I have returned! You must have known that a world so rich in history could not keep me away for long! < Lorewalker Cho chuckles, holding his enormous belly.> I have perhaps been taking part in too many celebratory feasts, now that the Vale has been cleansed. There is so much to celebrate in Pandaria! Should you find any future evidence of titanic influence on the native species, I will be here, heartily enjoying the roast clefthoof.", ["objectivesText"] = "Collect an Overgrown Artifact from The Everbloom . Progress: Have you found any signs of the titans here?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118628, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37243] = { ["id"] = 37243, ["name"] = "An Axe to Grind", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37243 }, ["description"] = "I, Gamon , have cleaved many orc skulls. Yet many of the iron horde remain, full of limbs and blood. I will relieve them of these things! Or I would, if I had an axe. The last one broke in half in the middle of an orc's ribcage. < Gamon laughs heartily.> Bring me another, so that I may continue cleaving my way through this land!", ["objectivesText"] = "Find an Iron Limbcleaver in Grimrail Depot . Progress: What?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 118644, 119037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37244] = { ["id"] = 37244, ["name"] = "Flamefly Trap", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37244 }, ["description"] = "Ol' Winky still hasn't come back! Now I'm gettin' worried. Do me a favor and get another one of those flameflies from Upper Blackrock Spire . If we get enough of em,' Winky's sure to see the glimmer and come heading on back. An then we'll have him right where we want him!", ["objectivesText"] = "Collect a Spire Flamefly in Upper Blackrock Spire . Progress: Did ye get another fly?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 118650, 119036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37245] = { ["id"] = 37245, ["name"] = "Whispers in the Darkness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37245 }, ["description"] = "If you don't mind, I'm trying VERY hard to prevent all of our worlds from collapsing into the void, AGAIN. Oh, right, you helped me last time, didn't you? Well, you've got great timing. I'm in need of another Gate-Key. Well? Go on! The infinite horrors of the abyss aren't just going to wait until you've had a nap! Having that many tentacles makes them really antsy.", ["objectivesText"] = "Find a Void-Gate Key in the Shadowmoon Burial Grounds . Progress: You do know that any time you waste talking to me brings us closer to doom, right?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 118651, 119036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37247] = { ["id"] = 37247, ["name"] = "Angry Brewfest Letter", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37247 }, ["rewardGold"] = 15, ["rewardXP"] = 200, ["rewardItems"] = { 119209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
