[37296] = { ["id"] = 37296, ["name"] = "A Lack of Wasps", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37296 }, ["series"] = { 35697, 35699, 37326, 37327 }, ["description"] = "The stings! These cursed wasps drone day and night and their constant aggression taxes me so. I shall do nothing about your offer until these nuisances are dealt with.", ["objectivesText"] = "Kill 8 Widow Wasps . Progress: Wasps are truly despicable things.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
