[37307] = { ["id"] = 37307, ["name"] = "Gold Victory", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37307 }, ["objectivesText"] = "Progress: The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous. Lead us to great victory, Commander.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 116980, 119155, 122163, 122472 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
