[37318] = { ["id"] = 37318, ["name"] = "The Dead Do Not Forget...", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37318 }, ["description"] = "Many years ago my family and I were slain in this very spot. The saberon you see around you are descended from the tribe that murdered my village. Long have I waited, here in this forgotten place, to see justice brought to the saberon for their crimes. The Snarlpaw chief is a boneseer, a saberon who divines the future using the remains of the dead. Collect the ancient skulls of the Snarlpaw ancestors and place them in the boneseer's cauldron . Let their own bones fill their cauldron for once!", ["objectivesText"] = "Place 10 Ancient Snarlpaw Skulls in the Boneseer's Cauldron . Progress: <The cauldron bubbles and boils.>", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 119184, 128438 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 88500, ["x"] = 0.795, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37319] = { ["id"] = 37319, ["name"] = "Jewelcrafting Special Order: Wedding Bands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37319 }, ["description"] = "We've been asked to craft a pair of wedding bands. The clients requested that they be made by you.", ["objectivesText"] = "Craft two Glowing Blackrock Bands . The secondary stats do not matter. Progress: Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", ["rewardItems"] = { 109118, 109119, 111983, 115993, 119191, 119195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37320] = { ["id"] = 37320, ["name"] = "Jewelcrafting Special Order: A Fine Choker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37320 }, ["description"] = "We have a request for a fine necklace. The client wants to give it to an old enemy, to end the conflict. She didn't specify a design, but I think I heard her mumbling under her breath about a choker. Oh, and she asks that the chain be \"extra sturdy\".", ["objectivesText"] = "Craft a Whispering Iron Choker . The secondary stats do not matter. Progress: Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", ["rewardItems"] = { 109118, 115524, 115992, 119191, 119195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37321] = { ["id"] = 37321, ["name"] = "Jewelcrafting Special Order: A Yellow Brighter Than Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37321 }, ["description"] = "We've been commissioned to make a gold bracelet, set with a taladite crystal \"even brighter than gold\". I can handle the metal work, but the crystal isn't something I can do.", ["objectivesText"] = "Craft a Critical Strike Taladite . Progress: Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", ["rewardItems"] = { 109118, 111983, 115803, 119191, 119195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37322] = { ["id"] = 37322, ["name"] = "The Prophet's Final Message", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["storyline"] = { 37322 }, ["description"] = "This unassuming iridescent crystal contains some of the final thoughts of Great Prophet Velen, created sometime in the hours before he confronted Ner'zhul. Deliver the crystal to Prophet Velen's Memorial beneath the Coliseum of Light near Karabor to hear his final message.", ["objectivesText"] = "Deliver the Prophet's Arcanum to Prophet Velen's Memorial beneath the Coliseum of Light in Shadowmoon Valley . Progress: The arcanum hums in your hand as you get close to the memorial.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 119208, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 119208 } },
[37323] = { ["id"] = 37323, ["name"] = "Jewelcrafting Special Order: Blue the Shade of Sky and Sea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37323 }, ["description"] = "The client wants a pair of silver earrings, set with blue crystals to match her eyes. The metal work is simple enough, but I don't know how to create such a shade of taladite.", ["objectivesText"] = "Craft two Haste Taladite . Progress: Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", ["rewardItems"] = { 109118, 111983, 115804, 119191, 119195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37324] = { ["id"] = 37324, ["name"] = "Out of Stock: Blackrock Ore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37324 }, ["description"] = "Our latest bracelet design is selling like mad, but we are completely out of the blackrock to make them.", ["objectivesText"] = "Obtain twenty Blackrock Ore . Progress: Unless we get more blackrock ore , we will not be able to fill the orders.", ["rewardItems"] = { 109118, 111983, 119191, 119195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37325] = { ["id"] = 37325, ["name"] = "Out of Stock: True Iron Ore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37325 }, ["description"] = "It seems our little boutique is gaining a reputation. We use true iron in all our designs, and guess what: we're out!", ["objectivesText"] = "Obtain twenty True Iron Ore . Progress: We are fortunate that our jewelry is so popular, but we won't be able to make more without any true iron.", ["rewardItems"] = { 109118, 109119, 111983, 119191, 119195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37326] = { ["id"] = 37326, ["name"] = "Befriending the Locals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37326 }, ["series"] = { 35697, 35699, 37296, 37327 }, ["description"] = "We need allies desperately if we want a chance at surviving until tomorrow. We've made contact with one of the outcast arakkoa, but he refused to discuss alliances without speaking to you first. He called himself Dusk-Seer Irrizar. You should speak with him, commander. You can find him just southwest of Veil Terokk.", ["objectivesText"] = "Speak to Dusk-Seer Irizzar near Veil Terokk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37327] = { ["id"] = 37327, ["name"] = "Befriending the Locals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37327 }, ["series"] = { 35697, 35699, 37296, 37326 }, ["description"] = "Commander, I believe it best for the safety of this outpost if we secure an ally. We've made contact with one of the outcast arakkoa, but he refused to make any promises of alliance without speaking to you first. He called himself Dusk-Seer Irrizar. Could you go speak with him, commander? You can find him just southwest of Veil Terokk.", ["objectivesText"] = "Speak to Dusk-Seer Irizzar near Veil Terokk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81929, ["x"] = 0.398, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37328] = { ["id"] = 37328, ["name"] = "Not Here, Not Now", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 37328 }, ["description"] = "I will travel to your people to make arrangements soon. For now, begone. Leave me in peace.", ["objectivesText"] = "Speak to Taskmaster Gornek at Axefall.", ["rewardGold"] = 5865, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113096, 116394, 116431, 119001, 140251, 237812 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
