[37511] = { ["id"] = 37511, ["name"] = "Dizzy Sparkshift", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37511 }, ["series"] = { 35945, 35970, 35972, 35973, 36117, 37516 }, ["description"] = "I'm in a pretty good spot as far as artifacts go. We have a couple other society members out in the field. I'd go look for them, but it seems like a bad idea from a health perspective. You don't seem to have a problem with pain, think you could find Dizzy?", ["objectivesText"] = "Find Dizzy Sparkshift .", ["rewardGold"] = 117300, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83734, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 76508, ["x"] = 0.406, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37516] = { ["id"] = 37516, ["name"] = "News for Nixxie", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37516 }, ["series"] = { 35945, 35970, 35972, 35973, 36117, 37511 }, ["description"] = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation. If you see her can you let her know we will be back soonish?", ["objectivesText"] = "Speak with Nixxie .", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 119128 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 76508, ["x"] = 0.406, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37517] = { ["id"] = 37517, ["name"] = "News for Nixxie", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37517 }, ["series"] = { 35945, 35970, 35972, 35973, 35985, 37511 }, ["description"] = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation. If you see her can you let her know we will be back soonish?", ["objectivesText"] = "Speak with Nixxie .", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 119128 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 76508, ["x"] = 0.406, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37520] = { ["id"] = 37520, ["name"] = "Vileclaw's Claw", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37520 }, ["objectivesText"] = "Progress: Vileclaw is feared throughout Nagrand as a vicious predator. While it is true that Vileclaw is one of the most dangerous raptors you'll ever encounter, she is also a savagely beautiful creature. Vileclaw must be preserved for future generations to behold! If you can bring me back one of her vicious claws, I'll make sure you get a cut of the profit!", ["rewardGold"] = 339600, ["rewardItems"] = { 118099, 118100, 118654, 118655, 118656, 118657, 118658, 118659, 118660, 118661, 120172 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 87706, ["x"] = 0.502, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37523] = { ["id"] = 37523, ["name"] = "Assault on the Gorian Proving Grounds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37523 }, ["description"] = "The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.", ["objectivesText"] = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119384, 120317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
