[37868] = { ["id"] = 37868, ["name"] = "More Big Racing!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 37868 }, ["description"] = "You like this big race, do you? Me too! It has four legs: get to the purple post, then green, then red, then back here. Your time matters, so do it fast!", ["objectivesText"] = "Run through the Start Banner, hit the Purple Post, then the Green Post, then the Red Post, then the return to the Start Banner. Progress: You haven't hit all the markers. Hurry!", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[37881] = { ["id"] = 37881, ["name"] = "Treasure Contract: Explosive Discoveries", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37881 }, ["series"] = { 37882, 37883, 37884, 37885, 37994 }, ["description"] = "In Shadowmoon Valley there is a cave said to possess an ancient tome that may contain secrets that can help our cause against the Iron Horde. The cave, however, is protected by an ancient barrier composed of arcane energy. There is a goblin in Darktide Roost, said to know how to take down any barrier. Persuade him to give up his secrets and bring back the book.", ["objectivesText"] = "Defeat Demolitionist Megacharge in Darktide Roost and take his explosives cookbook.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 104299, 109076, 118711, 119093, 121831, 121832, 121834, 121837, 122273, 122399, 122404, 122407, 122409, 122415, 122417, 122423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37882] = { ["id"] = 37882, ["name"] = "Dark Grimoire: The First Ingredient", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["storyline"] = { 37882 }, ["series"] = { 37881, 37883, 37884, 37885, 37994 }, ["description"] = "You will need three ingredients to make Megacharge's special \"Arcane Bunker Buster,\" which should be able to take down the barrier. The first ingredient, some precision blasting powder , should be available nearby. The book reads: \"To make one, you'll first need to acquire some high grade, precision blasting powder . Here in Blackfuse Company, it's pretty easy to come by, since they use it for all of the cannons.\"", ["objectivesText"] = "Follow the clue from Megacharge's Cookbook to locate some precision blasting powder .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 104299, 118711, 119093, 121830, 121831, 121832, 121834, 121837, 127709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[37883] = { ["id"] = 37883, ["name"] = "Dark Grimoire: The Second Ingredient", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37883 }, ["series"] = { 37881, 37882, 37884, 37885, 37994 }, ["description"] = "With the blasting powder acquired, you now must find a suitable detonator. A note attached to the entry in the cookbook hints to where one might be found: \"Reminder: Order more high-voltage detonators. The last shipment was lost off of the Shadowmoon coast near the demon-inhabited cliffs. Maybe we should send a diving team to salvage.\"", ["objectivesText"] = "Follow the clue from Megacharge's Cookbook to find the high voltage detonator .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 19970, 44050, 81354, 104299, 119093, 121831, 121832, 121837 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37884] = { ["id"] = 37884, ["name"] = "Dark Grimoire: The Final Ingredient", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["storyline"] = { 37884 }, ["series"] = { 37881, 37882, 37883, 37885, 37994 }, ["description"] = "The final ingredient to create Megacharge's bomb is a sizable quantity of demon's blood . Unfortunately, that's not something they're likely to give up easily...", ["objectivesText"] = "Collect blood from demons in Socrethar's Rise.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 104299, 119093, 121832, 121837 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[37885] = { ["id"] = 37885, ["name"] = "Dark Grimoire: Breaching the Barrier", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["requiredClasses"] = { 2, 5, 10 }, ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37885 }, ["series"] = { 37881, 37882, 37883, 37884, 37994 }, ["description"] = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier. There's only one way to find out...", ["objectivesText"] = "Destroy the ancient barrier below Socrethar's Rise and claim the Grimoire of the Nameless Void . Progress: Dr. Jones asked me to take this book from you, but I'm not sure I want to touch it.", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 72140, 81354, 89682, 104299, 109076, 111820, 113542, 113543, 114244, 114246, 116113, 118711, 119093, 119436, 121831, 121832, 121834, 121837, 127669 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
