[37910] = { ["id"] = 37910, ["name"] = "The Real Race", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 37910 }, ["description"] = "Ok, Darkmoon Racer, let's see what you got! The real race has four legs: get to the blue post, then green, then red, then back here. Your time matters, so do it fast!", ["objectivesText"] = "Run through the Start Banner, hit the Blue Post, then the Green Post, then the Red Post, then return to the Start Banner. Progress: You haven't hit all the markers. Hurry!", ["rewardItems"] = { 93724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[37911] = { ["id"] = 37911, ["name"] = "The Real Big Race", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 37911 }, ["description"] = "Here's the big one! Good luck out there! This race has four legs: get to the purple post, then green, then red, then back here. Your time matters, so do it fast!", ["objectivesText"] = "Run through the Start Banner, hit the Purple Post, then the Green Post, then the Red Post, then the return to the Start Banner. Progress: You haven't hit all the markers. Hurry!", ["rewardItems"] = { 93724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[37914] = { ["id"] = 37914, ["name"] = "Treasure Contract: The Thunderlord Sage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37914 }, ["series"] = { 37916, 37917, 37918, 37919, 37995 }, ["description"] = "In Frostfire Ridge , a Thunderlord sage by the name of Argoram seems to have uncovered the whereabouts of a storied weapon, known to the orcs as Gronnsbane. He was last spotted headed into Magnarok. Find him and see if he can lead you to this relic.", ["objectivesText"] = "Locate the Thunderlord sage Argoram in Magnarok.", ["rewardGold"] = 42450, ["rewardXP"] = 1365, ["rewardItems"] = { 109131, 122096, 122098, 122099, 122101, 122102, 122103, 122399, 122404, 122407, 122409, 122415, 122417, 122423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37916] = { ["id"] = 37916, ["name"] = "Gronnsbane: The Broken Spear", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["storyline"] = { 37916 }, ["series"] = { 37914, 37917, 37918, 37919, 37995 }, ["description"] = "Looking through Argoram's journal, it becomes apparent that claiming this relic will be far more complicated than simply finding the pieces of the spear. However, that would be the best place to start...", ["objectivesText"] = "Search throughout Magnarok for Gronnsbane's blade , haft, and weight.", ["rewardGold"] = 42450, ["rewardXP"] = 1365, ["rewardItems"] = { 109131, 122096, 122098, 122099, 122101, 122102, 122103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[37917] = { ["id"] = 37917, ["name"] = "Gronnsbane: The Blessing of Fire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["storyline"] = { 37917 }, ["series"] = { 37914, 37916, 37918, 37919, 37995 }, ["description"] = "The weapon has been assembled, but it lacks the power that made it a legend. In order to restore it, you must receive three blessings: one of fire, one of frost, and one of beasts. The first blessing mentioned in the journal is that of fire. The journal reads: \"He describes an ancient monolith, perched upon the edge of a precipice extending from the cliff where the searing magma falls into the sea. I believe the location he speaks of is just overlooking Tor'goroth's Tooth.\"", ["objectivesText"] = "Follow the clue to find the Molten Shamanstone and receive the Blessing of Fire.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 109131, 122096, 122098, 122099, 122101, 122103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[37918] = { ["id"] = 37918, ["name"] = "Gronnsbane: The Blessing of Frost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37918 }, ["series"] = { 37914, 37916, 37917, 37919, 37995 }, ["description"] = "The weapon has been imbued with the Blessing of Fire, drawing power from the Molten Shamanstone. The Frozen Shamanstone should impart the next blessing. Argoram mentions its location in his journal: \"As I was maneuvering away from the great boulders hurled at me by the ogron brutes, I glanced what looked like another monolith atop the tallest of the snow-capped towers in Bloodmaul. Perhaps this is the Frozen Shamanstone, which is thought to grant the Blessing of Frost\"", ["objectivesText"] = "Follow the clue to find the Frozen Shamanstone and receive the Blessing of Frost.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 109131, 122096, 122098, 122099, 122101, 122103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37919] = { ["id"] = 37919, ["name"] = "Gronnsbane: The Blessing of Beasts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37919 }, ["series"] = { 37914, 37916, 37917, 37918, 37995 }, ["description"] = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads: \"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", ["objectivesText"] = "Defeat the ancient black rylak and douse Gronnsbane in its blood. Once empowered, return the weapon to Bodrick Grey for your reward. Progress: Have you returned with the Thunderlords' relic?", ["rewardGold"] = 2736079, ["rewardXP"] = 1365, ["rewardItems"] = { 44998, 109131, 122096, 122098, 122099, 122101, 122102, 122103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37921] = { ["id"] = 37921, ["name"] = "Clearing the Docks", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 37921 }, ["description"] = "Our salvage team thought these here docks would be abandoned, but they're crawlin' wit' remnants of the Iron Horde. Gul'dan's cronies are convertin' anyone they can and evacuatin' everyone to Tanaan Jungle. Commander, if yeh can clear this place out, my team can salvage some of this equipment. Plus, ev'ry orc yeh kill here is one less ta worry about in Tanaan!", ["objectivesText"] = "Kill 1 Iron Horde orcs and 50 ogron.", ["rewardGold"] = 169800, ["rewardXP"] = 685, ["rewardItems"] = { 40727, 119093 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Disrupt the Iron Horde Evacuation", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Iron Horde orcs slain", ["amount"] = 50, ["type"] = 0, ["objectID"] = 90025, ["orderIndex"] = 1 }, { ["text"] = "Ogron Slain", ["amount"] = 17, ["type"] = 0, ["objectID"] = 89951, ["orderIndex"] = 2 }, { ["text"] = "Transports Sunk", ["amount"] = 17, ["type"] = 0, ["objectID"] = 93147, ["orderIndex"] = 3 }, { ["text"] = "Siege Weapons Destroyed", ["amount"] = 17, ["type"] = 0, ["objectID"] = 93174, ["orderIndex"] = 4 }, { ["text"] = "Felsworn Prophet Slain", ["amount"] = 10, ["type"] = 0, ["objectID"] = 91596, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543 },
[37924] = { ["id"] = 37924, ["name"] = "Maritime Salvage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 37924 }, ["description"] = "It would go a bit faster if you could mark any bigger piles of resources you see while you are clearing those guys out. Just drop this flag down and someone will be along directly!", ["objectivesText"] = "Mark 7 supply caches with flags.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37934] = { ["id"] = 37934, ["name"] = "In, Through, and Beyond!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37889, 37890, 37934, 37935 }, ["series"] = { 37889, 37890, 37935, 39236, 39241, 39242 }, ["description"] = "A few of us snuck through before we was spotted, den de cannons started up. De small ones are no trouble, but de big one... we gonna need to take it out if we wanna get anyting through.", ["objectivesText"] = "Destroy the Fel Defense Cannon covering the gate.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.6496, ["y"] = 0.5144 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 141, ["name"] = "Tanaan Invasion - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[37935] = { ["id"] = 37935, ["name"] = "The Assault Base", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37889, 37890, 37934, 37935 }, ["series"] = { 37889, 37890, 37934, 39236, 39241, 39242 }, ["description"] = "Nearby be a good place. Not too close to da enemy, but close enough for us to take some pressure off da boys in the west. Follow me.", ["objectivesText"] = "Establish your assault base in Tanaan Jungle.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.6496, ["y"] = 0.5144 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 141, ["name"] = "Tanaan Invasion - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
