[37948] = { ["id"] = 37948, ["name"] = "Death to Nullifier Darkoor!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37948 }, ["description"] = "Gurgthock stopped by from the Ring of Blood and said that Mogor wants his Blood Champion to participate in a special exhibition match. That's you, commander! Just whisper \"I seek the seeker.\" into Gurgthock's ear and he'll get things going for ya!", ["objectivesText"] = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", ["rewardGold"] = 1488770, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37949] = { ["id"] = 37949, ["name"] = "Death to Nullifier Darkoor!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37949 }, ["description"] = "Da goblin Gurgthock stopped by and be sayin' that Mogor wants his Blood Champion to fight in an exhibition match against something terrible he's dug up. Dat be you, boss. If you be ready, whisper to Gurgthock \"I seek da seeker.\" He take care of da rest.", ["objectivesText"] = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37961] = { ["id"] = 37961, ["name"] = "Bringing the Bass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37961 }, ["description"] = "You know what would boost morale around here? Bass. Beats. Music! Everyone loves a party! You go out and get me some hardware, and I'll make a system that will shatter Draenor itself.", ["objectivesText"] = "Collect a Bass Blaster , Laz-Tron Disc Reader , Phonic Amplifier , S.P.R.K. Capacitor , and a Cord of Ancient Wood . Progress: Collect a Bass Blaster , Laz-Tron Disc Reader , Phonic Amplifier , S.P.R.K. Capacitor , and a Cord of Ancient Wood .", ["rewardItems"] = { 91838, 110560, 122195, 122196, 122197, 122198, 122199, 122200, 122201, 122203, 122205, 122206, 122208, 122209, 122210, 122211, 122212, 122213, 122214, 122215, 122216, 122217, 122218, 122219, 122221, 122222, 122223, 122224, 122226, 122228, 122229, 122231, 122232, 122233, 122234, 122236, 122237, 122238, 122239, 122565, 122566, 122567, 122568, 122569, 122613 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37964] = { ["id"] = 37964, ["name"] = "To Gul'dan!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37964 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 39023, 40501 }, ["description"] = "We must act quickly - Garona here tells me that Gul'dan is on the move. He is headed to the Path of Glory to meet with Grommash Hellscream. We have to act while our intelligence is fresh! Hurry and meet us outside of Bladefury's Command in northern Talador. We won't be able to engage Gul'dan and the whole Iron Horde army on our own, but we may just learn something to use against them...", ["objectivesText"] = "Speak with Archmage Khadgar outside of Bladefury's Command in Northern Talador.", ["rewardGold"] = 154900, ["rewardXP"] = 1365, ["rewardItems"] = { 113148, 113149, 113150, 140148, 201989 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 90233, ["x"] = 0.674, ["y"] = 0.066 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
