[37968] = { ["id"] = 37968, ["name"] = "Assault on the Temple of Sha'naar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37968 }, ["description"] = "Up in the hills of Tanaan Jungle , the Sargerei have converted a once-sacred temple into a den of demonic summoning. We must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", ["objectivesText"] = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle . Progress: How goes the attack, sir?", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[37970] = { ["id"] = 37970, ["name"] = "Assault on the Fel Forge", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["storyline"] = { 37970 }, ["description"] = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan. A strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", ["objectivesText"] = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Iron Horde Forces Thwarted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } } },
[37973] = { ["id"] = 37973, ["name"] = "Treasure Contract: The Artificer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37973 }, ["series"] = { 37976, 37977, 37978, 37979, 37997 }, ["description"] = "I have heard of a draenei artificer by the name of Maatun that was seeking to restore an old draenei crystal, possibly of naaru origin. He called the crystal the Dream of Argus. The draenei went missing after seeking out help from the Shadowmoon orcs back before they allied themselves with the Iron Horde. One of your scouts recently spotted a draenei matching the description of Maatun near the entrance of the Pillars of Fate. Go there and see what you can dig up.", ["objectivesText"] = "Search near the entrance of the Pillars of Fate for evidence of Artificer Maatun's crystal.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 122154, 122160, 122161, 122162, 122189, 122399, 122404, 122407, 122409, 122415, 122417, 122423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37976] = { ["id"] = 37976, ["name"] = "Dream of Argus: The First Fragment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["storyline"] = { 37976 }, ["series"] = { 37973, 37977, 37978, 37979, 37997 }, ["description"] = "In his quest to restore the Dream of Argus, Maatun enlisted the help of three orcs. These same orcs betrayed him and took the crystal shards before they could be combined. If you find these orcs, they may still have them. The first target shouldn't be far. The journal reads: \"I was told she spent most of her time in the crystal cave to the north of the encampment. There she studied the native crystals for ways to improve their potential abilities.\"", ["objectivesText"] = "Follow the clue from the journal to find Lor Stonefist. Defeat her and claim the Rough Crystal Shard .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 122154, 122160, 122161, 122162, 122189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[37977] = { ["id"] = 37977, ["name"] = "Dream of Argus: The Second Fragment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37977 }, ["series"] = { 37973, 37976, 37978, 37979, 37997 }, ["description"] = "The second orc that Matuun mentioned was a master runecarver and sorcerer. He should be located somewhere in the main camp. The journal reads: \"She mentioned that the orc could normally found in one of the runemaster's huts in the southern part of the camp. They could be identified by the standing stones surrounding the structure, as well as the floating runestones above.\"", ["objectivesText"] = "Follow the clue in the journal to find Vok Blacktongue. Defeat him and claim the Cracked Crystal Shard .", ["rewardGold"] = 52140, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 122154, 122160, 122161, 122162, 122189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37978] = { ["id"] = 37978, ["name"] = "Dream of Argus: The Final Fragment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37978 }, ["series"] = { 37973, 37976, 37977, 37979, 37997 }, ["description"] = "The last orc to be found was a hermit who kept away from the bulk of the Shadowmoon orcs at the Pillars of Fate camp, but was often seen in the high hills above. The journal reads: \"It is said, however, that he can often be seen among the graves upon the high hill, overlooking the camp below. There he would commune with the dead ancestors, whom it is said he preferred over his living brethren.\"", ["objectivesText"] = "Follow the clue in the journal to find Koros Soulsplinter. Defeat him and claim the Smooth Crystal Shard .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 122154, 122160, 122161, 122162, 122189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37979] = { ["id"] = 37979, ["name"] = "Dream of Argus: The Crystal Reborn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37979 }, ["series"] = { 37973, 37976, 37977, 37978, 37997 }, ["description"] = "With the shards recovered, it is now possible to restore the Dream of Argus . You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", ["objectivesText"] = "Locate the crystal reconstruction device and use it to restore the Dream of Argus . Progress: Were you able to restore the draenei crystal?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 122154, 122160, 122161, 122162, 122189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37981] = { ["id"] = 37981, ["name"] = "The World Famous Ring of Blood!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 37981 }, ["description"] = "Dear Unadulterated Badass, If you're reading this, you're exactly the sort of tough-as-nails champ in the making we need down at the Ring of Blood in Nagrand . You and two friends are cordially invited to fight for your lives against the toughest creatures this side of Gorgrond. It's positively brutal - and the crowd loves it! Come talk to me to start your first fight - beat four of the fiercest creatures I've got and you'll get a shot at the champ himself! - Gurgthock", ["objectivesText"] = "Become Lord of the Ring at the Ring of Blood in Nagrand . Progress: Two hundred gold... two hundred and fifty... That makes it about three fifty. Not bad! Oh, hey, what's shakin' champ?", ["rewardGold"] = 169800, ["rewardXP"] = 1200, ["rewardItems"] = { 32572, 114081, 114616, 114807, 122190, 122191 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84783, ["x"] = 0.568, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "group", ["startItems"] = { 122190 } },
[37992] = { ["id"] = 37992, ["name"] = "Gutrek's Cleaver: The Spirit Forge", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 37992 }, ["series"] = { 37788, 37797, 37798, 37799, 37811 }, ["description"] = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver . Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled. The journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", ["objectivesText"] = "Locate the Spirit Forge in Earthshaker Gorge and reforge Gutrek's Cleaver . Progress: Dis be da blade dat Jones was lookin for?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 120989, 120998, 121814, 121822 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37993] = { ["id"] = 37993, ["name"] = "Amulet of Rukhmar: The Apexis Device", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["requiredClasses"] = { 3, 9, 11 }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37993 }, ["series"] = { 37848, 37849, 37850, 37851, 37852 }, ["description"] = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. The Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", ["objectivesText"] = "Activate the Apexis device and claim the Amulet of Rukhmar . Progress: Ya manage ta get da amulet?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 118711, 121819, 121820, 121823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37994] = { ["id"] = 37994, ["name"] = "Dark Grimoire: Breaching the Barrier", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["requiredClasses"] = { 7, 9 }, ["requiredRaces"] = { 2, 9, 10 }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37994 }, ["series"] = { 37881, 37882, 37883, 37884, 37885 }, ["description"] = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier. There's only one way to find out...", ["objectivesText"] = "Destroy the ancient barrier below Socrethar's Rise and claim the Grimoire of the Nameless Void . Progress: I can sense a bad voodoo comin from ya, mon. Dat be da book I'm feelin?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 104299, 109076, 118711, 119093, 121831, 121832, 121834, 121837, 127669 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37995] = { ["id"] = 37995, ["name"] = "Gronnsbane: The Blessing of Beasts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37995 }, ["series"] = { 37914, 37916, 37917, 37918, 37919 }, ["description"] = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads: \"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", ["objectivesText"] = "Defeat the ancient black rylak and douse Gronnsbane in its blood. Once empowered, return the weapon to Rokhan for your reward. Progress: You bring da spear from da Thunderlords?", ["rewardGold"] = 2552959, ["rewardXP"] = 1365, ["rewardItems"] = { 109131, 122096, 122098, 122099, 122101, 122103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37996] = { ["id"] = 37996, ["name"] = "The Silent Skull: Taking from the Taker", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 37996 }, ["description"] = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. Once the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker. His mask should bring a hefty reward.", ["objectivesText"] = "Use the Laughing Skull elixir to find Skulltaker and claim the Silent Skull . Progress: Dat must be da cursed skull you got dere.", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 122150 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[37997] = { ["id"] = 37997, ["name"] = "Dream of Argus: The Crystal Reborn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37997 }, ["series"] = { 37973, 37976, 37977, 37978, 37979 }, ["description"] = "With the shards recovered, it is now possible to restore the Dream of Argus . You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", ["objectivesText"] = "Locate the crystal reconstruction device and use it to restore the Dream of Argus . Progress: You get da crystal put back togetha?", ["rewardGold"] = 3017576, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 122154, 122160, 122161, 122162, 122189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[38001] = { ["id"] = 38001, ["name"] = "Commander in the Field!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38001 }, ["series"] = { 38577 }, ["description"] = "We have been stopped by these new fel orcs, but we will ultimately prevail. Draka and I did manage to get a full scouting group out into the jungle to gather what else we will have to deal with. You should seek them out, gain a full understanding of what we face here.", ["objectivesText"] = "Get reports from various scouts in Tanaan Jungle .", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90553, ["x"] = 0.096, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.096, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[38008] = { ["id"] = 38008, ["name"] = "The Road of Glory", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 38008 }, ["description"] = "The Horde intends to force us out of Ashran , <name>. We can't let them succeed. March into the Road of Glory and thin their ranks by at least five.", ["objectivesText"] = "Chris Clarkie in Stormshield wants you to kill 5 members of the Horde within the Road of Glory.", ["rewardGold"] = 154000, ["rewardXP"] = 100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
