[38175] = { ["id"] = 38175, ["name"] = "Scrap Meltdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 38175 }, ["description"] = "We've had a breakthrough in melting down the scraps you've been collecting! If you can get me a small pile of 'em, we can get your troops something a bit more useful.", ["objectivesText"] = "Kristen Stoneforge wants you to collect 25 Iron Horde Scraps . Progress: Do you have the scraps I've asked for?", ["rewardXP"] = 1415, ["rewardItems"] = { 113681, 120301, 120302 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[38176] = { ["id"] = 38176, ["name"] = "Missive: Assault on Stonefury Cliffs", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38176 }, ["description"] = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines. Shadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", ["objectivesText"] = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge. Progress: Da assault be goin' well I hope?", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122405 } },
[38177] = { ["id"] = 38177, ["name"] = "Missive: Assault on Magnarok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38177 }, ["description"] = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", ["objectivesText"] = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122403 } },
[38178] = { ["id"] = 38178, ["name"] = "Missive: Assault on the Iron Siegeworks", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38178 }, ["description"] = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", ["objectivesText"] = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122402 } },
[38179] = { ["id"] = 38179, ["name"] = "Missive: Assault on the Everbloom Wilds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38179 }, ["description"] = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Rokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.", ["objectivesText"] = "Assault the Botani forces in the Everbloom Wilds in Gorgrond.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122400 } },
[38180] = { ["id"] = 38180, ["name"] = "Missive: Assault on the Broken Precipice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38180 }, ["description"] = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", ["objectivesText"] = "Assault the ogron forces at the Broken Precipice in Nagrand.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122424 } },
[38181] = { ["id"] = 38181, ["name"] = "Missive: Assault on Mok'gol Watchpost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38181 }, ["description"] = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", ["objectivesText"] = "Assault the Warsong force at Mok'gol Watchpost in Nagrand.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122421 } },
[38182] = { ["id"] = 38182, ["name"] = "Missive: Assault on Darktide Roost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38182 }, ["description"] = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.", ["objectivesText"] = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122418 } },
[38183] = { ["id"] = 38183, ["name"] = "Missive: Assault on Socrethar's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38183 }, ["description"] = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrethar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.", ["objectivesText"] = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 251329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122416 } },
[38184] = { ["id"] = 38184, ["name"] = "Missive: Assault on Lost Veil Anzu", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38184 }, ["description"] = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu. Rokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", ["objectivesText"] = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122413 } },
[38185] = { ["id"] = 38185, ["name"] = "Missive: Assault on Pillars of Fate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38185 }, ["description"] = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak. Rokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.", ["objectivesText"] = "Assault the Shadowmoon forces at Pillars of Fate in Shadowmoon Valley.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122411 } },
[38186] = { ["id"] = 38186, ["name"] = "Missive: Assault on Skettis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38186 }, ["description"] = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads. Guards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", ["objectivesText"] = "Assault the arakkoa forces at Skettis in Spires of Arak.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122408 } },
[38187] = { ["id"] = 38187, ["name"] = "Missive: Assault on Shattrath Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38187 }, ["description"] = "Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar. The Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.", ["objectivesText"] = "Assault the Sargerei forces at Shattrath City in Talador.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 241043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 122412 } },
[38188] = { ["id"] = 38188, ["name"] = "Scrap Meltdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38188 }, ["description"] = "We've figured out how to make those scraps in to something a bit more useful to your troops. Bring me a pile of them and I'll have our smiths process it for you.", ["objectivesText"] = "Grun'lek wants you to collect 25 Iron Horde Scraps . Progress: Do you have the scraps I've asked for?", ["rewardXP"] = 1415, ["rewardItems"] = { 113681, 114128, 114129, 114131, 120301, 120302 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[38189] = { ["id"] = 38189, ["name"] = "Missive: Assault on Stonefury Cliffs", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38189 }, ["description"] = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines. Bodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", ["objectivesText"] = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122401 } },
[38190] = { ["id"] = 38190, ["name"] = "Missive: Assault on Magnarok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38190 }, ["description"] = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", ["objectivesText"] = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122399 } },
[38191] = { ["id"] = 38191, ["name"] = "Missive: Assault on the Iron Siegeworks", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38191 }, ["description"] = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", ["objectivesText"] = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122406 } },
[38192] = { ["id"] = 38192, ["name"] = "Missive: Assault on the Everbloom Wilds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38192 }, ["description"] = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Bodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.", ["objectivesText"] = "Assault the botani forces in the Everbloom Wilds of Gorgrond.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122404 } },
[38193] = { ["id"] = 38193, ["name"] = "Missive: Assault on the Broken Precipice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38193 }, ["description"] = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", ["objectivesText"] = "Assault the ogron forces at the Broken Precipice in Nagrand.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122423 } },
[38194] = { ["id"] = 38194, ["name"] = "Missive: Assault on the Gorian Proving Grounds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 38194 }, ["description"] = "The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.", ["objectivesText"] = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 122190 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 122420 } },
[38195] = { ["id"] = 38195, ["name"] = "Missive: Assault on Mok'gol Watchpost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38195 }, ["description"] = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", ["objectivesText"] = "Assault the Warsong forces at Mok'gol Watchpost in Nagrand.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122422 } },
[38196] = { ["id"] = 38196, ["name"] = "Missive: Assault on Darktide Roost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38196 }, ["description"] = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.", ["objectivesText"] = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 122417 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122417 } },
[38197] = { ["id"] = 38197, ["name"] = "Missive: Assault on Socrethar's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38197 }, ["description"] = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.", ["objectivesText"] = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 122415, 251329 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122415 } },
[38198] = { ["id"] = 38198, ["name"] = "Missive: Assault on Lost Veil Anzu", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38198 }, ["description"] = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu. Bodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", ["objectivesText"] = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122414 } },
[38199] = { ["id"] = 38199, ["name"] = "Missive: Assault on Pillars of Fate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38199 }, ["description"] = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak. Bodrick Grey is concerned at their proximity to the garrison, and has put out a request that we thin their forces as soon as possible.", ["objectivesText"] = "Assault the Shadowmoon orcs at Pillars of Fate in Shadowmoon Valley.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122409 } },
[38200] = { ["id"] = 38200, ["name"] = "Missive: Assault on Skettis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38200 }, ["description"] = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads. Guards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", ["objectivesText"] = "Assault the Adherents of Rukhmar at Skettis in Spires of Arak.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122407 } },
[38201] = { ["id"] = 38201, ["name"] = "Missive: Assault on Shattrath Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38201 }, ["description"] = "Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar. Members of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.", ["objectivesText"] = "Assault the Sargerei forces at Shattrath City in Talador.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 241043 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 122410 } },
[38202] = { ["id"] = 38202, ["name"] = "Missive: Assault on the Gorian Proving Grounds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 38202 }, ["description"] = "The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.", ["objectivesText"] = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 122190 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 122419 } },
[38213] = { ["id"] = 38213, ["name"] = "Get a Clue", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37687, 38213, 38223, 38267 }, ["description"] = "Aktar mentioned that in the ruins he's seen Sethekk, ogres, even demons, but no sign of Iskar. We're going to have to go in there if we're to find any clues and I'd prefer someone strong like yourself to lead the way. Well, what do you say?", ["objectivesText"] = "Search the Ruins of Kra'nak for clues. Progress: The binding is dirty yet the pages are still in good condition. Upon the bottom of the binding is written \"Property of Iskar.\"", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 122463, 124557 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91291, ["x"] = 0.258, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 123, ["name"] = "The Search for Iskar", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 125, ["name"] = "The Search for Iskar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38223] = { ["id"] = 38223, ["name"] = "Dark Ascension", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37687, 38213, 38223, 38267 }, ["description"] = "You skim through the pages of the tome, most of them filled with notes on the nature of shadow and illusion. On the last pages you discover a journal: I continue to search for a cure to the curse of Sethe. If Terokk was restored I would not be in this situation. Damn Reshad ! I was contacted by an orc that identified himself as Gul'dan. He has a cure for the curse! I must travel to Tanaan to search for the location of this \"cipher\" of his. Take this information to Reshad .", ["objectivesText"] = "Speak to Reshad in the Ruins of Kra'nak. Progress: I wish it had not come to this...", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 122429, 122463, 124557 }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 89400, ["x"] = 0.16, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.16, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 123, ["name"] = "The Search for Iskar", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 125, ["name"] = "The Search for Iskar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38241] = { ["id"] = 38241, ["name"] = "Unearthed Magic", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 38241 }, ["description"] = "Commander, I've heard reports of a strange stone found in the garrison mine. The miners aren't sure what to make of it, but I have a feeling it could be useful. When you next find yourself at the mine, it may be worth investigating. And if you don't mind, I would love to see the stone for myself.", ["objectivesText"] = "Find the Strange Stone near your garrison mine. Progress: Greetings sir. Have you found the stone?", ["rewardXP"] = 3595, ["rewardItems"] = { 122457, 122458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[38242] = { ["id"] = 38242, ["name"] = "Unearthed Magic", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 38242 }, ["description"] = "Commander, da miners be findin' somethin' in our mine with strong mojo. They don' be knowin' what ta do with it, so maybe you gonna go overe dere and check it out? If you find it, bring it here so I can look closer at da magic.", ["objectivesText"] = "Find the Strange Stone near your garrison mine. Progress: Where be the stone?", ["rewardXP"] = 3595, ["rewardItems"] = { 122457, 122467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[38243] = { ["id"] = 38243, ["name"] = "A Bit of Ore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 38243 }, ["objectivesText"] = "Progress: Ore has been in high demand on my trading route, and I'm trying to restock my supply. Would you be willing to trade?", ["rewardItems"] = { 109118, 109119, 120945 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[38250] = { ["id"] = 38250, ["name"] = "Assault on the Ruins of Kra'nak", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38250 }, ["description"] = "The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic. We must strike at them before they can master their diabolic powers.", ["objectivesText"] = "Assault the Shadow Council forces at the Ruins of Kra'nak in Tanaan Jungle .", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[38252] = { ["id"] = 38252, ["name"] = "Assault on the Ruins of Kra'nak", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38252 }, ["description"] = "The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic. We must strike at them before they can master their diabolic powers.", ["objectivesText"] = "Assault the Shadow Council forces at the Ruins of Kra'nak in Tanaan Jungle . Progress: How goes the attack, sir?", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[38253] = { ["id"] = 38253, ["name"] = "Garrison Campaign: War Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38254, 38255, 38256, 38257, 38258, 38259, 40418 }, ["description"] = "Your garrison is in an uproar. King Varian Wrynn himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle. The King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", ["objectivesText"] = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 110560, 123867 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38254] = { ["id"] = 38254, ["name"] = "Derailment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38255, 38256, 38257, 38258, 38259, 40418 }, ["description"] = "Several orcs have spoken out since Gul'dan assumed control. Some were taken prisoner. Among them is an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" He designed these docks as well as the great dreadnaughts of the orcish fleet. If my scouts are right, he's in that prison train as we speak... And he may be ready to defect! Gather explosives and meet with Yrel at the train to the southeast!", ["objectivesText"] = "Collect Explosive Charges and a Detonator . Progress: Commander, it's you! Naielle promised she would send someone.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 122515, 122516, 123867 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 90180, ["x"] = 0.525, ["y"] = 0.098 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 90177, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.098 }, ["mapCandidates"] = { ["npc"] = { 539, 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38255] = { ["id"] = 38255, ["name"] = "The Train Gang", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38256, 38257, 38258, 38259, 40418 }, ["description"] = "These rangari will surround and cover the train car. Hit the detonator to blow open the doors. I will try to talk Roark into joining our cause. He's a genius around a drydock and our best hope for building a shipyard. If it doesn't work, we must be prepared to kill him. The last thing we need is someone rebuilding another Iron Fleet...", ["objectivesText"] = "Use the detonator to blow open the prison train, and convince Roark to join your cause.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 90177, ["x"] = 0.276, ["y"] = 0.102 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 91242, ["x"] = 0.275, ["y"] = 0.112 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38256] = { ["id"] = 38256, ["name"] = "Hook, Line, and... Sink Him!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38257, 38258, 38259, 40418 }, ["description"] = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place. But I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar. <Roark spits.> Gul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", ["objectivesText"] = "Use a Blackrock Grapple to reach Knar's bunker. Slay him to obtain Roark's Shipyard Blueprints . Progress: I will rebuild.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38257] = { ["id"] = 38257, ["name"] = "We Need a Shipwright", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38256, 38258, 38259, 40418 }, ["description"] = "The Iron Horde - or whatever Gul'dan is turning them into - has fallen back and fortified the entrance to Tanaan. A direct assault will take a heavy toll. However, the sea lanes are open. If we attack by both land and sea, Gul'dan's Horde will have no quarter. <name>, it's time to build a shipyard! We'll need to source local resources. Travel to the Iron Docks, where a small Alliance reclamation force is already waiting. Gather what equipment you can, and find us a shipwright capable of building a fleet!", ["objectivesText"] = "Travel to the Iron Docks and speak with Exarch Naielle . Your Garrison Flight Master can provide transport.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 90180, ["x"] = 0.525, ["y"] = 0.098 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539, 543 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38258] = { ["id"] = 38258, ["name"] = "Nothing Remains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38256, 38257, 38259, 40418 }, ["description"] = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people. You and your allies from Shattrath still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor! Let your people know I am coming.", ["objectivesText"] = "Report back to King Wrynn at the Town Hall in your garrison.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38259] = { ["id"] = 38259, ["name"] = "All Hands on Deck", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38256, 38257, 38258, 40418 }, ["description"] = "Let's put this \"Iron Shipwright\" of yours to work, commander. If we're to pull off your plan to assault Tanaan from both land and sea, we'll need to get some docks operational as soon as possible. Work with Roark and build the Alliance a shipyard! Last I saw, Roark was northwest of the garrison, near Eventide Landing.", ["objectivesText"] = "Gather materials and construct a Level 1 Shipyard for your garrison. Progress: I'll need building materials, commander. You can't build docks from mud.", ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 119093, 123867 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38267] = { ["id"] = 38267, ["name"] = "Friends Above", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37687, 38213, 38223, 38267 }, ["series"] = { 37687 }, ["description"] = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak. I've asked a friend to set up a camp nearby. I say we head there to continue our search.", ["objectivesText"] = "Meet with Reshad at Atkar's Post.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 122463, 124557 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91290, ["x"] = 0.575, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91291, ["x"] = 0.258, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 123, ["name"] = "The Search for Iskar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38269] = { ["id"] = 38269, ["name"] = "Friends Above", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37688, 38213, 38223, 38269 }, ["description"] = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak. I've asked a friend to set up a camp nearby. I say we head there to continue our search.", ["objectivesText"] = "Meet with Reshad at Atkar's Post.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 122463, 124557 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91292, ["x"] = 0.605, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91291, ["x"] = 0.258, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 125, ["name"] = "The Search for Iskar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38270] = { ["id"] = 38270, ["name"] = "Finding the Killer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["series"] = { 38453, 38560 }, ["description"] = "With this map, you have pinpointed the origin of the attacks. It is time to see who or what is behind the attacks, and if they are a possible ally.", ["objectivesText"] = "Locate the slayer of Bleeding Hollow near Zeth'Gol. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 123852, 124553, 127709 }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91299, ["x"] = 0.27, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 123852 } },
[38271] = { ["id"] = 38271, ["name"] = "Following the Bloody Path", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["description"] = "The ones I kill... they speak of a cave. Sacred to the Bleeding Hollow. Kilrogg could be there - I am going.", ["objectivesText"] = "Follow Ariok to the cave.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 124553, 127709 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91299, ["x"] = 0.27, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91351, ["x"] = 0.324667, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38272] = { ["id"] = 38272, ["name"] = "The Bleeding Hollow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["description"] = "The cave pulls me. It keeps angry spirits near. Kilrogg has done magic here. You help me understand...", ["objectivesText"] = "Reach the bottom of the Bleeding Hollow.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 25628, 25629, 25630, 122574, 122575, 123852, 124553, 127709 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91351, ["x"] = 0.324667, ["y"] = 0.374667 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91324, ["x"] = 0.334, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.324667, ["y"] = 0.374667 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38273] = { ["id"] = 38273, ["name"] = "Spirits of the Bleeding Hollow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["storyline"] = { 38273 }, ["description"] = "It is clear the cave is protected by powerful ghosts, ancestors of the Bleeding Hollow. Whatever is down there, it will be easier to deal with if many of the spirits were dealt with first.", ["objectivesText"] = "Slay 6 Enraged Blood Spirits .", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 124553, 127669, 127709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[38274] = { ["id"] = 38274, ["name"] = "The Eye of Kilrogg", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["description"] = "If you wish to know what Kilrogg and his new master intend, you will need his eye. After the ritual all chieftains place their eye under the protection of the ghosts of the Bleeding Hollow in the next chamber. Go and locate the Eye of Kilrogg in the vault. The other chieftains will not stand with us, and will fight you for it. Then place it on the ritual mark nearby to get your answers.", ["objectivesText"] = "Find the Eye of Kilrogg and perform the scrying ritual. Progress: What have you learned?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 124553, 127709 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91324, ["x"] = 0.334, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92317, ["x"] = 0.328, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 4, ["flags"] = 0 } } },
