[38356] = { ["id"] = 38356, ["name"] = "Bringing the Bass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 38356 }, ["description"] = "It's a bit quiet around here, in between the invasions and all. You're in luck though, Commander! I can fix that, and boost morale among your troops all at the same time. All you need to do is bring me a few items from around Draenor, and I'll fill your garrison with music. I'll even throw in a few music rolls from my own collection to get you started! What do you say?", ["objectivesText"] = "Collect a Bass Blaster , Laz-Tron Disc Reader , Phonic Amplifier , S.P.R.K. Capacitor , and a Cord of Ancient Wood . Progress: Collect a Bass Blaster , Laz-Tron Disc Reader , Phonic Amplifier , S.P.R.K. Capacitor , and a Cord of Ancient Wood .", ["rewardItems"] = { 110560, 122201, 122203, 122205, 122206, 122208, 122209, 122210, 122212, 122213, 122216, 122217, 122218, 122219, 122565, 122566, 122567, 122568, 122569, 122613 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
