[38585] = { ["id"] = 38585, ["name"] = "Assault on the Throne of Kil'jaeden", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38585 }, ["description"] = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan. Gather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", ["objectivesText"] = "Defeat the Shadow Council at the Throne of Kil'jaeden in Tanaan Jungle .", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 123964 }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
