[38587] = { ["id"] = 38587, ["name"] = "Assault on the Throne of Kil'jaeden", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["storyline"] = { 38587 }, ["description"] = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Remember the first war, we know the destruction the legion can cause if they are unchecked. Head to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", ["objectivesText"] = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Shadow Council Forces Thwarted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } } },
