[38932] = { ["id"] = 38932, ["name"] = "Equipment Blueprint: Bilge Pump", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38932 }, ["description"] = "This appears to be a blueprint for some sort of naval equipment. We should take it back to our Shipyard and see if someone can decipher it.", ["objectivesText"] = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard. Progress: Those look like some equipment blueprints!", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 125787, 126950, 126951, 128256, 128264, 128265 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 }, { ["mapID"] = 525, ["npcID"] = 94801, ["x"] = 0.4, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 126950 } },
[38934] = { ["id"] = 38934, ["name"] = "Silas' Secret Stash", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 38934 }, ["description"] = "A great Darkmoon prize do you now seek, but be ye warned, it is not for the meek. Your very first clue to send you on this caper, you will find printed on the back of this paper.", ["objectivesText"] = "Find Silas' Secret Stash .", ["rewardGold"] = 1024800, ["rewardXP"] = 300, ["rewardItems"] = { 109076, 122238, 124669, 124670, 124671, 124674, 126925, 126926, 126927, 126928, 126929, 126930, 126931, 127141, 127143, 127144, 127145, 127146, 127147, 127148 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 126930 } },
[38935] = { ["id"] = 38935, ["name"] = "His Name Was... Stormstout", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 38935 }, ["series"] = { 29907, 29908, 29909, 29911, 29912, 29940, 32018, 32019, 49539, 49557 }, ["description"] = "The land is ripe with rumors of an unusual pandaren monk whose power was matched only for his appetite for brew. He was traveling with his young niece who's mouth seems to get them into a lot of trouble. The locals say these two were headed to the Valley of the Four Winds . You should meet him! Just... watch out for that right hook.", ["objectivesText"] = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 56133, ["x"] = 0.6065, ["y"] = 0.46575 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.6065, ["y"] = 0.46575 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[38936] = { ["id"] = 38936, ["name"] = "The Road to Kun-Lai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 38936 }, ["series"] = { 30457, 31254, 31255, 49541, 49559 }, ["description"] = "Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing. They need your help if they are to survive! To reach Kun-Lai Summit, travel to the Valley of the Four Winds and look for the Highroad Grummle that can be found at the base of the Veiled Stair along the northeastern border. They can guide you the rest of the way.", ["objectivesText"] = "Travel through the Veiled Stair to Binan Village.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 211279 }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 59073, ["x"] = 0.722, ["y"] = 0.918 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.918 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[38989] = { ["id"] = 38989, ["name"] = "Your Orders, General?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38989 }, ["description"] = "General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands. For the Horde!", ["objectivesText"] = "Go to the Tanaan Planning Map in Tanaan Jungle .", ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[39000] = { ["id"] = 39000, ["name"] = "We Don't Need No Library Card", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39000 }, ["series"] = { 39003, 39024 }, ["description"] = "If history is any indication, Gul'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves. As you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul'dan's lieutenants. They're dangerous, so don't read any of them. Not even the pictures. <Khadgar shudders.> ESPECIALLY the pictures.", ["objectivesText"] = "Collect 33 Tomes of Chaos from bosses in Hellfire Citadel. Progress: What about those books, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 71141, 127115 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[39003] = { ["id"] = 39003, ["name"] = "Cooking the Books", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39003 }, ["series"] = { 39000, 39024 }, ["description"] = "<name>, we've got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can't just burn them. Cordana will know what to do. Take these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.", ["objectivesText"] = "Deliver Gul'dan's Library of Chaos to Cordana at Zangarra and ensure they are destroyed. Progress: <Khadgar smiles.> So, how is Cordana doing? Is all well at my tower?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 119348 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39004] = { ["id"] = 39004, ["name"] = "Darkness Incarnate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39004 }, ["description"] = "We have one final task before us, <name>. We must defeat Gul'dan and unravel his plans for this world. I have no reward to offer you - I have given you everything I can. Come. When you and your allies are ready, we march on Hellfire Citadel... and end this.", ["objectivesText"] = "Hunt down and engage Gul'dan within the Hellfire Citadel. Progress: We must thwart Gul'dan!", ["rewardGold"] = 4647000, ["rewardItems"] = { 127785 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[39018] = { ["id"] = 39018, ["name"] = "Call of the Archmage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 39018 }, ["description"] = "Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.", ["objectivesText"] = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[39019] = { ["id"] = 39019, ["name"] = "Call of the Archmage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 39019 }, ["description"] = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", ["objectivesText"] = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[39020] = { ["id"] = 39020, ["name"] = "A Burning Path Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = true, ["event"] = "Outland Timewalking Dungeon Event", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39020 }, ["description"] = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Follow the blazing star, and walk the paths it reveals.", ["rewardItems"] = { 22921, 23572, 32092, 33844, 33857, 35348, 86574, 122338, 122339, 122340, 122341, 127853, 129747, 129922, 129923, 129926, 129929, 129938, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129965, 133511, 133542, 133543, 164258, 226193, 226194, 247820 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39021] = { ["id"] = 39021, ["name"] = "A Frozen Path Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = true, ["event"] = "Northrend Timewalking Dungeon Event", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39021 }, ["description"] = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Follow the chill star, and walk the paths it reveals.", ["rewardItems"] = { 43102, 44113, 44151, 46007, 122338, 122339, 122340, 122341, 127853, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129946, 129952, 129954, 129955, 129965, 133511, 133542, 133543, 226193, 226194, 247820, 247821 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39022] = { ["id"] = 39022, ["name"] = "Call of the Archmage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 39022 }, ["series"] = { 35997, 35998, 36004, 36005, 36006 }, ["description"] = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", ["objectivesText"] = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[39023] = { ["id"] = 39023, ["name"] = "Call of the Archmage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 39023 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 40501 }, ["description"] = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp. This will not take long.", ["objectivesText"] = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
