[39033] = { ["id"] = 39033, ["name"] = "The Time to Strike", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39033 }, ["description"] = "This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.", ["objectivesText"] = "Complete 5 Objectives in Apexis-yielding areas. Progress: Ah, the unmistakable hum of crystals when the Apexis star shines....", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39034] = { ["id"] = 39034, ["name"] = "Emissary of War", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39034 }, ["description"] = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture deep into caverns and strongholds to prove your worth.", ["objectivesText"] = "Complete 4 dungeons on Mythic difficulty. Progress: Be bold, <name>, and you may win many friends on this day.", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 127854, 226194, 234731, 247820, 250117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39040] = { ["id"] = 39040, ["name"] = "A Call to Battle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["event"] = "Battleground Bonus Event", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39040 }, ["description"] = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", ["objectivesText"] = "Win 4 Battleground matches.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 137642, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39041] = { ["id"] = 39041, ["name"] = "The Arena Calls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39041 }, ["objectivesText"] = "Win 10 Arena Skirmish battles.", ["rewardItems"] = { 138474, 141071, 141889 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39042] = { ["id"] = 39042, ["name"] = "The Very Best", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["event"] = "Pet Battle Bonus Event", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39042 }, ["description"] = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets.", ["rewardItems"] = { 92738, 98112, 98114, 122457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39054] = { ["id"] = 39054, ["name"] = "Shipbuilding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38435, 38436, 38444, 38445, 39055, 39082, 39276 }, ["description"] = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, <class>, and then destroy the evidence. Let me know when you are done.", ["objectivesText"] = "Learn the blueprints and destroy the evidence. Progress: You memorize those blueprints yet?", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39055] = { ["id"] = 39055, ["name"] = "Ship Shape", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38435, 38436, 38444, 38445, 39054, 39082, 39276 }, ["description"] = "Now that we have the blueprints, let's get started on our first ship, a transport! Speak to me when you are ready to begin construction.", ["objectivesText"] = "Speak with Yanas to begin construction on a transport ship. Once complete, add it to your collection of ships. Progress: Get that ship started yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 95002, ["x"] = 0.298, ["y"] = 0.106 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 95002, ["x"] = 0.298, ["y"] = 0.106 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.106 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39056] = { ["id"] = 39056, ["name"] = "Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39404, 39655, 39674, 39675, 39676 }, ["description"] = "We have come a long way in a short time on this shipyard, <name>. Now it's time to run our first naval mission and control the seas of Draenor! I will need to setup shop from a high vantage point to plan out these seafaring missions. Meet me near the shipyard entrance and we can get started.", ["objectivesText"] = "Find Merreck Vonder in your Shipyard and complete a Naval Mission. Progress: Finish a naval mission yet?", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260, 128353, 128373 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39057] = { ["id"] = 39057, ["name"] = "Command of the Seas", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39057 }, ["series"] = { 39697 }, ["description"] = "Gul'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we're going to need more than just a couple of transport ships. We must build an arsenal. We need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!", ["objectivesText"] = "Upgrade to a Level 2 shipyard.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39058] = { ["id"] = 39058, ["name"] = "Critters of Draenor", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 39058 }, ["description"] = "I love collecting pets, and I've picked up a few unusual pets here in Draenor. What would you say to a battle? If you can defeat my humble team, I think we'll both learn a few new tricks.", ["objectivesText"] = "Defeat Erris the Collector in a pet battle.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 116429, 122535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39067] = { ["id"] = 39067, ["name"] = "Upgrading The Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39068 }, ["description"] = "You have been doing a great job out there commander. However, we are going to need more experience and resources to upgrade this shipyard. Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", ["objectivesText"] = "Collect 1000 garrison resources , 1000 gold and complete 15 naval missions. Progress: Finding success on these new naval missions?", ["rewardXP"] = 685, ["rewardItems"] = { 127270 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 16, ["flags"] = 0 } } },
[39068] = { ["id"] = 39068, ["name"] = "Naval Domination", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39067 }, ["description"] = "Our naval domination continues! However, we are going to need even more experience and resources to take this shipyard to the next level. Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", ["objectivesText"] = "Collect 2500 garrison resources , 2500 gold and complete 25 naval treasure missions. Progress: Gather those resources yet? I am ready to get this upgrade started!", ["rewardXP"] = 685, ["rewardItems"] = { 127267, 128391 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 17, ["flags"] = 0 } } },
[39082] = { ["id"] = 39082, ["name"] = "Let's Get To Work", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38435, 38436, 38444, 38445, 39054, 39055, 39276 }, ["description"] = "Now that the shipyard is complete, we need to get busy making ships! Solog ran off to the dry docks, why don't you meet him down there? He said he had a plan.", ["objectivesText"] = "Meet Solog at the dry docks.", ["rewardGold"] = 5865, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 }, { ["mapID"] = 539, ["npcID"] = 97085, ["x"] = 0.282, ["y"] = 0.106 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39107] = { ["id"] = 39107, ["name"] = "An Even Bigga Score", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 39107 }, ["description"] = "So these mooks in Tanaan, they be carryin' all manner of valuable treasures. It still be complicated, but I can give ya a lot more now!", ["objectivesText"] = "Obtain Dingy Iron Coins for Griftah . Progress: So you've got every last one?", ["rewardGold"] = 27360392, ["rewardItems"] = { 112995, 112996, 112997, 112998, 112999, 113000, 113001, 113002, 113003, 113004, 113005, 113006, 113007, 113008, 127398, 127400, 127402, 127404, 127406, 127407, 127409 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39127] = { ["id"] = 39127, ["name"] = "Beyond the Wall", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 39127 }, ["series"] = { 30814, 31695, 49542, 49560 }, ["description"] = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes . It sounds like they are going after the root of the yaungol invasion. The pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", ["objectivesText"] = "Speak with Taran Zhu at the Longying Outpost in Townlong Steppes .", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["rewardItems"] = { 211279 }, ["ends"] = { { ["mapID"] = 388, ["npcID"] = 60688, ["x"] = 0.712, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 388, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 388 }, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[39129] = { ["id"] = 39129, ["name"] = "Ill Tempered", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 39129 }, ["description"] = "<Prying the lid off the scroll case reveals a plan by the Iron Horde to use large fish in the oceans around Draenor to interfere with Alliance and Horde naval power. Incredibly, the plan seems to have already worked on smaller sharks, but only up to a point.>", ["objectivesText"] = "Take the Shark Brainwashing Plans to your garrison shipwright. Provided item:", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 127663, 127682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 127682 } },
[39147] = { ["id"] = 39147, ["name"] = "6.2 Tanaan - PTR - Unlock Tanaan Debug", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 39147 }, ["rewardGold"] = 616000, ["rewardXP"] = 50, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39175] = { ["id"] = 39175, ["name"] = "Gems of the Apexis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 39175 }, ["series"] = { 39176, 39177, 39195 }, ["description"] = "Listen, boss. I know you're a jewelcrafter. It's OK, I totally understand - I like money, too! I heard some of them bird fellas talking about some new gem-cuttin' device they got up in Tanaan. I'd be interested in checkin' it out myself, but I've got this whole shipyard mess to deal with right now.", ["objectivesText"] = "Find Sun-Sage Chakkis in Tanaan Jungle.", ["rewardGold"] = 5865, ["rewardXP"] = 685, ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39176] = { ["id"] = 39176, ["name"] = "Mastery Of Taladite", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39176 }, ["series"] = { 39175, 39177, 39195 }, ["description"] = "You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes. I've been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak. What I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.", ["objectivesText"] = "Find the Apexis Gemcutting Construct.", ["rewardXP"] = 1365, ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94605, ["x"] = 0.258, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39177] = { ["id"] = 39177, ["name"] = "Ruined Construct", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39177 }, ["series"] = { 39175, 39176, 39195 }, ["description"] = "<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.> <A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>", ["objectivesText"] = "Repair the Apexis Gemcutter Construct by inserting 1000 Apexis Crystals.", ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 94605, ["x"] = 0.258, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39180] = { ["id"] = 39180, ["name"] = "Warchief's Command: Zangarmarsh!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 9716, 9718, 9720, 39181 }, ["description"] = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition. Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body. The expedition's leader, Ysiel Windsinger , has asked us to direct volunteers to her outpost. Report to her at the Cenarion Refuge in eastern Zangarmarsh . Take the main path to the west and it will lead you directly there.", ["objectivesText"] = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh .", ["rewardGold"] = 200, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17841, ["x"] = 0.784, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 102, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 3, ["flags"] = 0 } } },
