[39195] = { ["id"] = 39195, ["name"] = "Gems of the Apexis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 534, ["storyline"] = { 39195 }, ["series"] = { 39175, 39176, 39177 }, ["description"] = "Commander! I've noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable. I overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named \"Chakkis.\" Just thought you might be interested.", ["objectivesText"] = "Find Sun-Sage Chakkis in Tanaan Jungle.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39196] = { ["id"] = 39196, ["name"] = "Warchief's Command: Nagrand!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["description"] = "The Warchief has asked for any able bodied champions of the Horde to ride to the aid of Garadar. The home of the Mag'har, lies to the south, in Nagrand . Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake. Report to Captain Kroghan there and offer him what assistance you can. Garadar must not fall!", ["objectivesText"] = "Speak with Captain Kroghan at Garadar in Nagrand .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18090, ["x"] = 0.554, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39197] = { ["id"] = 39197, ["name"] = "Hero's Call: Nagrand!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["series"] = { 10476 }, ["description"] = "The King has requested you represent him with the Kurenai settlement of Telaar in Nagrand . Seek out Warden Moi'bff Jill upon arrival.", ["objectivesText"] = "Speak with Warden Moi'bff Jill at Telaar in Nagrand on Outland.", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18408, ["x"] = 0.548, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39198] = { ["id"] = 39198, ["name"] = "Warchief's Command: Blade's Edge Mountains!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3522, ["mapID"] = 105, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 10486, 10487, 10488 }, ["description"] = "The Warchief is calling for champions to put an end to the ogre threat in Blade's Edge Mountains . Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Gor'drek know of our plight. Any help he can spare would be most welcome.", ["objectivesText"] = "Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Gor'drek .", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 105, ["npcID"] = 18248, ["x"] = 0.518, ["y"] = 0.578 }, { ["mapID"] = 105, ["npcID"] = 21117, ["x"] = 0.522, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 105, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 105 }, ["zone"] = { 3522 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 105, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39199] = { ["id"] = 39199, ["name"] = "Hero's Call: Blade's Edge Mountains!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3522, ["mapID"] = 105, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["series"] = { 10455, 10456, 10457, 10506 }, ["description"] = "The Alliance forces of Sylvanaar in the Blade's Edge Mountains require reinforcements. The King has asked for any able bodied members of the Alliance to journey to the mountains along the northern border of Zangarmarsh.", ["objectivesText"] = "Speak with Rina Moonspring at Sylvanaar in the Blade's Edge Mountains .", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 105, ["npcID"] = 18098, ["x"] = 0.364, ["y"] = 0.6755 }, { ["mapID"] = 105, ["npcID"] = 21066, ["x"] = 0.362, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 105, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.6755 }, ["mapCandidates"] = { ["npc"] = { 105 }, ["zone"] = { 3522 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 105, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39201] = { ["id"] = 39201, ["name"] = "Warchief's Command: Netherstorm!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 10183, 10186, 11036, 11037, 11040, 11042, 39202 }, ["description"] = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours. The Warchief feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas. Area 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", ["objectivesText"] = "Report to Rocket-Chief Fuselage at Area 52.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 19570, ["x"] = 0.326, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 109, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39202] = { ["id"] = 39202, ["name"] = "Hero's Call: Netherstorm!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["series"] = { 10183, 10186, 11036, 11037, 11040, 11042, 39201 }, ["description"] = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours. The King feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas. Area 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", ["objectivesText"] = "Report to Rocket-Chief Fuselage at Area 52.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 19570, ["x"] = 0.326, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 109, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39203] = { ["id"] = 39203, ["name"] = "Warchief's Command: Dragonblight!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 11996, 11999, 12005 }, ["description"] = "The Warchief wishes to reinforce the Horde's presence at Agmar's Hammer in the Dragonblight . The fortress is a vital staging point for our assault on Icecrown and pivotal to containing the chaotic magic energies being released throughout the land. Report to Archmage Aethas Sunreaver.", ["objectivesText"] = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26471, ["x"] = 0.38, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39204] = { ["id"] = 39204, ["name"] = "Hero's Call: Dragonblight!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 11995, 12000, 12004, 12439, 12440 }, ["description"] = "Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart. Those skilled in fighting dragons and undead are greatly welcome. Those willing to answer the call should report to Archmage Modera at Stars' Rest in Dragonblight .", ["objectivesText"] = "Speak with the Image of Archmage Modera at Stars' Rest.", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26673, ["x"] = 0.29, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39206] = { ["id"] = 39206, ["name"] = "Warchief's Command: Grizzly Hills!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 12257, 12468, 12487, 12488 }, ["description"] = "We've received a request for help from our base in the Grizzly Hills . Go to see Conqueror Krenna . She's attempting to secure all of the natural resources. Just watch your back around her. The word is that she's aggressive even for an orc. You can reach her by traveling east from Dragonblight.", ["objectivesText"] = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26860, ["x"] = 0.206, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39207] = { ["id"] = 39207, ["name"] = "Hero's Call: Grizzly Hills!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 12292, 12293, 12294, 12295, 12511 }, ["description"] = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills . All in hopes of finding an alternate route into Icecrown. Lieutenant Dumont , stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", ["objectivesText"] = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26875, ["x"] = 0.318, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39208] = { ["id"] = 39208, ["name"] = "Zul'Drak", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 39208 }, ["series"] = { 12630, 12883, 12884, 12902, 49534, 49552 }, ["description"] = "Our death knight allies in Zul'Drak are in need of heroes to aid them in securing the troll lands from the Scourge. Those willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.", ["objectivesText"] = "Report to Stefan Vadu at Ebon Watch in Zul'Drak . Progress: What have you got there, <race>?", ["rewardGold"] = 5350, ["rewardXP"] = 690, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 28518, ["x"] = 0.232, ["y"] = 0.574667 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.232, ["y"] = 0.574667 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard" },
[39209] = { ["id"] = 39209, ["name"] = "Sholazar Basin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3711, ["mapID"] = 119, ["storyline"] = { 39209 }, ["series"] = { 12489, 12521, 39212, 49535, 49553 }, ["description"] = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin . His expedition has not been heard from since. Monte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either. Volunteers are needed to mount an expedition to find the missing expedition. Monte's flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin .", ["objectivesText"] = "Speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin .", ["rewardGold"] = 140450, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 119, ["npcID"] = 27987, ["x"] = 0.396, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 119, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 119 }, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[39210] = { ["id"] = 39210, ["name"] = "The Magical Kingdom of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 4395, ["storyline"] = { 39210 }, ["series"] = { 12790, 12791, 12794, 12796 }, ["description"] = "The Kirin Tor have moved their city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. They believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest. When you arrive, seek out Archmage Celindra .", ["objectivesText"] = "Report to Archmage Celindra at The Violet Gate in Dalaran .", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[39212] = { ["id"] = 39212, ["name"] = "Sholazar Basin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3711, ["mapID"] = 119, ["storyline"] = { 39212 }, ["series"] = { 12489, 12521, 39209, 49535, 49553 }, ["description"] = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin . His expedition has not been heard from since. Monte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either. Archmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot .", ["objectivesText"] = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin . When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin .", ["rewardGold"] = 140450, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 119, ["npcID"] = 27987, ["x"] = 0.396, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 119, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 119 }, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[39221] = { ["id"] = 39221, ["name"] = "Pits of Mannoroth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39221 }, ["description"] = "In the Hellfire Citadel , they work to corrupt a magnaron with fel energy within the Pits of Mannoroth. If you delve into the fel pools of that place, be on your guard.", ["objectivesText"] = "Defeat Kormrok in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39225] = { ["id"] = 39225, ["name"] = "Maw of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39225 }, ["description"] = "Falling into the heart of the mausoleum in Auchindoun, Teron'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. No longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", ["objectivesText"] = "Defeat Gorefiend in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 136350, 140618, 140619, 140620, 140621, 237812, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39228] = { ["id"] = 39228, ["name"] = "Temple of Tyranny", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39228 }, ["description"] = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her. Purge this Eredar of darkness.", ["objectivesText"] = "Defeat Tyrant Velhari in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39231] = { ["id"] = 39231, ["name"] = "Destructor's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39231 }, ["description"] = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we had predicted. Mannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", ["objectivesText"] = "Defeat Mannoroth in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39232] = { ["id"] = 39232, ["name"] = "The Black Gate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39232 }, ["description"] = "We have heard rumors that one of the strongest of the eredar could soon enter this world through the Black Gate. If these rumors are to be believed, it could even be Archimonde the Defiler. Should he arrive uncontested, Draenor itself is likely to fall.", ["objectivesText"] = "Defeat Archimonde in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39236] = { ["id"] = 39236, ["name"] = "Let's Get To Work", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39241, 39242 }, ["description"] = "Now that the shipyard is complete, we need to get busy making ships! Solog ran off to the dry docks, why don't you meet him down there? He said he had a plan.", ["objectivesText"] = "Meet Solog at the dry docks.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 }, { ["mapID"] = 525, ["npcID"] = 97096, ["x"] = 0.415, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39241] = { ["id"] = 39241, ["name"] = "Shipbuilding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39236, 39242 }, ["description"] = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, <class>, and then destroy the evidence. Let me know when you are done.", ["objectivesText"] = "Learn the blueprints and destroy the evidence. Progress: You memorize those blueprints yet?", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39242] = { ["id"] = 39242, ["name"] = "Ship Shape", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39236, 39241 }, ["description"] = "You want to take the fight to Gul'dan? You need a transport! Speak to me when you are ready to begin construction.", ["objectivesText"] = "Speak with Solog to begin construction on a transport ship. Once complete, add it to your collection of ships. Progress: Get that ship started yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39243] = { ["id"] = 39243, ["name"] = "Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39401 }, ["description"] = "You're a natural at this, <name>. You've got the salt in your veins. Now it's time to run our first naval mission and control the seas of Draenor! You will want a high vantage point to plan out these seafaring missions. I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.", ["objectivesText"] = "Find Rolash Wavechaser at your shipyard and complete a Naval Mission. Progress: Finish a naval mission yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 128373 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39245] = { ["id"] = 39245, ["name"] = "Upgrading The Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39246 }, ["description"] = "You have been doing a great job out there commander. However, we are going to need more experience and resources to upgrade this shipyard. Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", ["objectivesText"] = "Collect 1000 garrison resources , 1000 gold and combat 15 naval missions. Progress: Finding success on these new naval missions?", ["rewardXP"] = 685, ["rewardItems"] = { 127270 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 16, ["flags"] = 0 } } },
[39246] = { ["id"] = 39246, ["name"] = "Naval Domination", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39245 }, ["description"] = "Our naval domination continues! However, we are going to need even more experience and resources to take this shipyard to the next level. Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", ["objectivesText"] = "Collect 2500 garrison resources , 2500 gold and complete 25 naval treasure missions. Progress: Gather those resources yet? I am ready to get this upgrade started!", ["rewardXP"] = 685, ["rewardItems"] = { 127267 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 17, ["flags"] = 0 } } },
[39250] = { ["id"] = 39250, ["name"] = "Pits of Mannoroth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39250 }, ["description"] = "In the Hellfire Citadel , they're corruptin' a magnaron with fel energy in the Pits o' Mannoroth. If ye delve into the fel pools of that place, be on yer guard.", ["objectivesText"] = "Defeat Kormrok in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[39253] = { ["id"] = 39253, ["name"] = "Maw of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39253 }, ["description"] = "Falling into the heart o' the mausoleum in Auchindoun, Teron'gor gorged upon hundreds o' draenei souls, becoming a bloated abomination in the process. No longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", ["objectivesText"] = "Defeat Gorefiend in Hellfire Citadel . Progress: I hope you make Gorefiend pay for his atrocities.", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 136350, 140618, 140619, 140620, 140621, 237812, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[39256] = { ["id"] = 39256, ["name"] = "Temple of Tyranny", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39256 }, ["description"] = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her. Purge this Eredar of darkness.", ["objectivesText"] = "Defeat Tyrant Velhari in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
