[39401] = { ["id"] = 39401, ["name"] = "Destroying the Competition", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39243 }, ["description"] = "One battle does not win the war, Commander. That Transport isn't gonna hold up long against this Iron Horde navy. We are going to need another ship. Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers. We should construct one of these ships immediately!", ["objectivesText"] = "Construct a Destroyer in your Shipyard and send it on a naval mission. Progress: What is the status of the Destroyer?", ["rewardItems"] = { 126900, 127269 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39404] = { ["id"] = 39404, ["name"] = "Destroying the Competition", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39056, 39655, 39674, 39675, 39676 }, ["description"] = "One battle does not win the war, Commander. That Transport isn't gonna hold up long against this Iron Horde navy. We are going to need another ship. Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers. We should construct one of these ships immediately!", ["objectivesText"] = "Construct a Destroyer in your Shipyard and send it on a naval mission. Progress: What is the status of the Destroyer?", ["rewardItems"] = { 126900, 127882, 127884, 128260, 128492 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39422] = { ["id"] = 39422, ["name"] = "Shipyard Report", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39422 }, ["description"] = "Commander! We have received reports from the shipyard that things are getting serious. Can you head back to Lunarfall and check in with Merreck? Every ship we build gives us another advantage over Gul'dan's new Horde.", ["objectivesText"] = "Return to your shipyard in Lunarfall.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534, 539 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39423] = { ["id"] = 39423, ["name"] = "Shipyard Report", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 39423 }, ["description"] = "Commander! We have received reports from the shipyard that things are getting serious. Can you head back to Frostwall and check in with Rolosh? Every ship we build gives us another advantage over Gul'dan's new Horde.", ["objectivesText"] = "Return to your shipyard in Frostwall.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[39432] = { ["id"] = 39432, ["name"] = "Unknowable Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39432 }, ["description"] = "The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.", ["objectivesText"] = "Collect a Fel-Corrupted Apexis Fragment from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle . Progress: This is simply the beginning of what you must do to save what remains of the Arakkoa.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128346 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
[39433] = { ["id"] = 39433, ["name"] = "Unseen Influence", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39433 }, ["description"] = "The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.", ["objectivesText"] = "Collect 10 Fel-Corrupted Apexis Fragments from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle . Progress: I fear even your help may not be enough to avert the doom of the Arakkoa.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 93730, 119093, 124093, 124094, 124095, 124099, 128315, 128346, 128502, 128503 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
