[39509] = { ["id"] = 39509, ["name"] = "Bloodied Blades of Zeth'Gol", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39509 }, ["description"] = "Them Bleeding Hollow orcs do blood magic - like voodoo but it hurt more. They cut their own flesh. Most of 'em carry curved ritual blades for carvin' themselves up. Bring me them blades, commander. We can turn their power against 'em.", ["objectivesText"] = "Collect 25 Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth'Gol. Progress: Watch your back in Bleeding Hollow lands. They fight dirty. 'Course, we fight dirtier.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128428 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39510] = { ["id"] = 39510, ["name"] = "A Little Wetwork", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39510 }, ["description"] = "What be left of the Iron Horde is comin' to Tanaan through Ironhold Harbor. If we knew who was comin' and when, we could use our shipyard to cause some chaos. Go to Ironhold Harbor and fish up some intelligence!", ["objectivesText"] = "Collect 15 Iron Horde Naval Manifests from forces in Ironhold Harbor. Progress: Whatcha learn for us, commander?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128429 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39511] = { ["id"] = 39511, ["name"] = "Blood of Fallen Brothers", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39511 }, ["description"] = "Orcs that drink Gul'dan's poison turn into fel beasts. Soulless savages. Lady Liadrin an' the Blood Knights think maybe there be a way back. They be wantin' samples of blood from freshly turned orcs. Get their blood, <name>! You be findin' fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden is where you find the most.", ["objectivesText"] = "Collect 20 Vials of Fel Blood from fel orcs throughout Tanaan Jungle . Progress: You bleed 'em dry, commander?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128431 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39512] = { ["id"] = 39512, ["name"] = "Secrets of the Shadow Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39512 }, ["description"] = "Gul'dan be growin' his Shadow Council like a spider spin a web. But some of this new blood, they not so smart. They write down the secrets but don't burn 'em. Catch his minions out in the open and bring their secrets back to me! You find them workin' with the arakkoa in da Ruins of Kra'nak or atop the Throne of Kil'jaeden.", ["objectivesText"] = "Collect 20 Shadow Council Missives from shadow council representatives in the Ruins of Kra'nak or the Throne of Kil'jaeden. Progress: You find anything, commander?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128432 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39513] = { ["id"] = 39513, ["name"] = "Disarming Sha'naar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39513 }, ["description"] = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals used to channel their magics. Now demons be lootin' the place. We gotta keep those crystals out of demonic hands, commander! Attack the mines behind the temple and grab them crystals.", ["objectivesText"] = "Collect 8 Unrefined Draenic Crystals from the mines located within the Temple of Sha'naar in Tanaan Jungle . Progress: What you find up there, commander?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128433 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39514] = { ["id"] = 39514, ["name"] = "Harnessing Their Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39514 }, ["description"] = "Ol' Grommash Hellscream found a way to weaponize the gronn. Vol'jin wants to know how. Travel to the Iron Front and kill one of them big beasties, then bring back its war harness. You might be needin' help.", ["objectivesText"] = "Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle . Progress: Did you break one?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128434 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39519] = { ["id"] = 39519, ["name"] = "Demonslayer of Tanaan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39519 }, ["description"] = "Look to the north, <class>. The sky is turning a sickly green. Gul'dan's summoning portals are not yet at full strength, but already the stench of demon is on the wind. Slay them, <name>. Destroy as many beasts as you can before they find a way to Azeroth. The Temple of Sha'naar is infested, as is the Throne of Kil'jaeden, although you may find others wandering about the jungle.", ["objectivesText"] = "Slay 20 demons in Tanaan Jungle . Progress: How many demons were slain by your capable hands?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39526] = { ["id"] = 39526, ["name"] = "Pressing the Attack", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39526 }, ["description"] = "We got Gul'dan's minions on the run, commander! If you be feelin' it, we should put some pressure on some of his other strongholds as well.", ["objectivesText"] = "Complete 2 bonus objective areas within Tanaan Jungle . Progress: How goes the fight?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39529] = { ["id"] = 39529, ["name"] = "Tooth and Claw", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39529 }, ["description"] = "Beyond the meager shelter of these fortress walls, the jungle closes in. Can you feel it? That is the untamed wilderness, <class>, calling forth our primal instincts. There is no better way to feel alive than to court death. Join me in the hunt, <name>! Collect teeth from the wild beasts. The ravagers in Thornmire, the raptors in Zorammarsh - even the sea creatures along the strand and the little podling plants themselves all have teeth. Bring them to me!", ["objectivesText"] = "Collect 100 Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle . Progress: I trust the hunt goes well?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 124099, 128438, 194369 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39532] = { ["id"] = 39532, ["name"] = "Bringing Down the Iron Horde", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39532 }, ["description"] = "Ever since the fall of Blackrock Foundry, Gul'dan has been turning the Iron Horde into... something worse. The orcs who once flocked to Grommash's banner, through either fear or thirst for revenge, are now embracing the fel. Wade into the battlefields of Tanaan and lay waste to Gul'dan's forces. Orc or fel orc makes no difference. Gut what remains of the Iron Horde!", ["objectivesText"] = "Slay 25 Iron Horde orcs in Tanaan Jungle . Progress: Feel no remorse for the fallen, <name>. They made their choice.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39565] = { ["id"] = 39565, ["name"] = "Rumble in the Jungle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39565 }, ["description"] = "Dem fancy cat-men gotta be shown who is da boss 'round dese parts. Kill all their champions, and ya will earn da respect of all creatures in da jungle. Y'gonna need dese totems to draw dem out.", ["objectivesText"] = "Defeat the three arena champions of Fangri'la. Progress: No lie mon - if I'd had money on you coming back in one piece, I'd be out that money right now.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 46725, 124093, 124094, 124095, 124099, 128346, 137663 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92805, ["x"] = 0.552, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92805, ["x"] = 0.552, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39567] = { ["id"] = 39567, ["name"] = "Bloodied Blades of Zeth'Gol", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39567 }, ["description"] = "The Bleeding Hollow clan is infamous for their blood rituals. The brutes carve sigils into their flesh and create potions from the blood of their strongest warriors. The curved ceremonial blades they use have a power all their own. Gather some of these for me. We will deprive them of these weapons and learn something about our enemy at the same time.", ["objectivesText"] = "Collect 25 Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth'Gol. Progress: We draenei have had little contact with the Bleeding Hollow before this war. They were an insular clan living in one of the most hostile parts of Draenor.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128428 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39568] = { ["id"] = 39568, ["name"] = "A Little Wetwork", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39568 }, ["description"] = "The shattered remnants of the Iron Horde pour into Tanaan through Ironhold Harbor. If we knew more about their fleet we could dispatch countermeasures from your shipyard in Shadowmoon. Perhaps you could gather some naval intelligence for our cause?", ["objectivesText"] = "Collect 15 Iron Horde Naval Manifests from forces in Ironhold Harbor. Progress: The Prophet said it was always wise to know one's enemy before engaging.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128429 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39569] = { ["id"] = 39569, ["name"] = "Breaking Their Fel Bonds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39569 }, ["description"] = "Gul'dan's fel poison turns already ferocious orcs into hateful, vicious creatures with no soul. But were he here to guide us, Prophet Velen wouldn't give up on the whole race. If you could find samples of their blood, maybe we can reverse the process? You'll find fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden are the most densely populated.", ["objectivesText"] = "Collect 20 Vials of Fel Blood from fel orcs throughout Tanaan Jungle . Progress: Were you able to secure some blood samples? I will not inquire as to your methods, commander.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128431 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39570] = { ["id"] = 39570, ["name"] = "Secrets of the Shadow Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39570 }, ["description"] = "Gul'dan has been building a spy network for himself - the so-called \"Shadow Council\". As they struggle to control Tanaan, the Shadow Council has grown careless. Their members are out in the open, recruiting arakkoa at the Ruins of Kra'nak or summoning demons at the Throne of Kil'jaeden. Find members of the Shadow Council and acquire any intelligence they were foolish enough not to destroy!", ["objectivesText"] = "Collect 20 Shadow Council Missives from Shadow Council representatives in the Ruins of Kra'nak or the Throne of Kil'jaeden. Progress: What have you learned?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128432 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39571] = { ["id"] = 39571, ["name"] = "Disarming Sha'naar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39571 }, ["description"] = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals to power our arcane devices. Sadly, the temple is lost to us - we have been betrayed by the Sargerei. <name>, it is imperative that you venture into those mines and secure those crystals before the Sargerei use them in their demonic rituals. If you must kill our former brothers and sisters, so be it.", ["objectivesText"] = "Collect 8 Unrefined Draenic Crystals from the mines located within the Temple of Sha'naar in Tanaan Jungle . Progress: That temple was once a place of peace and solitude. I fear it is forever corupted.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128433 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39573] = { ["id"] = 39573, ["name"] = "Harnessing Their Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39573 }, ["description"] = "We have always believed that the primal creatures of Draenor could not be tamed. And yet, the Iron Horde found a way to weaponize the gronn. It would be to our advantage to learn how. Venture to the Iron Front, slay a Wargronn, and retrieve its harness. You may want to find help.", ["objectivesText"] = "Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle . Progress: Exarch Maladaar reports that the battlefield is in chaos. Were you able to persevere?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128434 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39574] = { ["id"] = 39574, ["name"] = "Pressing the Attack", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39574 }, ["description"] = "Gul'dan's minions are on the run, commander! If you have the strength, now would be an opportune time to press forward and assault some of his other strongholds.", ["objectivesText"] = "Complete 2 bonus objective areas within Tanaan Jungle . Progress: Be wary of the jungle, commander.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39581] = { ["id"] = 39581, ["name"] = "Demonslayer of Tanaan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39581 }, ["description"] = "Demons! Hate 'em! Gul'dan is spinning up more summoning portals with each passing hour. There's only one way to stem the tide, <name>. < Parvink smashes her gauntleted fist against her open palm.> Smash 'em! The Temple of Sha'naar is a good place to start, or head up to the Throne of Kil'jaeden if you're looking for a real challenge.", ["objectivesText"] = "Slay 20 demons in Tanaan Jungle . Progress: < Parvink looks at some hatch marks she scribbled on a scrap of paper.> I'm up to 17 demons killed today. You?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39582] = { ["id"] = 39582, ["name"] = "Tooth and Claw", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39582 }, ["description"] = "These wimps lugging wood around the jungle keep talking about how dangerous it is. You know, between the ravager den to the south or the raptors that stalk Zorammarsh - hey, even the beach creatures or podlings have teeth! What do you say you and I do a little hunting? Collect teeth from wild beasts. The bigger the beast, the more teeth. Meet me back here and we'll compare our haul!", ["objectivesText"] = "Collect 100 Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle . Progress: Ready to compare notes?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 111987, 124099, 128438, 194369 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39586] = { ["id"] = 39586, ["name"] = "Bringing Down the Iron Horde", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39586 }, ["description"] = "Ever since we humiliated 'em at Blackrock Foundry, the Iron Horde has been on the run. Gul'dan is converting them all into fel orcs, but I ain't scared. A bloodlusting orc is twice as strong but twice as stupid. Hey! Let's wade into the battlefields of Tanaan and lay waste to as many orcs as we can. Orc or fel orc - doesn't matter to me.", ["objectivesText"] = "Slay 25 Iron Horde orcs in Tanaan Jungle .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39601] = { ["id"] = 39601, ["name"] = "I Sunk Your Battleship", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["description"] = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde. We have heard reports from Tanaan that a new Alliance faction can supply us with the plans to build battleships. Head out there as soon as you can and investigate!", ["objectivesText"] = "Meet Vindicator Krethos at Lion's Watch in Tanaan Jungle. Progress: Any luck with those battleship plans?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127269, 128373, 128492 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 534, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39604] = { ["id"] = 39604, ["name"] = "I Sunk Your Battleship", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["description"] = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde. We have heard reports from Tanaan that a new Horde faction can supply us with the plans to build battleships. Head out there as soon as you can and investigate!", ["objectivesText"] = "Meet Shadow Hunter Denjai at Vol'mar in Tanaan Jungle. Progress: Any luck with those battleship plans?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 128373 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39648] = { ["id"] = 39648, ["name"] = "Where Are the Children?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39648 }, ["description"] = "The children have gone missing! That horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them! Our scouts have spotted him over in Frostfire Ridge .", ["objectivesText"] = "Save 6 Kidnapped Children. Progress: Thank you for all the help! Their families will be so happy to see them.", ["rewardGold"] = 292100, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39649] = { ["id"] = 39649, ["name"] = "Menacing Grumplings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39649 }, ["description"] = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus. If you're able to remove the threat I'm sure rescuing the children won't be much of a problem.", ["objectivesText"] = "Kill 8 Grumplings . Progress: Well that was fast! Grumpus is gonna have a hard time continuing his work without his minions. Take these. I had them specially crafted to withstand any climate. You never know what you'll run into out here in Draenor!", ["rewardGold"] = 341600, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128632, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39651] = { ["id"] = 39651, ["name"] = "Grumpus", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39651 }, ["description"] = "One of Draenor's oldest stories is the legend of Grumpus . The story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions. But Grumpus is no legend, he's real and he's taken our children! Please, you have to slay him!", ["objectivesText"] = "Slay Grumpus .", ["rewardGold"] = 292100, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675, 144339 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[39655] = { ["id"] = 39655, ["name"] = "If At First You Fail, Try Again!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39056, 39404, 39674, 39675, 39676 }, ["description"] = "Looks like that Submarine had a bit more firepower than we thought! They used First Strike to hit us before we even saw it coming. Losing ships is a part of naval battles, Commander. Luckily, we were prepared for this exact sort of situation. Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer. Head back here when the ship is complete, we will have a new mission ready for you.", ["objectivesText"] = "Meet Yanas Seastrike at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission. Progress: Get that replacement Destroyer built?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 13, ["flags"] = 0 } } },
