[39665] = { ["id"] = 39665, ["name"] = "A True Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39666 }, ["description"] = "Yes! Those are the blueprints I misplaced when I was fishing last week. These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships. This should let us break the naval blocade and expand our control of the Draenor seas.", ["objectivesText"] = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission. Progress: Get that equipment installed?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128256, 128260, 128264, 128265, 128373 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 15, ["flags"] = 0 } } },
[39666] = { ["id"] = 39666, ["name"] = "Equipping Our Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39665 }, ["description"] = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war. Find Salty Jorren down at the docks, he should be able to help us out.", ["objectivesText"] = "Meet Salty Jorren at the docks. Progress: Yes?", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260, 128274 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 14, ["flags"] = 0 } } },
[39668] = { ["id"] = 39668, ["name"] = "What Horrible Presents!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39668 }, ["description"] = "That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable. Take this spirit bomb . Toss it on some of Grumpus's unusual gifts and take them out for good! We're in this together, <name>. Now go and save the spirit of the holiday!", ["objectivesText"] = "Destroy 5 Unusual Gifts . Progress: Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what those were made of.", ["rewardGold"] = 341600, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39674] = { ["id"] = 39674, ["name"] = "If At First You Fail, Try Again!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39056, 39404, 39655, 39675, 39676 }, ["description"] = "Looks like that Submarine had a bit more firepower than we thought! They used First Strike to hit us before we even saw it coming. Losing ships is a part of naval battles, Commander. Luckily, we were prepared for this exact sort of situation. Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer. Head back here when the ship is complete, we will have a new mission ready for you.", ["objectivesText"] = "Meet Solog Roark at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission. Progress: Get that replacement Destroyer built?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 13, ["flags"] = 0 } } },
